// The Atlas graph: the one data model shared by the agents, the server and the UI.
//
// Edges always point from the thing that acts to the thing it depends on
// (frontend → api, api → database, worker → queue). Every edge must carry
// evidence: a file, line and code snippet that proves the dependency exists.
import { z } from "zod";

export const NODE_KINDS = [
  "client", // browser, mobile app, CLI user
  "frontend", // web app pages/components
  "api", // HTTP route handlers / controllers
  "service", // business-logic modules
  "worker", // background jobs, consumers, cron
  "database",
  "cache",
  "queue",
  "storage", // object/file storage
  "external", // third-party APIs and SaaS
] as const;
export type NodeKind = (typeof NODE_KINDS)[number];

export const EDGE_KINDS = [
  "http", // HTTP/fetch/REST/GraphQL call
  "rpc", // gRPC / tRPC / internal RPC
  "sql", // database query or ORM call
  "cache", // cache read/write
  "publish", // enqueue / publish a message
  "consume", // subscribe / process messages (worker → queue)
  "sdk", // third-party SDK call
  "call", // in-process function/module call
  "webhook", // inbound callback from a third party
] as const;
export type EdgeKind = (typeof EDGE_KINDS)[number];

export const FileRefSchema = z.object({
  path: z.string(),
  line: z.number().int().positive().optional(),
});
export type FileRef = z.infer<typeof FileRefSchema>;

export const EvidenceSchema = z.object({
  path: z.string(),
  line: z.number().int().positive(),
  snippet: z.string(),
});
export type Evidence = z.infer<typeof EvidenceSchema>;

export const NodeSchema = z.object({
  id: z.string(),
  kind: z.enum(NODE_KINDS),
  label: z.string(),
  summary: z.string(),
  tech: z.string().optional(),
  files: z.array(FileRefSchema).default([]),
  /** Short facts such as endpoints ("POST /api/orders") or tables. */
  details: z.array(z.string()).default([]),
});
export type AtlasNode = z.infer<typeof NodeSchema>;

export const EdgeSchema = z.object({
  id: z.string(),
  from: z.string(),
  to: z.string(),
  kind: z.enum(EDGE_KINDS),
  label: z.string(),
  evidence: z.array(EvidenceSchema).min(1),
});
export type AtlasEdge = z.infer<typeof EdgeSchema>;

export const FlowStepSchema = z.object({
  edge: z.string(),
  note: z.string(),
});
export type FlowStep = z.infer<typeof FlowStepSchema>;

export const FlowSchema = z.object({
  id: z.string(),
  name: z.string(),
  trigger: z.string(),
  description: z.string(),
  steps: z.array(FlowStepSchema).min(1),
});
export type AtlasFlow = z.infer<typeof FlowSchema>;

export const RepoRefSchema = z.object({
  /** Stable id used for storage, e.g. "prabhat-gp__chai-commerce". */
  key: z.string(),
  source: z.enum(["github", "local"]),
  /** Display name, e.g. "prabhat-gp/chai-commerce". */
  name: z.string(),
  /** Clone URL (github) or absolute path (local). */
  location: z.string(),
  webUrl: z.string().optional(),
});
export type RepoRef = z.infer<typeof RepoRefSchema>;

export const AgentRunStatSchema = z.object({
  agent: z.string(),
  durationMs: z.number(),
  inputTokens: z.number().optional(),
  outputTokens: z.number().optional(),
});
export type AgentRunStat = z.infer<typeof AgentRunStatSchema>;

export const GraphStatsSchema = z.object({
  files: z.number(),
  tokens: z.number(),
  edgesProposed: z.number(),
  edgesVerified: z.number(),
  edgesDropped: z.number(),
  nodesDropped: z.number(),
  model: z.string(),
  durationMs: z.number(),
  agents: z.array(AgentRunStatSchema).default([]),
});
export type GraphStats = z.infer<typeof GraphStatsSchema>;

export const GraphSchema = z.object({
  version: z.literal(1),
  repo: RepoRefSchema,
  sha: z.string(),
  branch: z.string().optional(),
  generatedAt: z.string(),
  /** "full" = mapped from scratch, "incremental" = patched from a push. */
  mode: z.enum(["full", "incremental"]).default("full"),
  stack: z.array(z.string()),
  summary: z.string(),
  nodes: z.array(NodeSchema),
  edges: z.array(EdgeSchema),
  flows: z.array(FlowSchema),
  stats: GraphStatsSchema,
});
export type AtlasGraph = z.infer<typeof GraphSchema>;

// ---------------------------------------------------------------------------
// Drift: what changed in the architecture between two commits.

export const SEVERITIES = ["info", "warning", "critical"] as const;
export type Severity = (typeof SEVERITIES)[number];

export const DriftFindingSchema = z.object({
  id: z.string(),
  severity: z.enum(SEVERITIES),
  /** Rule id for deterministic findings ("layering.frontend-to-data"), or "reviewer". */
  rule: z.string(),
  title: z.string(),
  detail: z.string(),
  nodeIds: z.array(z.string()).default([]),
  edgeIds: z.array(z.string()).default([]),
  source: z.enum(["rule", "reviewer"]),
});
export type DriftFinding = z.infer<typeof DriftFindingSchema>;

export const CommitInfoSchema = z.object({
  sha: z.string(),
  message: z.string(),
  author: z.string().optional(),
});
export type CommitInfo = z.infer<typeof CommitInfoSchema>;

export const DriftReportSchema = z.object({
  id: z.string(),
  repoKey: z.string(),
  repoName: z.string(),
  fromSha: z.string(),
  toSha: z.string(),
  at: z.string(),
  commits: z.array(CommitInfoSchema).default([]),
  changedFiles: z.array(z.string()).default([]),
  added: z.object({ nodes: z.array(NodeSchema), edges: z.array(EdgeSchema) }),
  removed: z.object({ nodes: z.array(NodeSchema), edges: z.array(EdgeSchema) }),
  brokenFlows: z.array(z.string()).default([]),
  findings: z.array(DriftFindingSchema),
  summary: z.string(),
  maxSeverity: z.enum(["none", ...SEVERITIES]),
});
export type DriftReport = z.infer<typeof DriftReportSchema>;

// ---------------------------------------------------------------------------
// Helpers shared by server and UI.

/** Semantic identity of an edge, used to diff graphs across commits. */
export function edgeKey(e: Pick<AtlasEdge, "from" | "to" | "kind">): string {
  return `${e.from}|${e.to}|${e.kind}`;
}

export function severityRank(s: Severity | "none"): number {
  return s === "critical" ? 3 : s === "warning" ? 2 : s === "info" ? 1 : 0;
}

export function shortSha(sha: string): string {
  return sha.slice(0, 7);
}

// Repository access: resolve a user-supplied repo, clone/pull it, and read the
// files exactly as they are at a commit (via git objects, not the working tree,
// so a map is always reproducible for its sha).
import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdir } from "node:fs/promises";
import path from "node:path";
import { promisify } from "node:util";
import type { CommitInfo, RepoRef } from "../shared/graph";
import { dataDir } from "./store";

const exec = promisify(execFile);

export interface RepoFile {
  path: string;
  content: string;
  lines: number;
  /** Rough token estimate (chars / 4). */
  tokens: number;
}

export interface RepoSnapshot {
  repo: RepoRef;
  sha: string;
  branch?: string;
  /** Every tracked path at this sha, including ones we skip reading. */
  tree: string[];
  /** Source files worth analysing, with contents. */
  files: RepoFile[];
  totalTokens: number;
}

export interface ChangedFile {
  path: string;
  status: "added" | "modified" | "deleted" | "renamed";
  previousPath?: string;
  /** Unified diff for this file (may be truncated). */
  patch: string;
}

const MAX_FILE_BYTES = 120_000;
const MAX_PATCH_CHARS = 12_000;

const SOURCE_EXT = new Set([
  ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".py", ".go", ".java", ".kt", ".rb", ".rs",
  ".php", ".cs", ".swift", ".scala", ".ex", ".exs", ".sql", ".prisma", ".graphql", ".gql",
  ".proto", ".yml", ".yaml", ".toml", ".vue", ".svelte",
]);
const SOURCE_NAMES = new Set([
  "package.json", "dockerfile", "docker-compose.yml", "docker-compose.yaml", "compose.yml",
  "compose.yaml", "procfile", "requirements.txt", "pyproject.toml", "go.mod", "cargo.toml",
  "gemfile", "pom.xml", "build.gradle", ".env.example", "serverless.yml", "vercel.json",
  "netlify.toml", "fly.toml", "render.yaml", "wrangler.toml", "readme.md",
]);
const SKIP_DIRS = /(^|\/)(node_modules|dist|build|out|\.next|\.nuxt|coverage|vendor|target|\.git|\.venv|venv|__pycache__|\.turbo|\.cache|public|static|assets|fixtures|__snapshots__)(\/|$)/i;
const SKIP_FILES = /(\.min\.(js|css)$|\.map$|\.lock$|-lock\.(json|yaml)$|\.d\.ts$|\.(test|spec)\.[jt]sx?$|(^|\/)(package-lock\.json|pnpm-lock\.yaml|yarn\.lock)$)/i;

export function isSourcePath(p: string): boolean {
  if (SKIP_DIRS.test(p) || SKIP_FILES.test(p)) return false;
  const base = path.posix.basename(p).toLowerCase();
  if (SOURCE_NAMES.has(base)) return true;
  return SOURCE_EXT.has(path.posix.extname(base));
}

async function git(cwd: string, args: string[], opts: { input?: string } = {}): Promise<string> {
  const { stdout } = await exec("git", args, {
    cwd,
    maxBuffer: 256 * 1024 * 1024,
    env: { ...process.env, GIT_TERMINAL_PROMPT: "0" },
    ...(opts.input !== undefined ? { input: opts.input } : {}),
  } as Parameters<typeof exec>[2]);
  return stdout.toString();
}

/**
 * Turn user input into a RepoRef. Accepts:
 *   https://github.com/owner/name(.git), github.com/owner/name, owner/name,
 *   an absolute local path, or "local:/abs/path".
 */
export function resolveRepo(input: string): RepoRef {
  const raw = input.trim().replace(/\/+$/, "");
  const localPath = raw.startsWith("local:") ? raw.slice(6) : raw;
  if (path.isAbsolute(localPath) || localPath.startsWith("~")) {
    const abs = localPath.startsWith("~") ? path.join(process.env.HOME ?? "", localPath.slice(1)) : localPath;
    const name = path.basename(abs);
    return { key: `local__${slug(name)}`, source: "local", name, location: abs };
  }
  const m = raw.match(/^(?:https?:\/\/)?(?:www\.)?(?:github\.com[/:])?([\w.-]+)\/([\w.-]+?)(?:\.git)?(?:\/.*)?$/i);
  if (!m) throw new Error(`Not a GitHub repo or absolute path: "${input}"`);
  const [, owner, name] = m;
  return {
    key: `${slug(owner)}__${slug(name)}`,
    source: "github",
    name: `${owner}/${name}`,
    location: `https://github.com/${owner}/${name}.git`,
    webUrl: `https://github.com/${owner}/${name}`,
  };
}

function slug(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9._-]+/g, "-");
}

/** Local checkout directory for a repo (the path itself for local repos). */
export function repoDir(repo: RepoRef): string {
  return repo.source === "local" ? repo.location : path.join(dataDir(), "repos", repo.key);
}

/**
 * Make sure we have the repo locally and up to date. Returns the commit to map:
 * `sha` if given (must exist after fetching), else the tip of `branch`/HEAD.
 */
export async function syncRepo(
  repo: RepoRef,
  opts: { branch?: string; sha?: string } = {},
): Promise<{ dir: string; sha: string; branch?: string }> {
  const dir = repoDir(repo);
  if (repo.source === "local") {
    if (!existsSync(path.join(dir, ".git"))) throw new Error(`${dir} is not a git repository`);
    const sha = opts.sha ?? (await git(dir, ["rev-parse", "HEAD"])).trim();
    const branch = (await git(dir, ["rev-parse", "--abbrev-ref", "HEAD"]).catch(() => "")).trim() || undefined;
    return { dir, sha, branch };
  }

  if (!existsSync(path.join(dir, ".git"))) {
    await mkdir(path.dirname(dir), { recursive: true });
    await exec("git", ["clone", "--quiet", "--no-tags", "--filter=blob:none", repo.location, dir], {
      maxBuffer: 64 * 1024 * 1024,
      env: { ...process.env, GIT_TERMINAL_PROMPT: "0" },
    }).catch((err: Error) => {
      throw new Error(`Could not clone ${repo.name}. Is it public? (${err.message.split("\n")[0]})`);
    });
  } else {
    await git(dir, ["fetch", "--quiet", "--no-tags", "origin"]);
  }

  let branch = opts.branch;
  if (!branch) {
    const head = await git(dir, ["symbolic-ref", "--short", "refs/remotes/origin/HEAD"]).catch(() => "origin/main");
    branch = head.trim().replace(/^origin\//, "") || "main";
  }
  const sha = opts.sha ?? (await git(dir, ["rev-parse", `origin/${branch}`])).trim();
  // Fail loudly if a webhook names a commit we can't see.
  await git(dir, ["cat-file", "-e", `${sha}^{commit}`]);
  return { dir, sha, branch };
}

/** Read the analysable source files at `sha` straight from git objects. */
export async function snapshotRepo(
  repo: RepoRef,
  dir: string,
  sha: string,
  branch?: string,
): Promise<RepoSnapshot> {
  const tree = (await git(dir, ["ls-tree", "-r", "-l", "--full-tree", sha]))
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      // "<mode> <type> <object> <size>\t<path>"
      const [meta, p] = line.split("\t");
      const parts = meta.trim().split(/\s+/);
      return { path: p, object: parts[2], size: Number(parts[3]) || 0, type: parts[1] };
    })
    .filter((e) => e.type === "blob");

  const wanted = tree.filter((e) => e.size <= MAX_FILE_BYTES && isSourcePath(e.path));
  const contents = await readBlobs(dir, wanted.map((e) => e.object));

  const files: RepoFile[] = [];
  wanted.forEach((e, i) => {
    const content = contents[i];
    if (content === undefined || content.includes("\u0000")) return; // binary
    files.push({
      path: e.path,
      content,
      lines: content.split("\n").length,
      tokens: Math.ceil(content.length / 4),
    });
  });

  return {
    repo,
    sha,
    branch,
    tree: tree.map((e) => e.path),
    files,
    totalTokens: files.reduce((n, f) => n + f.tokens, 0),
  };
}

/** Batch-read blobs with one `git cat-file --batch` process. */
async function readBlobs(dir: string, objects: string[]): Promise<(string | undefined)[]> {
  if (objects.length === 0) return [];
  const out = await new Promise<Buffer>((resolve, reject) => {
    const child = execFile("git", ["cat-file", "--batch"], { cwd: dir, encoding: "buffer", maxBuffer: 512 * 1024 * 1024 }, (err, stdout) =>
      err ? reject(err) : resolve(stdout as unknown as Buffer),
    );
    child.stdin?.end(objects.join("\n") + "\n");
  });
  const result: (string | undefined)[] = [];
  let pos = 0;
  for (let i = 0; i < objects.length; i++) {
    const nl = out.indexOf(0x0a, pos);
    if (nl < 0) break;
    const header = out.subarray(pos, nl).toString();
    pos = nl + 1;
    const m = header.match(/^\S+ blob (\d+)$/);
    if (!m) {
      result.push(undefined); // "missing"
      continue;
    }
    const size = Number(m[1]);
    result.push(out.subarray(pos, pos + size).toString("utf8"));
    pos += size + 1; // trailing newline
  }
  return result;
}

/** Files changed between two commits, with per-file unified diffs. */
export async function diffCommits(dir: string, fromSha: string, toSha: string): Promise<ChangedFile[]> {
  const nameStatus = await git(dir, ["diff", "--name-status", "-M", fromSha, toSha]);
  const changed: ChangedFile[] = [];
  for (const line of nameStatus.split("\n").filter(Boolean)) {
    const [code, a, b] = line.split("\t");
    const status = code.startsWith("A") ? "added" : code.startsWith("D") ? "deleted" : code.startsWith("R") ? "renamed" : "modified";
    const p = status === "renamed" ? b : a;
    if (!isSourcePath(p) && !(status === "renamed" && isSourcePath(a))) continue;
    let patch = await git(dir, ["diff", "--unified=3", fromSha, toSha, "--", ...(status === "renamed" ? [a, b] : [p])]);
    if (patch.length > MAX_PATCH_CHARS) patch = patch.slice(0, MAX_PATCH_CHARS) + "\n… (diff truncated)";
    changed.push({ path: p, status, ...(status === "renamed" ? { previousPath: a } : {}), patch });
  }
  return changed;
}

/** Commits in (fromSha, toSha], newest first. */
export async function listCommits(dir: string, fromSha: string, toSha: string): Promise<CommitInfo[]> {
  const out = await git(dir, ["log", "--format=%H%x1f%an%x1f%s", `${fromSha}..${toSha}`]).catch(() => "");
  return out
    .split("\n")
    .filter(Boolean)
    .map((l) => {
      const [sha, author, message] = l.split("\x1f");
      return { sha, author, message };
    });
}

/** Prefix every line with its 1-based number: how agents cite evidence. */
export function numberLines(content: string): string {
  const lines = content.split("\n");
  const width = String(lines.length).length;
  return lines.map((l, i) => `${String(i + 1).padStart(width, " ")}| ${l}`).join("\n");
}

// Contract between the Atlas server and its agent "brain".
//
// The brain only *proposes*: every edge it returns is checked afterwards by
// src/server/graph/verify.ts, which drops anything whose evidence snippet is
// not literally present in the repo. So the brain must cite, never invent.
import type {
  AgentRunStat,
  AtlasEdge,
  AtlasFlow,
  AtlasGraph,
  AtlasNode,
  DriftFinding,
} from "../../shared/graph";
import type { ChangedFile, RepoSnapshot } from "../repo";

export type AgentName = "scout" | "reader" | "cartographer" | "tracer" | "reviewer";

export interface ProgressEvent {
  agent: AgentName | "pipeline";
  phase: "start" | "progress" | "done" | "error";
  /** Human-readable line shown live in the UI, e.g. "Reader 2/4 · api/routes (6 files)". */
  message: string;
  /** Small counters for the UI, e.g. { endpoints: 14, edges: 9 }. */
  data?: Record<string, number | string>;
}
export type OnProgress = (event: ProgressEvent) => void;

export interface BrainOptions {
  /** Defaults to process.env.ATLAS_MODEL ?? "gpt-6.1-sol". */
  model?: string;
  onProgress?: OnProgress;
  signal?: AbortSignal;
}

/** An edge as proposed by agents: unverified evidence, draft id. */
export type DraftEdge = AtlasEdge;
/** A flow whose steps reference DraftEdge ids. */
export type DraftFlow = AtlasFlow;

export interface DraftGraph {
  stack: string[];
  summary: string;
  nodes: AtlasNode[];
  edges: DraftEdge[];
  flows: DraftFlow[];
  agentStats: AgentRunStat[];
}

export interface ReviewInput {
  /** The verified graph at the previous commit. */
  graph: AtlasGraph;
  /** Files at the new commit. */
  snapshot: RepoSnapshot;
  /** What changed between the two commits. */
  changes: ChangedFile[];
}

export interface ReviewResult {
  /** Components introduced by the change (ids must not clash with existing ones). */
  addNodes: AtlasNode[];
  /** Dependencies introduced by the change; evidence must point into changed files. */
  addEdges: DraftEdge[];
  /** Ids of existing edges the change removes. */
  removeEdgeIds: string[];
  /** Architectural observations about the change, most important first. */
  findings: Array<Omit<DriftFinding, "id" | "source" | "rule">>;
  /** One or two sentences: what changed architecturally. */
  summary: string;
  agentStats: AgentRunStat[];
}

export interface TraceInput {
  graph: AtlasGraph;
  question: string;
}

export interface TraceResult {
  /** Set when an existing flow in graph.flows answers the question. */
  flowId: string | null;
  /** Otherwise a new flow; steps must reference existing graph edge ids, in order. */
  flow: DraftFlow | null;
  /** Short plain-language answer for the chat. */
  answer: string;
  agentStats: AgentRunStat[];
}

/** What src/server/brain/index.ts must export. */
export interface Brain {
  mapRepository(snapshot: RepoSnapshot, opts?: BrainOptions): Promise<DraftGraph>;
  reviewChanges(input: ReviewInput, opts?: BrainOptions): Promise<ReviewResult>;
  traceQuestion(input: TraceInput, opts?: BrainOptions): Promise<TraceResult>;
}

// Tiny JSON-file persistence under .atlas/ — graphs per commit, repo index,
// drift reports and MCP Events subscriptions. Writes are atomic (tmp + rename)
// and reads are cached in memory, which is plenty for one Atlas server.
import { existsSync, readFileSync } from "node:fs";
import { mkdir, readdir, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  type AtlasGraph,
  type DriftReport,
  GraphSchema,
  type RepoRef,
} from "../shared/graph";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

export function dataDir(): string {
  return process.env.ATLAS_DATA_DIR ?? path.join(ROOT, ".atlas");
}

const cache = new Map<string, unknown>();

function readJson<T>(file: string, fallback: T): T {
  if (cache.has(file)) return cache.get(file) as T;
  const value = existsSync(file) ? (JSON.parse(readFileSync(file, "utf8")) as T) : fallback;
  cache.set(file, value);
  return value;
}

async function writeJson(file: string, value: unknown): Promise<void> {
  cache.set(file, value);
  await mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  await writeFile(tmp, JSON.stringify(value, null, 2));
  await rename(tmp, file);
}

// ---------------------------------------------------------------- repos

export interface RepoRecord {
  repo: RepoRef;
  branch?: string;
  latestSha?: string;
  mappedAt?: string;
  /** Last sha whose drift was reviewed (or the first mapped sha). */
  reviewedSha?: string;
}

const reposFile = () => path.join(dataDir(), "repos.json");

export function listRepos(): RepoRecord[] {
  return Object.values(readJson<Record<string, RepoRecord>>(reposFile(), {})).sort((a, b) =>
    (b.mappedAt ?? "").localeCompare(a.mappedAt ?? ""),
  );
}

export function getRepo(key: string): RepoRecord | undefined {
  return readJson<Record<string, RepoRecord>>(reposFile(), {})[key];
}

/** Find a repo by key, "owner/name", or a fuzzy suffix ("chai-commerce"). */
export function findRepo(query: string | undefined): RepoRecord | undefined {
  const all = listRepos();
  if (!query) return all[0];
  const q = query.trim().toLowerCase().replace(/\.git$/, "").replace(/\/+$/, "");
  return (
    all.find((r) => r.repo.key === q) ??
    all.find((r) => r.repo.name.toLowerCase() === q) ??
    all.find((r) => q.endsWith(r.repo.name.toLowerCase())) ??
    all.find((r) => r.repo.name.toLowerCase().endsWith(`/${q}`) || r.repo.name.toLowerCase() === q.split("/").pop())
  );
}

export async function upsertRepo(key: string, patch: Partial<RepoRecord> & { repo: RepoRef }): Promise<RepoRecord> {
  const all = readJson<Record<string, RepoRecord>>(reposFile(), {});
  const next = { ...all[key], ...patch };
  await writeJson(reposFile(), { ...all, [key]: next });
  return next;
}

// ---------------------------------------------------------------- graphs

const graphFile = (key: string, sha: string) => path.join(dataDir(), "graphs", key, `${sha}.json`);

export async function saveGraph(graph: AtlasGraph): Promise<void> {
  await writeJson(graphFile(graph.repo.key, graph.sha), graph);
}

export function loadGraph(key: string, sha?: string): AtlasGraph | undefined {
  const target = sha ?? getRepo(key)?.latestSha;
  if (!target) return undefined;
  const file = graphFile(key, target);
  if (!existsSync(file) && !cache.has(file)) return undefined;
  return GraphSchema.parse(readJson<unknown>(file, undefined));
}

export async function listGraphShas(key: string): Promise<string[]> {
  const dir = path.join(dataDir(), "graphs", key);
  if (!existsSync(dir)) return [];
  return (await readdir(dir)).filter((f) => f.endsWith(".json")).map((f) => f.slice(0, -5));
}

// ---------------------------------------------------------------- drift

const driftFile = (key: string) => path.join(dataDir(), "drift", `${key}.json`);

export function listDrift(key: string): DriftReport[] {
  return readJson<DriftReport[]>(driftFile(key), []);
}

export async function appendDrift(report: DriftReport): Promise<void> {
  const all = listDrift(report.repoKey);
  await writeJson(driftFile(report.repoKey), [report, ...all].slice(0, 100));
}

// ---------------------------------------------------------------- generic docs

/** Small named JSON documents (MCP Events subscriptions, counters, …). */
export function readDoc<T>(name: string, fallback: T): T {
  return readJson<T>(path.join(dataDir(), `${name}.json`), fallback);
}

export async function writeDoc(name: string, value: unknown): Promise<void> {
  await writeJson(path.join(dataDir(), `${name}.json`), value);
}

// "Atlas never draws an arrow it can't cite."
//
// Agents propose edges with evidence (path, line, snippet). This module checks
// every snippet against the actual file contents at the mapped commit, fixes
// slightly-off line numbers, and drops edges with no surviving evidence.
import {
  type AtlasEdge,
  type AtlasFlow,
  type AtlasGraph,
  type AtlasNode,
  type Evidence,
  type GraphStats,
  NodeSchema,
  type RepoRef,
  edgeKey,
} from "../../shared/graph";
import type { DraftEdge, DraftGraph } from "../brain/types";
import type { RepoSnapshot } from "../repo";

const MAX_EVIDENCE_PER_EDGE = 5;
const MIN_SNIPPET_CHARS = 6;
const NEAR_WINDOW = 6;

export interface DroppedEdge {
  from: string;
  to: string;
  kind: string;
  label: string;
  reason: "no-evidence" | "unknown-node" | "self-loop";
}

/** Fast lookup over a snapshot's files. */
export class FileIndex {
  private byPath = new Map<string, { raw: string[]; norm: string[] }>();
  private paths: string[];

  constructor(snapshot: Pick<RepoSnapshot, "files">) {
    for (const f of snapshot.files) {
      const raw = f.content.split("\n");
      this.byPath.set(f.path, { raw, norm: raw.map(normalize) });
    }
    this.paths = [...this.byPath.keys()];
  }

  has(path: string): boolean {
    return this.byPath.has(path);
  }

  /** Resolve a possibly sloppy path ("./src/x.ts", "x.ts") to a real one. */
  resolve(p: string): string | undefined {
    const clean = p.trim().replace(/^\.?\/+/, "").replace(/\\/g, "/");
    if (this.byPath.has(clean)) return clean;
    const suffix = this.paths.filter((q) => q.endsWith(`/${clean}`));
    if (suffix.length === 1) return suffix[0];
    return undefined;
  }

  /** Whether `p` is a file or a directory prefix of some file. */
  exists(p: string): boolean {
    const clean = p.trim().replace(/^\.?\/+/, "").replace(/\/+$/, "");
    if (this.resolve(clean)) return true;
    return this.paths.some((q) => q.startsWith(`${clean}/`));
  }

  /** Verify one evidence item; returns the corrected evidence or undefined. */
  verify(ev: Evidence): Evidence | undefined {
    const path = this.resolve(ev.path);
    if (!path) return undefined;
    const file = this.byPath.get(path)!;
    const anchors = snippetAnchors(ev.snippet);
    if (anchors.length === 0) return undefined;

    for (const anchor of anchors) {
      const hit = findLine(file.norm, anchor, ev.line);
      if (hit !== undefined) {
        return { path, line: hit + 1, snippet: file.raw[hit].trim().slice(0, 240) };
      }
    }
    return undefined;
  }
}

/** Collapse whitespace and unify quotes so trivial differences don't fail a match. */
function normalize(s: string): string {
  return s.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/`/g, "'").replace(/"/g, "'").replace(/\s+/g, " ").trim();
}

/** Lines of the snippet worth matching on, longest first, with any "12| " prefix removed. */
function snippetAnchors(snippet: string): string[] {
  return snippet
    .split("\n")
    .map((l) => normalize(l.replace(/^\s*\d+\s*\|\s?/, "")))
    .filter((l) => l.length >= MIN_SNIPPET_CHARS && !/^[{}()[\];,]+$/.test(l))
    .sort((a, b) => b.length - a.length)
    .slice(0, 3);
}

function findLine(norm: string[], anchor: string, hintLine: number): number | undefined {
  const hint = Math.max(0, Math.min(norm.length - 1, hintLine - 1));
  for (let d = 0; d <= NEAR_WINDOW; d++) {
    for (const i of d === 0 ? [hint] : [hint - d, hint + d]) {
      if (i >= 0 && i < norm.length && norm[i].includes(anchor)) return i;
    }
  }
  const i = norm.findIndex((l) => l.includes(anchor));
  return i >= 0 ? i : undefined;
}

/** Stable, readable edge id derived from its semantics, so ids survive re-maps. */
export function stableEdgeId(e: Pick<AtlasEdge, "from" | "to" | "kind">): string {
  return `${e.from}--${e.kind}--${e.to}`;
}

function dedupeEvidence(items: Evidence[]): Evidence[] {
  const seen = new Set<string>();
  const out: Evidence[] = [];
  for (const ev of items) {
    const k = `${ev.path}:${ev.line}`;
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(ev);
  }
  return out.slice(0, MAX_EVIDENCE_PER_EDGE);
}

function mergeLabels(a: string, b: string): string {
  const parts = [...new Set([...a.split(" · "), ...b.split(" · ")].map((s) => s.trim()).filter(Boolean))];
  return parts.length > 3 ? `${parts.slice(0, 3).join(" · ")} +${parts.length - 3}` : parts.join(" · ");
}

export interface VerifiedEdges {
  edges: AtlasEdge[];
  /** draft edge id → final edge id */
  idMap: Map<string, string>;
  dropped: DroppedEdge[];
}

/**
 * Verify draft edges against the index. Edges that share from/to/kind are merged
 * (evidence and labels combined) under one stable id.
 */
export function verifyEdges(drafts: DraftEdge[], nodeIds: Set<string>, index: FileIndex): VerifiedEdges {
  const byKey = new Map<string, AtlasEdge>();
  const idMap = new Map<string, string>();
  const dropped: DroppedEdge[] = [];

  for (const d of drafts) {
    const base = { from: d.from, to: d.to, kind: d.kind, label: d.label };
    if (d.from === d.to) {
      dropped.push({ ...base, reason: "self-loop" });
      continue;
    }
    if (!nodeIds.has(d.from) || !nodeIds.has(d.to)) {
      dropped.push({ ...base, reason: "unknown-node" });
      continue;
    }
    const evidence = d.evidence.map((ev) => index.verify(ev)).filter((ev): ev is Evidence => !!ev);
    if (evidence.length === 0) {
      dropped.push({ ...base, reason: "no-evidence" });
      continue;
    }
    const key = edgeKey(d);
    const existing = byKey.get(key);
    if (existing) {
      existing.evidence = dedupeEvidence([...existing.evidence, ...evidence]);
      existing.label = mergeLabels(existing.label, d.label);
      idMap.set(d.id, existing.id);
    } else {
      const id = stableEdgeId(d);
      byKey.set(key, { id, from: d.from, to: d.to, kind: d.kind, label: d.label.trim(), evidence: dedupeEvidence(evidence) });
      idMap.set(d.id, id);
    }
  }
  return { edges: [...byKey.values()], idMap, dropped };
}

/** Rewrite flow steps through an id map, dropping steps whose edge vanished. */
export function remapFlows(flows: AtlasFlow[], idMap: Map<string, string>, edgeIds: Set<string>): AtlasFlow[] {
  const seen = new Set<string>();
  const out: AtlasFlow[] = [];
  for (const f of flows) {
    const steps = f.steps
      .map((s) => ({ ...s, edge: idMap.get(s.edge) ?? s.edge }))
      .filter((s) => edgeIds.has(s.edge))
      // a merged edge can appear twice in a row; keep the first
      .filter((s, i, arr) => i === 0 || arr[i - 1].edge !== s.edge);
    if (steps.length === 0) continue;
    let id = slugId(f.id || f.name);
    while (seen.has(id)) id = `${id}-2`;
    seen.add(id);
    out.push({ ...f, id, steps });
  }
  return out;
}

function slugId(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "flow";
}

/** Clean up agent-proposed nodes: valid shape, unique ids, real file refs. */
export function cleanNodes(nodes: AtlasNode[], index: FileIndex): AtlasNode[] {
  const seen = new Set<string>();
  const out: AtlasNode[] = [];
  for (const raw of nodes) {
    const parsed = NodeSchema.safeParse(raw);
    if (!parsed.success) continue;
    const n = parsed.data;
    const id = slugId(n.id);
    if (seen.has(id)) continue;
    seen.add(id);
    const files = n.files
      .map((f) => ({ ...f, path: index.resolve(f.path) ?? f.path.replace(/^\.?\/+/, "").replace(/\/+$/, "") }))
      .filter((f) => index.exists(f.path));
    out.push({ ...n, id, files, details: [...new Set(n.details)].slice(0, 12) });
  }
  return out;
}

export interface VerifyMeta {
  repo: RepoRef;
  sha: string;
  branch?: string;
  model: string;
  durationMs: number;
}

export interface VerifyResult {
  graph: AtlasGraph;
  dropped: DroppedEdge[];
}

/** Turn an agent DraftGraph into a verified AtlasGraph. */
export function verifyDraft(draft: DraftGraph, snapshot: RepoSnapshot, meta: VerifyMeta): VerifyResult {
  const index = new FileIndex(snapshot);

  // Agents sometimes return node ids that need slugging; keep edges pointing at them.
  const idFix = new Map<string, string>();
  for (const n of draft.nodes) idFix.set(n.id, slugId(n.id));
  const fixedEdges = draft.edges.map((e) => ({ ...e, from: idFix.get(e.from) ?? e.from, to: idFix.get(e.to) ?? e.to }));

  let nodes = cleanNodes(draft.nodes, index);
  const nodeIds = new Set(nodes.map((n) => n.id));
  const { edges, idMap, dropped } = verifyEdges(fixedEdges, nodeIds, index);

  // Keep a node if a verified edge touches it, or it is backed by real files.
  const touched = new Set(edges.flatMap((e) => [e.from, e.to]));
  const before = nodes.length;
  nodes = nodes.filter((n) => touched.has(n.id) || n.files.length > 0);
  const nodesDropped = before - nodes.length + (draft.nodes.length - before);

  const flows = remapFlows(draft.flows, idMap, new Set(edges.map((e) => e.id)));

  const stats: GraphStats = {
    files: snapshot.files.length,
    tokens: snapshot.totalTokens,
    edgesProposed: draft.edges.length,
    edgesVerified: edges.length,
    edgesDropped: dropped.length,
    nodesDropped,
    model: meta.model,
    durationMs: meta.durationMs,
    agents: draft.agentStats,
  };

  return {
    graph: {
      version: 1,
      repo: meta.repo,
      sha: meta.sha,
      branch: meta.branch,
      generatedAt: new Date().toISOString(),
      mode: "full",
      stack: draft.stack,
      summary: draft.summary,
      nodes,
      edges,
      flows,
      stats,
    },
    dropped,
  };
}

/**
 * Re-check existing edges after a push. Edges whose evidence lives only in
 * unchanged files are kept as-is; the rest are re-verified against the new
 * snapshot and removed if nothing survives.
 */
export function reverifyEdges(
  edges: AtlasEdge[],
  changedPaths: Set<string>,
  index: FileIndex,
): { kept: AtlasEdge[]; lost: AtlasEdge[] } {
  const kept: AtlasEdge[] = [];
  const lost: AtlasEdge[] = [];
  for (const e of edges) {
    if (!e.evidence.some((ev) => changedPaths.has(ev.path))) {
      kept.push(e);
      continue;
    }
    const evidence = e.evidence
      .map((ev) => (changedPaths.has(ev.path) ? index.verify(ev) : ev))
      .filter((ev): ev is Evidence => !!ev);
    if (evidence.length > 0) kept.push({ ...e, evidence: dedupeEvidence(evidence) });
    else lost.push(e);
  }
  return { kept, lost };
}

// Deterministic graph analysis: no model calls, instant and repeatable.
// Blast radius, commit-to-commit diffs, architecture rules and flow rendering.
import {
  type AtlasEdge,
  type AtlasFlow,
  type AtlasGraph,
  type AtlasNode,
  type DriftFinding,
  type NodeKind,
  type Severity,
  edgeKey,
} from "../../shared/graph";

export function nodeMap(graph: Pick<AtlasGraph, "nodes">): Map<string, AtlasNode> {
  return new Map(graph.nodes.map((n) => [n.id, n]));
}

/** Find a node by id, label or fuzzy text ("redis", "Orders API"). */
export function findNode(graph: AtlasGraph, query: string): AtlasNode | undefined {
  const q = query.trim().toLowerCase();
  const exact = graph.nodes.find((n) => n.id === q || n.label.toLowerCase() === q);
  if (exact) return exact;
  const words = q.split(/[^a-z0-9]+/).filter(Boolean);
  let best: { node: AtlasNode; score: number } | undefined;
  for (const n of graph.nodes) {
    const hay = `${n.id} ${n.label} ${n.tech ?? ""} ${n.kind}`.toLowerCase();
    const score = words.filter((w) => hay.includes(w)).length;
    if (score > 0 && (!best || score > best.score)) best = { node: n, score };
  }
  return best?.node;
}

// ---------------------------------------------------------------- blast radius

export interface BlastRadius {
  node: AtlasNode;
  /** Components that (transitively) depend on the failed one, nearest first. */
  impacted: Array<{ node: AtlasNode; depth: number; via: string }>;
  /** Edges that stop working: into the failed node and along the impact chain. */
  edgeIds: string[];
  /** Flows with a step that touches the failed node. */
  brokenFlows: AtlasFlow[];
  summary: string;
}

/**
 * "What breaks if X dies?" Edges point actor → dependency, so everything that
 * reaches X by following edges backwards is impacted.
 */
export function blastRadius(graph: AtlasGraph, nodeId: string): BlastRadius | undefined {
  const nodes = nodeMap(graph);
  const root = nodes.get(nodeId);
  if (!root) return undefined;

  const incoming = new Map<string, AtlasEdge[]>();
  for (const e of graph.edges) {
    if (!incoming.has(e.to)) incoming.set(e.to, []);
    incoming.get(e.to)!.push(e);
  }

  const depth = new Map<string, number>([[nodeId, 0]]);
  const via = new Map<string, string>();
  const edgeIds = new Set<string>();
  const queue = [nodeId];
  while (queue.length) {
    const cur = queue.shift()!;
    for (const e of incoming.get(cur) ?? []) {
      edgeIds.add(e.id);
      if (depth.has(e.from)) continue;
      depth.set(e.from, depth.get(cur)! + 1);
      via.set(e.from, e.id);
      queue.push(e.from);
    }
  }

  const impacted = [...depth.entries()]
    .filter(([id]) => id !== nodeId)
    .map(([id, d]) => ({ node: nodes.get(id)!, depth: d, via: via.get(id)! }))
    .sort((a, b) => a.depth - b.depth || a.node.label.localeCompare(b.node.label));

  const touching = new Set(graph.edges.filter((e) => e.from === nodeId || e.to === nodeId).map((e) => e.id));
  const brokenFlows = graph.flows.filter((f) => f.steps.some((s) => touching.has(s.edge)));

  const direct = impacted.filter((i) => i.depth === 1).map((i) => i.node.label);
  const summary =
    impacted.length === 0
      ? `Nothing in the map depends on ${root.label}.`
      : `If ${root.label} goes down, ${impacted.length} component${impacted.length === 1 ? "" : "s"} ` +
        `${impacted.length === 1 ? "is" : "are"} affected (directly: ${direct.join(", ")})` +
        (brokenFlows.length ? ` and ${brokenFlows.length} flow${brokenFlows.length === 1 ? "" : "s"} break: ${brokenFlows.map((f) => f.name).join(", ")}.` : ".");

  return { node: root, impacted, edgeIds: [...edgeIds], brokenFlows, summary };
}

// ---------------------------------------------------------------- diff

export interface GraphDiff {
  addedNodes: AtlasNode[];
  removedNodes: AtlasNode[];
  addedEdges: AtlasEdge[];
  removedEdges: AtlasEdge[];
}

export function diffGraphs(before: AtlasGraph, after: AtlasGraph): GraphDiff {
  const beforeNodes = new Set(before.nodes.map((n) => n.id));
  const afterNodes = new Set(after.nodes.map((n) => n.id));
  const beforeEdges = new Set(before.edges.map(edgeKey));
  const afterEdges = new Set(after.edges.map(edgeKey));
  return {
    addedNodes: after.nodes.filter((n) => !beforeNodes.has(n.id)),
    removedNodes: before.nodes.filter((n) => !afterNodes.has(n.id)),
    addedEdges: after.edges.filter((e) => !beforeEdges.has(edgeKey(e))),
    removedEdges: before.edges.filter((e) => !afterEdges.has(edgeKey(e))),
  };
}

export function isEmptyDiff(d: GraphDiff): boolean {
  return !d.addedNodes.length && !d.removedNodes.length && !d.addedEdges.length && !d.removedEdges.length;
}

// ---------------------------------------------------------------- rules

const DATA_KINDS = new Set<NodeKind>(["database", "cache", "queue", "storage"]);
const CLIENT_KINDS = new Set<NodeKind>(["frontend", "client"]);

type RuleFinding = Omit<DriftFinding, "id">;

/** Architecture rules applied to what a push changed. */
export function ruleFindings(before: AtlasGraph, after: AtlasGraph, diff: GraphDiff): RuleFinding[] {
  const nodes = new Map([...nodeMap(before), ...nodeMap(after)]);
  const out: RuleFinding[] = [];
  const label = (id: string) => nodes.get(id)?.label ?? id;
  const where = (e: AtlasEdge) => (e.evidence[0] ? ` (${e.evidence[0].path}:${e.evidence[0].line})` : "");

  for (const e of diff.addedEdges) {
    const from = nodes.get(e.from);
    const to = nodes.get(e.to);
    if (!from || !to) continue;
    if (CLIENT_KINDS.has(from.kind) && DATA_KINDS.has(to.kind)) {
      out.push({
        severity: "critical",
        rule: "layering.client-to-data",
        title: `${from.label} now talks to ${to.label} directly`,
        detail:
          `New ${e.kind} dependency${where(e)} bypasses the API layer, so its auth, validation and ` +
          `caching no longer apply, and ${to.kind} credentials end up in client code.`,
        nodeIds: [from.id, to.id],
        edgeIds: [e.id],
        source: "rule",
      });
    } else if (CLIENT_KINDS.has(from.kind) && to.kind === "external" && e.kind === "sdk") {
      out.push({
        severity: "warning",
        rule: "layering.client-to-third-party",
        title: `${from.label} calls ${to.label} from the client`,
        detail: `Third-party SDK used in client code${where(e)}. Make sure no secret keys are shipped to the browser.`,
        nodeIds: [from.id, to.id],
        edgeIds: [e.id],
        source: "rule",
      });
    }
  }

  for (const n of diff.addedNodes) {
    if (n.kind === "external") {
      out.push({
        severity: "info",
        rule: "dependency.new-third-party",
        title: `New third-party dependency: ${n.label}`,
        detail: `${n.summary}`.trim() || `The system now depends on ${n.label}.`,
        nodeIds: [n.id],
        edgeIds: diff.addedEdges.filter((e) => e.to === n.id || e.from === n.id).map((e) => e.id),
        source: "rule",
      });
    } else if (DATA_KINDS.has(n.kind)) {
      out.push({
        severity: "warning",
        rule: "dependency.new-datastore",
        title: `New ${n.kind}: ${n.label}`,
        detail: `A new piece of infrastructure to run, back up and monitor. ${n.summary}`.trim(),
        nodeIds: [n.id],
        edgeIds: diff.addedEdges.filter((e) => e.to === n.id).map((e) => e.id),
        source: "rule",
      });
    }
  }

  // Flows that lost a step.
  const removed = new Set(diff.removedEdges.map((e) => e.id));
  for (const f of before.flows) {
    const lostSteps = f.steps.filter((s) => removed.has(s.edge));
    if (lostSteps.length === 0) continue;
    out.push({
      severity: "warning",
      rule: "flow.changed",
      title: `"${f.name}" flow changed`,
      detail: `${lostSteps.length} step${lostSteps.length === 1 ? "" : "s"} of this flow no longer exist: ${lostSteps
        .map((s) => {
          const e = before.edges.find((x) => x.id === s.edge);
          return e ? `${label(e.from)} → ${label(e.to)}` : s.edge;
        })
        .join(", ")}.`,
      nodeIds: [],
      edgeIds: lostSteps.map((s) => s.edge),
      source: "rule",
    });
  }

  // New dependency cycles between our own components.
  for (const e of diff.addedEdges) {
    if (e.kind === "consume" || e.kind === "webhook") continue;
    const path = findPath(after, e.to, e.from);
    if (path) {
      out.push({
        severity: "warning",
        rule: "coupling.cycle",
        title: `New dependency cycle: ${[e.from, ...path].map(label).join(" → ")}`,
        detail: "Cycles make components impossible to deploy, test or reason about independently.",
        nodeIds: [e.from, ...path],
        edgeIds: [e.id],
        source: "rule",
      });
    }
  }

  return out;
}

/** BFS path from → to over call-like edges; returns node ids after `from`, ending at `to`. */
function findPath(graph: AtlasGraph, from: string, to: string): string[] | undefined {
  const out = new Map<string, string[]>();
  for (const e of graph.edges) {
    if (e.kind === "consume" || e.kind === "webhook") continue;
    if (!out.has(e.from)) out.set(e.from, []);
    out.get(e.from)!.push(e.to);
  }
  const prev = new Map<string, string>();
  const queue = [from];
  const seen = new Set([from]);
  while (queue.length) {
    const cur = queue.shift()!;
    if (cur === to) {
      const path = [cur];
      let p = cur;
      while (prev.has(p) && prev.get(p) !== from) {
        p = prev.get(p)!;
        path.unshift(p);
      }
      return from === to ? path : [from, ...path].slice(1).length ? [from, ...path].filter((x, i) => i > 0 || x !== from).length ? [from, ...path].slice(from === path[0] ? 1 : 0) : path : path;
    }
    for (const next of out.get(cur) ?? []) {
      if (seen.has(next)) continue;
      seen.add(next);
      prev.set(next, cur);
      queue.push(next);
    }
  }
  return undefined;
}

export function maxSeverity(findings: Array<{ severity: Severity }>): Severity | "none" {
  if (findings.some((f) => f.severity === "critical")) return "critical";
  if (findings.some((f) => f.severity === "warning")) return "warning";
  if (findings.length) return "info";
  return "none";
}

// ---------------------------------------------------------------- flows

export interface FlowStepView {
  index: number;
  edgeId: string;
  from: { id: string; label: string; kind: NodeKind };
  to: { id: string; label: string; kind: NodeKind };
  kind: AtlasEdge["kind"];
  label: string;
  note: string;
  evidence: AtlasEdge["evidence"][number] | undefined;
}

export interface FlowView {
  id: string;
  name: string;
  trigger: string;
  description: string;
  steps: FlowStepView[];
}

export function flowView(graph: AtlasGraph, flow: AtlasFlow): FlowView {
  const nodes = nodeMap(graph);
  const edges = new Map(graph.edges.map((e) => [e.id, e]));
  const steps: FlowStepView[] = [];
  flow.steps.forEach((s) => {
    const e = edges.get(s.edge);
    if (!e) return;
    const from = nodes.get(e.from);
    const to = nodes.get(e.to);
    if (!from || !to) return;
    steps.push({
      index: steps.length + 1,
      edgeId: e.id,
      from: { id: from.id, label: from.label, kind: from.kind },
      to: { id: to.id, label: to.label, kind: to.kind },
      kind: e.kind,
      label: e.label,
      note: s.note,
      evidence: e.evidence[0],
    });
  });
  return { id: flow.id, name: flow.name, trigger: flow.trigger, description: flow.description, steps };
}

/** Plain-text walk-through of a flow, for the model to narrate. */
export function flowText(view: FlowView): string {
  return [
    `Flow: ${view.name} (trigger: ${view.trigger})`,
    ...view.steps.map(
      (s) =>
        `${s.index}. ${s.from.label} → ${s.to.label} [${s.kind}: ${s.label}]: ${s.note}` +
        (s.evidence ? ` (${s.evidence.path}:${s.evidence.line})` : ""),
    ),
  ].join("\n");
}

/** Cheap keyword match of a question against existing flows. */
export function matchFlow(graph: AtlasGraph, question: string): AtlasFlow | undefined {
  const stop = new Set(["what", "happens", "when", "how", "does", "the", "a", "an", "is", "do", "i", "user", "someone", "to", "of", "in", "on", "and", "flow", "work", "works"]);
  const words = question.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 2 && !stop.has(w));
  let best: { flow: AtlasFlow; score: number } | undefined;
  for (const f of graph.flows) {
    const hay = `${f.id} ${f.name} ${f.trigger} ${f.description}`.toLowerCase();
    const score = words.filter((w) => hay.includes(w) || hay.includes(w.replace(/s$/, ""))).length;
    if (score > 0 && (!best || score > best.score)) best = { flow: f, score };
  }
  return best && best.score >= Math.min(2, words.length) ? best.flow : undefined;
}

// ---------------------------------------------------------------- summaries

export function graphSummary(graph: AtlasGraph) {
  const kinds: Record<string, number> = {};
  for (const n of graph.nodes) kinds[n.kind] = (kinds[n.kind] ?? 0) + 1;
  return {
    repoKey: graph.repo.key,
    repo: graph.repo.name,
    sha: graph.sha,
    generatedAt: graph.generatedAt,
    stack: graph.stack,
    summary: graph.summary,
    components: graph.nodes.length,
    dependencies: graph.edges.length,
    flows: graph.flows.map((f) => ({ id: f.id, name: f.name })),
    kinds,
    verified: { proposed: graph.stats.edgesProposed, verified: graph.stats.edgesVerified, dropped: graph.stats.edgesDropped },
  };
}

/** Compact text description of the whole graph, for model consumption. */
export function graphText(graph: AtlasGraph): string {
  const nodes = nodeMap(graph);
  const lines = [
    `${graph.repo.name} @ ${graph.sha.slice(0, 7)}: ${graph.summary}`,
    `Stack: ${graph.stack.join(", ")}`,
    `Components (${graph.nodes.length}): ${graph.nodes.map((n) => `${n.label} [${n.kind}]`).join("; ")}`,
    `Dependencies (${graph.edges.length}, every one cited from code):`,
    ...graph.edges.map((e) => `- ${nodes.get(e.from)?.label} → ${nodes.get(e.to)?.label} (${e.kind}: ${e.label})`),
    `Flows: ${graph.flows.map((f) => f.name).join("; ")}`,
  ];
  return lines.join("\n");
}

