// MCP Events (draft spec, protocol 2026-07-28): ChatGPT subscribes to
// "atlas.architecture_drift" with a callback URL and signing secret; when a
// push changes a repo's architecture we POST a Standard Webhooks–signed event.
//
// https://developers.openai.com/plugins/build/mcp-events
import { createHash, randomBytes, randomUUID } from "node:crypto";
import { Webhook } from "standardwebhooks";
import { type DriftReport, type Severity, severityRank, shortSha } from "../shared/graph";
import { readDoc, writeDoc } from "./store";

export const DRIFT_EVENT = "atlas.architecture_drift";

export const EVENT_DEFINITIONS = [
  {
    name: DRIFT_EVENT,
    description:
      "Fires when a push changes a mapped repository's architecture: new or removed components " +
      "and dependencies, layering violations (e.g. frontend querying the database), new " +
      "third-party services, or broken flows. Use it to watch a repo for architecture drift.",
    delivery: ["webhook"],
    inputSchema: {
      type: "object",
      properties: {
        repo: {
          type: "string",
          description: "Repository to watch, e.g. \"owner/name\". Omit to watch every mapped repo.",
        },
        minSeverity: {
          type: "string",
          enum: ["info", "warning", "critical"],
          default: "warning",
          description: "Only fire for drift at least this severe.",
        },
      },
    },
    payloadSchema: {
      type: "object",
      properties: {
        reportId: { type: "string" },
        repo: { type: "string" },
        fromSha: { type: "string" },
        toSha: { type: "string" },
        severity: { type: "string", enum: ["info", "warning", "critical"] },
        summary: { type: "string" },
        commit: { type: "string", description: "Head commit message" },
        findings: {
          type: "array",
          items: {
            type: "object",
            properties: { severity: { type: "string" }, title: { type: "string" }, detail: { type: "string" } },
          },
        },
        viewUrl: { type: "string" },
      },
    },
  },
] as const;

const DEFAULT_TTL_MS = 24 * 60 * 60 * 1000;
const MAX_TTL_MS = 7 * DEFAULT_TTL_MS;
const MAX_SUBSCRIPTIONS = 200;
const RECENT_EVENTS = 200;

export interface Subscription {
  id: string;
  name: string;
  arguments: { repo?: string; minSeverity?: Severity };
  url: string;
  secret: string;
  /** Canonical identity: same name + arguments + url ⇒ same subscription. */
  identity: string;
  createdAt: string;
  expiresAt: string;
  refreshBefore: string;
  cursor: string;
  lastDeliveryAt: string | null;
  lastError: string | null;
}

interface StoredEvent {
  seq: number;
  eventId: string;
  name: string;
  timestamp: string;
  data: Record<string, unknown>;
}

interface EventLog {
  seq: number;
  recent: StoredEvent[];
}

/** JSON-RPC error with the codes from the MCP Events draft. */
export class EventsError extends Error {
  constructor(
    readonly code: number,
    message: string,
    readonly data?: Record<string, unknown>,
  ) {
    super(message);
  }
}

const subs = () => readDoc<Record<string, Subscription>>("subscriptions", {});
const saveSubs = (all: Record<string, Subscription>) => writeDoc("subscriptions", all);
const eventLog = () => readDoc<EventLog>("events", { seq: 0, recent: [] });

const cursorOf = (seq: number) => `c_${seq}`;
const seqOf = (cursor: string | null | undefined) => (cursor && /^c_\d+$/.test(cursor) ? Number(cursor.slice(2)) : undefined);

function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.keys(value as object)
      .sort()
      .filter((k) => (value as Record<string, unknown>)[k] !== undefined)
      .map((k) => `${JSON.stringify(k)}:${canonical((value as Record<string, unknown>)[k])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

// ---------------------------------------------------------------- handlers

export function listEvents() {
  return { events: EVENT_DEFINITIONS };
}

export interface SubscribeParams {
  name: string;
  arguments?: Record<string, unknown>;
  delivery?: { mode?: string; url?: string; secret?: string };
  cursor?: string | null;
  maxAgeMs?: number;
  ttlMs?: number;
}

export async function subscribe(params: SubscribeParams) {
  if (params.name !== DRIFT_EVENT) throw new EventsError(-32011, "NotFound", { kind: "event" });
  const delivery = params.delivery ?? {};
  if ((delivery.mode ?? "webhook") !== "webhook") {
    throw new EventsError(-32014, "Unsupported", { feature: `delivery mode ${delivery.mode}` });
  }
  if (!delivery.url || !/^https?:\/\//.test(delivery.url)) throw new EventsError(-32602, "InvalidParams", { reason: "delivery.url must be an http(s) URL" });
  if (!delivery.secret || !/^whsec_[A-Za-z0-9+/=]{16,}$/.test(delivery.secret)) {
    throw new EventsError(-32602, "InvalidParams", { reason: "delivery.secret must be whsec_<base64>" });
  }
  const args = normalizeArgs(params.arguments ?? {});
  const identity = canonical({ name: params.name, arguments: args, url: delivery.url });
  const all = subs();
  const existing = Object.values(all).find((s) => s.identity === identity);
  if (!existing && Object.keys(all).length >= MAX_SUBSCRIPTIONS) {
    throw new EventsError(-32013, "ResourceExhausted", { limit: "subscriptions" });
  }

  // Prove the callback works before activating (new subscriptions or new secret).
  if (!existing || existing.secret !== delivery.secret) await verifyCallback(delivery.url, delivery.secret);

  const ttl = Math.min(Math.max(params.ttlMs ?? DEFAULT_TTL_MS, 60_000), MAX_TTL_MS);
  const now = Date.now();
  const log = eventLog();
  const sub: Subscription = {
    id: existing?.id ?? `sub_${randomBytes(8).toString("hex")}`,
    name: params.name,
    arguments: args,
    url: delivery.url,
    secret: delivery.secret,
    identity,
    createdAt: existing?.createdAt ?? new Date(now).toISOString(),
    expiresAt: new Date(now + ttl).toISOString(),
    refreshBefore: new Date(now + ttl * 0.8).toISOString(),
    cursor: params.cursor ?? existing?.cursor ?? cursorOf(log.seq),
    lastDeliveryAt: existing?.lastDeliveryAt ?? null,
    lastError: existing?.lastError ?? null,
  };
  await saveSubs({ ...all, [sub.id]: sub });

  // Replay events the subscriber missed since its cursor (within maxAgeMs).
  const since = seqOf(params.cursor);
  let truncated = false;
  if (since !== undefined) {
    const oldest = log.recent.at(-1)?.seq ?? log.seq;
    truncated = since < oldest - 1;
    const maxAge = params.maxAgeMs ?? Number.POSITIVE_INFINITY;
    const missed = log.recent
      .filter((e) => e.seq > since && now - Date.parse(e.timestamp) <= maxAge && matches(sub, e.data))
      .sort((a, b) => a.seq - b.seq);
    for (const e of missed) void deliver(sub, e);
  }

  return {
    id: sub.id,
    refreshBefore: sub.refreshBefore,
    cursor: cursorOf(log.seq),
    truncated,
    deliveryStatus: { active: true, lastDeliveryAt: sub.lastDeliveryAt, lastError: sub.lastError },
  };
}

export async function unsubscribe(params: { name?: string; arguments?: Record<string, unknown>; delivery?: { url?: string }; id?: string }) {
  const all = subs();
  const identity = params.name && params.delivery?.url
    ? canonical({ name: params.name, arguments: normalizeArgs(params.arguments ?? {}), url: params.delivery.url })
    : undefined;
  const victim = Object.values(all).find((s) => (params.id && s.id === params.id) || (identity && s.identity === identity));
  if (victim) {
    delete all[victim.id];
    await saveSubs(all);
  }
  return {}; // idempotent
}

function normalizeArgs(raw: Record<string, unknown>): Subscription["arguments"] {
  const out: Subscription["arguments"] = {};
  if (typeof raw.repo === "string" && raw.repo.trim()) out.repo = raw.repo.trim().toLowerCase().replace(/^https?:\/\/github\.com\//, "").replace(/\.git$/, "");
  const sev = raw.minSeverity;
  if (sev !== undefined) {
    if (sev !== "info" && sev !== "warning" && sev !== "critical") throw new EventsError(-32602, "InvalidParams", { reason: "minSeverity" });
    out.minSeverity = sev;
  }
  return out;
}

async function verifyCallback(url: string, secret: string): Promise<void> {
  const challenge = randomUUID();
  const body = JSON.stringify({ type: "verification", challenge });
  let res: Response;
  try {
    res = await fetch(url, { method: "POST", headers: signedHeaders(secret, `verify_${challenge}`, body), body, signal: AbortSignal.timeout(8000) });
  } catch (err) {
    const reason = String((err as Error).name) === "TimeoutError" ? "timeout" : "connection_refused";
    throw new EventsError(-32015, "CallbackEndpointError", { reason });
  }
  if (!res.ok) throw new EventsError(-32015, "CallbackEndpointError", { reason: res.status >= 500 ? "http_5xx" : "http_4xx" });
  const text = await res.text();
  let echoed: unknown;
  try {
    echoed = (JSON.parse(text) as { challenge?: unknown }).challenge;
  } catch {
    echoed = text.trim();
  }
  if (echoed !== challenge) throw new EventsError(-32015, "CallbackEndpointError", { reason: "challenge_failed" });
}

function signedHeaders(secret: string, msgId: string, body: string, subscriptionId?: string): Record<string, string> {
  const ts = new Date();
  return {
    "Content-Type": "application/json",
    "webhook-id": msgId,
    "webhook-timestamp": String(Math.floor(ts.getTime() / 1000)),
    "webhook-signature": new Webhook(secret).sign(msgId, ts, body),
    ...(subscriptionId ? { "X-MCP-Subscription-Id": subscriptionId } : {}),
  };
}

// ---------------------------------------------------------------- emit

function matches(sub: Subscription, data: Record<string, unknown>): boolean {
  if (sub.arguments.repo) {
    const repo = String(data.repo ?? "").toLowerCase();
    const want = sub.arguments.repo;
    if (repo !== want && !repo.endsWith(`/${want}`)) return false;
  }
  const min = sub.arguments.minSeverity ?? "warning";
  return severityRank(data.severity as Severity) >= severityRank(min);
}

/** Record a drift report as an event and fan it out to matching subscriptions. */
export async function emitDrift(report: DriftReport, publicUrl?: string): Promise<number> {
  if (report.maxSeverity === "none") return 0;
  const log = eventLog();
  const seq = log.seq + 1;
  const event: StoredEvent = {
    seq,
    eventId: `evt_${createHash("sha256").update(report.id).digest("hex").slice(0, 16)}`,
    name: DRIFT_EVENT,
    timestamp: report.at,
    data: {
      reportId: report.id,
      repo: report.repoName,
      fromSha: shortSha(report.fromSha),
      toSha: shortSha(report.toSha),
      severity: report.maxSeverity,
      summary: report.summary,
      commit: report.commits[0]?.message ?? "",
      findings: report.findings.slice(0, 5).map((f) => ({ severity: f.severity, title: f.title, detail: f.detail })),
      ...(publicUrl ? { viewUrl: `${publicUrl}/app?repo=${encodeURIComponent(report.repoKey)}&drift=${report.id}` } : {}),
    },
  };
  await writeDoc("events", { seq, recent: [event, ...log.recent].slice(0, RECENT_EVENTS) });

  const now = Date.now();
  const targets = Object.values(subs()).filter((s) => Date.parse(s.expiresAt) > now && matches(s, event.data));
  await Promise.all(targets.map((s) => deliver(s, event)));
  return targets.length;
}

async function deliver(sub: Subscription, event: StoredEvent): Promise<void> {
  const body = JSON.stringify({
    eventId: event.eventId,
    name: event.name,
    timestamp: event.timestamp,
    data: event.data,
    cursor: cursorOf(event.seq),
  });
  const delays = [0, 1000, 4000, 15000];
  let lastError: string | null = null;
  for (const delay of delays) {
    if (delay) await new Promise((r) => setTimeout(r, delay));
    try {
      const res = await fetch(sub.url, {
        method: "POST",
        headers: signedHeaders(sub.secret, event.eventId, body, sub.id),
        body,
        signal: AbortSignal.timeout(10_000),
      });
      if (res.ok) {
        await patchSub(sub.id, { lastDeliveryAt: new Date().toISOString(), lastError: null, cursor: cursorOf(event.seq) });
        console.log(`[events] delivered ${event.eventId} → ${sub.id}`);
        return;
      }
      lastError = `HTTP ${res.status}`;
      if (res.status === 410) {
        // Subscriber is gone for good.
        await unsubscribe({ id: sub.id });
        return;
      }
      if (res.status === 413 || (res.status >= 400 && res.status < 500 && res.status !== 429)) break;
    } catch (err) {
      lastError = (err as Error).message;
    }
  }
  await patchSub(sub.id, { lastError });
  console.warn(`[events] delivery of ${event.eventId} to ${sub.id} failed: ${lastError}`);
}

async function patchSub(id: string, patch: Partial<Subscription>): Promise<void> {
  const all = subs();
  if (!all[id]) return;
  all[id] = { ...all[id], ...patch };
  await saveSubs(all);
}

export function subscriptionCount(): number {
  return Object.keys(subs()).length;
}

// GitHub push webhooks → incremental architecture review, plus an optional
// commit comment when a push introduces drift.
import { createHmac, timingSafeEqual } from "node:crypto";
import type { Request, Response } from "express";
import { type DriftReport, shortSha } from "../shared/graph";
import { startReviewJob } from "./jobs";
import { resolveRepo } from "./repo";
import { getRepo } from "./store";

function validSignature(raw: Buffer, header: string | undefined, secret: string): boolean {
  if (!header?.startsWith("sha256=")) return false;
  const expected = Buffer.from(`sha256=${createHmac("sha256", secret).update(raw).digest("hex")}`);
  const got = Buffer.from(header);
  return expected.length === got.length && timingSafeEqual(expected, got);
}

/** Express handler; mount with express.raw() so the body is the exact bytes GitHub signed. */
export function githubWebhook(req: Request, res: Response): void {
  const raw = Buffer.isBuffer(req.body) ? req.body : Buffer.from(JSON.stringify(req.body ?? {}));
  const secret = process.env.GITHUB_WEBHOOK_SECRET;
  if (secret && !validSignature(raw, req.header("x-hub-signature-256"), secret)) {
    res.status(401).json({ error: "bad signature" });
    return;
  }

  const event = req.header("x-github-event");
  if (event === "ping") {
    res.json({ ok: true, message: "Atlas is listening" });
    return;
  }
  if (event !== "push") {
    res.status(202).json({ ignored: event });
    return;
  }

  let payload: {
    ref?: string;
    after?: string;
    deleted?: boolean;
    repository?: { html_url?: string; full_name?: string };
  };
  try {
    payload = JSON.parse(raw.toString("utf8"));
  } catch {
    res.status(400).json({ error: "invalid JSON" });
    return;
  }
  if (payload.deleted || !payload.after || /^0+$/.test(payload.after)) {
    res.status(202).json({ ignored: "branch deletion" });
    return;
  }

  const repo = resolveRepo(payload.repository?.html_url ?? payload.repository?.full_name ?? "");
  const record = getRepo(repo.key);
  if (!record?.latestSha) {
    res.status(202).json({ ignored: `${repo.name} is not mapped yet` });
    return;
  }
  const branch = payload.ref?.replace(/^refs\/heads\//, "");
  if (record.branch && branch && branch !== record.branch) {
    res.status(202).json({ ignored: `push to ${branch}; watching ${record.branch}` });
    return;
  }

  const job = startReviewJob(repo.key, { toSha: payload.after, source: "github" });
  console.log(`[github] push to ${repo.name}@${shortSha(payload.after)} → ${job?.id}`);
  res.status(202).json({ jobId: job?.id });
}

/** Comment on the head commit of a drifting push (needs GITHUB_TOKEN). */
export async function commentOnCommit(report: DriftReport, publicUrl?: string): Promise<void> {
  const token = process.env.GITHUB_TOKEN;
  const record = getRepo(report.repoKey);
  if (!token || record?.repo.source !== "github" || report.maxSeverity === "none") return;

  const icon = report.maxSeverity === "critical" ? "🔴" : report.maxSeverity === "warning" ? "🟠" : "🔵";
  const body = [
    `### ${icon} Atlas: architecture drift in \`${shortSha(report.toSha)}\``,
    "",
    report.summary,
    "",
    ...report.findings.slice(0, 6).map((f) => `- **${f.severity.toUpperCase()}**: ${f.title}. ${f.detail}`),
    "",
    publicUrl ? `[Open in Atlas](${publicUrl}/app?repo=${encodeURIComponent(report.repoKey)}&drift=${report.id})` : "",
  ].join("\n");

  const res = await fetch(`https://api.github.com/repos/${record.repo.name}/commits/${report.toSha}/comments`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}`, Accept: "application/vnd.github+json", "User-Agent": "atlas" },
    body: JSON.stringify({ body }),
  });
  if (!res.ok) console.warn(`[github] commit comment failed: ${res.status} ${await res.text()}`);
}

// Tool implementations, shared by the MCP server (ChatGPT) and the REST API
// that powers the standalone UI and tests.
import { type AtlasFlow, type AtlasGraph, type DriftReport, shortSha } from "../shared/graph";
import { brain } from "./brain";
import {
  blastRadius,
  findNode,
  flowText,
  flowView,
  graphSummary,
  graphText,
  matchFlow,
  nodeMap,
} from "./graph/analysis";
import { remapFlows } from "./graph/verify";
import { activeJob, getJob, startMapJob, startReviewJob } from "./jobs";
import { findRepo, listDrift, listRepos, loadGraph, saveGraph } from "./store";

export interface ToolOutput {
  /** Text the model reads. */
  text: string;
  /** structuredContent: seen by the model and the UI. Keep it compact. */
  structured: Record<string, unknown>;
}

export class ToolError extends Error {}

function requireGraph(repo: string | undefined): AtlasGraph {
  const record = findRepo(repo);
  if (!record) {
    throw new ToolError(
      repo
        ? `"${repo}" hasn't been mapped yet. Call map_repo with its GitHub URL first.`
        : "No repository has been mapped yet. Call map_repo with a GitHub URL first.",
    );
  }
  const graph = loadGraph(record.repo.key);
  if (!graph) throw new ToolError(`${record.repo.name} is still being mapped. Try again when the map is ready.`);
  return graph;
}

function repoList() {
  return listRepos().map((r) => {
    const g = r.latestSha ? loadGraph(r.repo.key, r.latestSha) : undefined;
    return {
      key: r.repo.key,
      name: r.repo.name,
      source: r.repo.source,
      sha: r.latestSha ?? null,
      mappedAt: r.mappedAt ?? null,
      components: g?.nodes.length ?? 0,
      dependencies: g?.edges.length ?? 0,
      mapping: activeJob(r.repo.key)?.id ?? null,
    };
  });
}

// ---------------------------------------------------------------- model-facing

export async function atlasHome(args: { repo?: string }): Promise<ToolOutput> {
  const repos = repoList();
  const current = findRepo(args.repo);
  const graph = current ? loadGraph(current.repo.key) : undefined;
  return {
    text: repos.length
      ? `Atlas is open. Mapped repos: ${repos.map((r) => `${r.name} (${r.components} components)`).join(", ")}.`
      : "Atlas is open. No repository is mapped yet: ask the user for a GitHub repo and call map_repo.",
    structured: { view: graph ? "map" : "home", repoKey: current?.repo.key ?? null, repos, summary: graph ? graphSummary(graph) : null },
  };
}

export async function mapRepo(args: { repo: string; branch?: string; force?: boolean }): Promise<ToolOutput> {
  let job;
  try {
    job = startMapJob(args.repo, { branch: args.branch, force: args.force });
  } catch (err) {
    throw new ToolError((err as Error).message);
  }
  // A cached map resolves almost instantly; give it a moment.
  for (let i = 0; i < 15 && job.status === "running"; i++) await new Promise((r) => setTimeout(r, 100));

  if (job.status === "error") throw new ToolError(job.error ?? "Mapping failed");
  if (job.status === "done") {
    const graph = loadGraph(job.repoKey)!;
    return {
      text: `${graph.repo.name} is mapped${job.cached ? " (cached)" : ""}. ${graphText(graph)}\n\nThe Atlas view shows the interactive map. Offer to trace a flow (trace_flow) or show what breaks if a component fails (blast_radius).`,
      structured: { view: "map", repoKey: job.repoKey, jobId: job.id, status: "done", summary: graphSummary(graph) },
    };
  }
  return {
    text:
      `Mapping ${job.repoName} has started. Atlas agents are reading the code: a Scout plans the work, Readers analyse ` +
      `modules in parallel, a Cartographer assembles the map, and a Verifier drops any dependency it can't find in the ` +
      `code. The Atlas view shows live progress; it usually takes about a minute. Don't call map_repo again for this repo.`,
    structured: { view: "map", repoKey: job.repoKey, jobId: job.id, status: "running", summary: null },
  };
}

export async function traceFlow(args: { repo?: string; question: string }): Promise<ToolOutput> {
  const graph = requireGraph(args.repo);
  let flow: AtlasFlow | undefined = matchFlow(graph, args.question);
  let answer = "";

  if (!flow) {
    try {
      const result = await brain.traceQuestion({ graph, question: args.question });
      answer = result.answer;
      if (result.flowId) flow = graph.flows.find((f) => f.id === result.flowId);
      if (!flow && result.flow) {
        const [clean] = remapFlows([result.flow], new Map(), new Set(graph.edges.map((e) => e.id)));
        if (clean) {
          flow = clean.id && graph.flows.some((f) => f.id === clean.id) ? { ...clean, id: `${clean.id}-q` } : clean;
          // Remember it, so the same question is instant next time.
          await saveGraph({ ...graph, flows: [...graph.flows, flow] });
        }
      }
    } catch (err) {
      console.error("tracer failed", err);
    }
  }
  if (!flow) {
    throw new ToolError(
      answer ||
        `Atlas couldn't find that path in ${graph.repo.name}. Known flows: ${graph.flows.map((f) => f.name).join("; ")}.`,
    );
  }

  const view = flowView(graph, flow);
  return {
    text: `${flowText(view)}${answer ? `\n\n${answer}` : ""}\n\nThe Atlas view is animating this request hop by hop with the code behind each step.`,
    structured: { view: "trace", repoKey: graph.repo.key, sha: graph.sha, flow: view },
  };
}

export async function blast(args: { repo?: string; component: string }): Promise<ToolOutput> {
  const graph = requireGraph(args.repo);
  const node = findNode(graph, args.component);
  if (!node) {
    throw new ToolError(`No component matching "${args.component}". Components: ${graph.nodes.map((n) => n.label).join(", ")}.`);
  }
  const b = blastRadius(graph, node.id)!;
  return {
    text: [
      b.summary,
      ...b.impacted.map((i) => `- ${i.node.label} (${i.node.kind}, ${i.depth === 1 ? "direct" : `${i.depth} hops away`})`),
      b.brokenFlows.length ? `Broken flows: ${b.brokenFlows.map((f) => f.name).join(", ")}` : "",
    ]
      .filter(Boolean)
      .join("\n"),
    structured: {
      view: "blast",
      repoKey: graph.repo.key,
      sha: graph.sha,
      nodeId: node.id,
      impacted: b.impacted.map((i) => ({ id: i.node.id, label: i.node.label, kind: i.node.kind, depth: i.depth })),
      brokenFlows: b.brokenFlows.map((f) => ({ id: f.id, name: f.name })),
      summary: b.summary,
    },
  };
}

export async function explainComponent(args: { repo?: string; component: string }): Promise<ToolOutput> {
  const graph = requireGraph(args.repo);
  const node = findNode(graph, args.component);
  if (!node) throw new ToolError(`No component matching "${args.component}".`);
  const nodes = nodeMap(graph);
  const fmt = (id: string) => nodes.get(id)?.label ?? id;
  const outgoing = graph.edges.filter((e) => e.from === node.id);
  const incoming = graph.edges.filter((e) => e.to === node.id);
  const cite = (e: (typeof graph.edges)[number]) => e.evidence.map((ev) => `${ev.path}:${ev.line} \`${ev.snippet}\``).join("; ");
  return {
    text: [
      `${node.label} (${node.kind}${node.tech ? `, ${node.tech}` : ""}): ${node.summary}`,
      node.details.length ? `Details: ${node.details.join("; ")}` : "",
      node.files.length ? `Files: ${node.files.map((f) => f.path).join(", ")}` : "",
      outgoing.length ? `Depends on:\n${outgoing.map((e) => `- ${fmt(e.to)} [${e.kind}: ${e.label}] (${cite(e)})`).join("\n")}` : "",
      incoming.length ? `Used by:\n${incoming.map((e) => `- ${fmt(e.from)} [${e.kind}: ${e.label}] (${cite(e)})`).join("\n")}` : "",
    ]
      .filter(Boolean)
      .join("\n"),
    structured: {
      repoKey: graph.repo.key,
      node,
      dependsOn: outgoing.map((e) => ({ id: e.to, label: fmt(e.to), kind: e.kind, label2: e.label })),
      usedBy: incoming.map((e) => ({ id: e.from, label: fmt(e.from), kind: e.kind, label2: e.label })),
    },
  };
}

function compactReport(r: DriftReport) {
  return {
    id: r.id,
    at: r.at,
    fromSha: r.fromSha,
    toSha: r.toSha,
    commit: r.commits[0]?.message ?? "",
    author: r.commits[0]?.author ?? "",
    summary: r.summary,
    maxSeverity: r.maxSeverity,
    findings: r.findings.map((f) => ({ severity: f.severity, title: f.title, detail: f.detail })),
    added: { components: r.added.nodes.length, dependencies: r.added.edges.length },
    removed: { components: r.removed.nodes.length, dependencies: r.removed.edges.length },
  };
}

export async function architectureDrift(args: { repo?: string; reportId?: string; limit?: number }): Promise<ToolOutput> {
  const graph = requireGraph(args.repo);
  const reports = listDrift(graph.repo.key);
  const selected = (args.reportId && reports.find((r) => r.id === args.reportId)) || reports[0];
  const recent = reports.slice(0, Math.min(args.limit ?? 5, 20));
  if (!selected) {
    return {
      text: `No pushes reviewed yet for ${graph.repo.name}. Atlas reviews every push automatically once the GitHub webhook is set up.`,
      structured: { view: "drift", repoKey: graph.repo.key, reportId: null, reports: [] },
    };
  }
  const lines = [
    `Push ${shortSha(selected.fromSha)} → ${shortSha(selected.toSha)}${selected.commits[0] ? ` ("${selected.commits[0].message}")` : ""}: ${selected.summary}`,
    ...selected.findings.map((f) => `- [${f.severity}] ${f.title}: ${f.detail}`),
  ];
  return {
    text: `${lines.join("\n")}\n\nThe Atlas view highlights the change on the map.`,
    structured: { view: "drift", repoKey: graph.repo.key, reportId: selected.id, reports: recent.map(compactReport) },
  };
}

export async function checkDrift(args: { repo?: string }): Promise<ToolOutput> {
  const graph = requireGraph(args.repo);
  const job = startReviewJob(graph.repo.key, { source: "manual" });
  if (!job) throw new ToolError("This repo needs a full map first.");
  return {
    text: `Atlas is reviewing new commits on ${graph.repo.name} since ${shortSha(graph.sha)}. Results appear in the Atlas view in a few seconds.`,
    structured: { view: "drift", repoKey: graph.repo.key, jobId: job.id, reportId: null, reports: [] },
  };
}

// ---------------------------------------------------------------- app-only

export async function appGraph(args: { repo?: string; sha?: string }) {
  const record = findRepo(args.repo);
  const graph = record ? loadGraph(record.repo.key, args.sha) : undefined;
  return { graph: graph ?? null, mapping: record ? (activeJob(record.repo.key)?.id ?? null) : null };
}

export async function appJob(args: { jobId: string }) {
  const job = getJob(args.jobId);
  if (!job) return { job: null };
  return { job: { ...job, log: job.log.slice(-60) } };
}

export async function appChanges(args: { repo?: string; after?: string }) {
  const record = findRepo(args.repo);
  if (!record) return { reports: [], latestSha: null, reviewing: null };
  const all = listDrift(record.repo.key);
  const idx = args.after ? all.findIndex((r) => r.id === args.after) : -1;
  const fresh = args.after ? (idx === -1 ? all.slice(0, 1) : all.slice(0, idx)) : all.slice(0, 10);
  const job = activeJob(record.repo.key);
  return {
    reports: fresh,
    latestSha: record.latestSha ?? null,
    reviewing: job && job.kind === "review" ? { id: job.id, log: job.log.slice(-8) } : null,
  };
}

export async function appRepos() {
  return { repos: repoList() };
}

export const toolImpls = {
  atlas: atlasHome,
  map_repo: mapRepo,
  trace_flow: traceFlow,
  blast_radius: blast,
  explain_component: explainComponent,
  architecture_drift: architectureDrift,
  check_drift: checkDrift,
} as const;

export const appToolImpls = {
  atlas_graph: appGraph,
  atlas_job: appJob,
  atlas_changes: appChanges,
  atlas_repos: appRepos,
} as const;

