    38	  groupLimit = READER_GROUP_TOKENS,
    39	): { groups: ReaderGroup[]; skipped: number } {
    40	  const available = new Map(files.map((file) => [file.path, file]));
    41	  const assignments = new Map<string, ReaderGroup>();
    42	  for (const group of proposed) {
    43	    for (const path of group.files) {
    44	      if (available.has(path) && !assignments.has(path)) assignments.set(path, group);
    45	    }
    46	  }
    47	  for (const group of fallbackGroups(files)) {
    48	    for (const path of group.files) if (!assignments.has(path)) assignments.set(path, group);
    49	  }
