    51	  let total = 0;
    52	  let skipped = 0;
    53	  const ranked = [...available.values()].sort((a, b) =>
    54	    filePriority(b.path) - filePriority(a.path) || a.tokens - b.tokens || a.path.localeCompare(b.path));
    55	  for (const file of ranked) {
    56	    const tokens = Math.max(file.tokens, Math.ceil(file.content.length / 4));
