   177	/** Bound the entire changed-file payload, including diffs and numbering overhead.
   178	 * Truncate content at line boundaries to preserve evidence coordinates. */
   179	export function reviewFiles(changes: ChangedFile[], files: RepoFile[], tokenLimit = 40_000) {
   180	  const byPath = new Map(files.map((file) => [file.path, file]));
   181	  let remaining = Math.max(0, tokenLimit * 4 - 2);
   182	  const supplied = new Map<string, string>();
   183	  const entries: Array<{ path: string; status: ChangedFile["status"]; previousPath?: string;
   184	    patch: string; content: string | null; truncated: boolean }> = [];
   185	  for (const change of changes) {
   186	    const entry = { ...change, patch: "", content: null as string | null, truncated: false };
   187	    const baseSize = JSON.stringify(entry).length + (entries.length ? 1 : 0);
   188	    if (baseSize > remaining) break;
   189	    remaining -= baseSize;
   190	    const take = (value: string) => {
   191	      // JSON escaping is part of the actual input budget.
   192	      let low = 0, high = value.length;
   193	      while (low < high) {
   194	        const mid = Math.ceil((low + high) / 2);
   195	        if (JSON.stringify(value.slice(0, mid)).length - 2 <= remaining) low = mid;
   196	        else high = mid - 1;
   197	      }
   198	      const chunk = value.slice(0, low);
   199	      remaining -= JSON.stringify(chunk).length - 2;
   200	      return chunk;
   201	    };
   202	    entry.patch = take(change.patch);
   203	    const file = change.status !== "deleted" ? byPath.get(change.path) : undefined;
   204	    if (file) {
   205	      const numbered = numberLines(file.content);
   206	      // Replacing null with a JSON string frees two characters.
   207	      remaining += 2;
   208	      const chunk = take(numbered);
   209	      const content = chunk.length === numbered.length ? chunk : chunk.slice(0, Math.max(0, chunk.lastIndexOf("\n")));
   210	      entry.content = content;
   211	      const count = content ? content.split("\n").length : 0;
   212	      supplied.set(change.path, file.content.split("\n").slice(0, count).join("\n"));
   213	      entry.truncated = content.length !== numbered.length;
   214	    }
   215	    entry.truncated ||= entry.patch !== change.patch || (!file && change.status !== "deleted");
   216	    entries.push(entry);
   217	  }
   218	  return { entries, supplied, omitted: changes.length - entries.length };
   219	}
