   221	export function isSuppliedEvidence(evidence: Evidence, supplied: Map<string, string>): boolean {
   222	  const content = supplied.get(evidence.path);
   223	  return content !== undefined && evidence.snippet.length > 0 && evidence.line > 0
   224	    && Number.isInteger(evidence.line)
   225	    && content.split("\n")[evidence.line - 1] === evidence.snippet;
   226	}
   227	
   228	/** Ordered results despite concurrent completion; at most limit tasks run at once. */
   229	export async function concurrentMap<T, R>(items: T[], limit: number, fn: (item: T, index: number) => Promise<R>): Promise<R[]> {
   230	  if (!Number.isInteger(limit) || limit < 1) throw new Error("Concurrency limit must be positive");
   231	  const results = new Array<R>(items.length);
   232	  let next = 0;
   233	  let failed = false;
   234	  // Stop scheduling after a fatal failure, and drain in-flight work before rejecting.
   235	  const workers = await Promise.allSettled(Array.from({ length: Math.min(limit, items.length) }, async () => {
   236	    while (!failed && next < items.length) {
   237	      const index = next++;
   238	      try {
   239	        results[index] = await fn(items[index], index);
   240	      } catch (error) {
   241	        failed = true;
   242	        throw error;
   243	      }
   244	    }
   245	  }));
   246	  for (const worker of workers) if (worker.status === "rejected") throw worker.reason;
   247	  return results;
   248	}

