import { ToolError, type ToolOutput, appToolImpls, toolImpls } from "./tools";

export const APP_URI = "ui://atlas/app.html";
export const APP_MIME = "text/html;profile=mcp-app";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const APP_HTML = path.join(ROOT, "dist/web/index.html");

/** Monochrome 20×20 sidebar icon (currentColor), per the plugin icon guidelines. */
const ICON = `data:image/svg+xml;base64,${Buffer.from(
  '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.33" stroke-linecap="round" stroke-linejoin="round"><path d="M2.67 5.33 7.33 3.33l5.34 2.34 4.66-2v11l-4.66 2-5.34-2.34-4.66 2z"/><path d="M7.33 3.33v11M12.67 5.67v11"/></svg>',
).toString("base64")}`;

const INSTRUCTIONS = `Atlas maps the architecture of a code repository and keeps the map current on every push.
- map_repo: map a GitHub repo (or reuse the cached map). Mapping runs in the background with live progress in the Atlas view.
- trace_flow: answer "what happens when …" by animating a request hop by hop, with the code behind each step.
- blast_radius: "what breaks if X goes down?"
- explain_component: details and cited dependencies of one component.
- architecture_drift: show how recent pushes changed the architecture (layering violations, new dependencies).
Every dependency Atlas shows is backed by a file:line citation from the code; Atlas drops anything it can't cite.
When an atlas.architecture_drift event arrives, call architecture_drift with its repo and reportId to show it, then explain the most severe finding in one or two sentences.`;

export async function appHtml(opts: { standalone?: boolean } = {}): Promise<string> {
  const html = existsSync(APP_HTML)
    ? await readFile(APP_HTML, "utf8")
    : "<!doctype html><meta charset=utf-8><body style='font:14px system-ui;padding:24px'>Atlas UI not built yet: run <code>npm run build:web</code>.</body>";
  if (!opts.standalone) return html;
  return html.replace("<head>", `<head><script>window.__ATLAS_STANDALONE__=true</script>`);
}

function toResult(out: ToolOutput) {
  return {
    content: [{ type: "text" as const, text: out.text }],
    structuredContent: out.structured,
  };
}

function toErrorResult(err: unknown) {
  const message = err instanceof ToolError ? err.message : `Atlas error: ${(err as Error).message ?? String(err)}`;
  if (!(err instanceof ToolError)) console.error(err);
  return { content: [{ type: "text" as const, text: message }], isError: true };
}

const repoArg = z.string().optional().describe('Repository, e.g. "owner/name" or a GitHub URL. Defaults to the most recently mapped repo.');

/** _meta for tools that render the Atlas view. */
function uiMeta(opts: { invoking: string; invoked: string; fullscreen?: boolean; entrypoints?: boolean }) {
  return {
    ui: { resourceUri: APP_URI, visibility: ["model", "app"] },
    "openai/outputTemplate": APP_URI,
    "openai/widgetAccessible": true,
    "openai/toolInvocation/invoking": opts.invoking,
    "openai/toolInvocation/invoked": opts.invoked,
    ...(opts.entrypoints || opts.fullscreen
      ? {
          "openai/ui": {
            ...(opts.entrypoints ? { entrypoints: [{ type: "global" }, { type: "thread" }] } : {}),
            ...(opts.fullscreen ? { preferredModelDisplayMode: "fullscreen" } : {}),
          },
        }
      : {}),
  };
}

const appOnly = { ui: { visibility: ["app"] } };
const readOnly = { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false };

export function createAtlasServer(): McpServer {
  const server = new McpServer(
    {
      name: "atlas",
      title: "Atlas",
      version: "0.1.0",
      description: "Google Maps for your codebase: a live, verified architecture map inside ChatGPT.",
      icons: [{ src: ICON, mimeType: "image/svg+xml", sizes: ["20x20"] }],
    },
    {
      // `events` = MCP Events (draft). Cast: not yet part of the SDK's capability types.
      capabilities: { tools: {}, resources: {}, events: { listChanged: false } } as Record<string, object>,
      instructions: INSTRUCTIONS,
    },
  );

  // ---------------------------------------------------------------- UI resource
  const resourceMeta = {
    ui: { prefersBorder: true, csp: { connectDomains: [], resourceDomains: [] } },
    "openai/ui": { availableDisplayModes: ["inline", "fullscreen", "pip"] },
    "openai/widgetDescription": "Interactive architecture map: components, cited dependencies, animated request flows, blast radius and drift.",
    "openai/widgetPrefersBorder": true,
  };
  server.registerResource(
    "atlas-app",
    APP_URI,
    { title: "Atlas", description: "The Atlas architecture map", mimeType: APP_MIME, _meta: resourceMeta },
    async () => ({ contents: [{ uri: APP_URI, mimeType: APP_MIME, text: await appHtml(), _meta: resourceMeta }] }),
  );

  // ---------------------------------------------------------------- model-facing tools
  const tool = <S extends z.ZodObject>(
    name: keyof typeof toolImpls,
    config: { title: string; description: string; inputSchema: S; _meta?: Record<string, unknown>; annotations?: Record<string, boolean> },
  ) => {
    const impl = toolImpls[name] as (args: z.infer<S>) => Promise<ToolOutput>;
    server.registerTool(
      name,
      { ...config, icons: [{ src: ICON, mimeType: "image/svg+xml" }], annotations: { ...readOnly, ...config.annotations } },
      async (args: z.infer<S>) => {
        try {
          return toResult(await impl(args));
        } catch (err) {
          return toErrorResult(err);
        }
      },
    );
  };

  tool("atlas", {
    title: "Atlas",
    description: "Open Atlas: the interactive architecture map of your mapped repositories.",
    inputSchema: z.object({ repo: repoArg }),
    _meta: uiMeta({ invoking: "Opening Atlas…", invoked: "Atlas is open", entrypoints: true, fullscreen: true }),
  });

  tool("map_repo", {
    title: "Map a repository",
    description:
      "Map the architecture of a GitHub repository: its components (frontends, APIs, services, workers, databases, " +
      "queues, third-party services), the dependencies between them with file:line evidence, and its main request flows. " +
      "Use when the user wants to understand, onboard onto, or visualise a codebase. Returns quickly; mapping continues " +
      "in the background with live progress in the Atlas view.",
    inputSchema: z.object({
      repo: z.string().describe('GitHub repo URL or "owner/name"'),
      branch: z.string().optional().describe("Branch to map (default: the repo's default branch)"),
      force: z.boolean().optional().describe("Re-map even if this commit is already mapped"),
    }),
    _meta: uiMeta({ invoking: "Mapping the repository…", invoked: "Map ready", fullscreen: true }),
    annotations: { idempotentHint: false, openWorldHint: true },
  });

  tool("trace_flow", {
    title: "Trace a flow",
    description:
      'Answer "what happens when …" questions (e.g. "what happens when a user places an order?") by tracing the request ' +
      "hop by hop through the mapped architecture. Animates the path in the Atlas view with the code behind each step.",
    inputSchema: z.object({ question: z.string().describe("The user's question about a flow or request"), repo: repoArg }),
    _meta: uiMeta({ invoking: "Tracing the flow…", invoked: "Flow traced" }),
  });

  tool("blast_radius", {
    title: "Blast radius",
    description: 'Show what breaks if a component goes down ("what if Redis dies?"): impacted components and broken flows.',
    inputSchema: z.object({ component: z.string().describe('Component name or id, e.g. "Redis" or "orders-api"'), repo: repoArg }),
    _meta: uiMeta({ invoking: "Simulating the outage…", invoked: "Blast radius ready" }),
  });

  tool("explain_component", {
    title: "Explain a component",
    description: "Explain one component of the mapped architecture: its role, files, and every dependency in and out with file:line citations.",
    inputSchema: z.object({ component: z.string().describe("Component name or id"), repo: repoArg }),
  });

  tool("architecture_drift", {
    title: "Architecture drift",
    description:
      "Show how recent pushes changed the architecture: new or removed components and dependencies, layering violations " +
      "(e.g. a frontend querying the database directly), new third-party services and broken flows. Call this when an " +
      "atlas.architecture_drift event arrives, passing its reportId.",
    inputSchema: z.object({
      repo: repoArg,
      reportId: z.string().optional().describe("A specific drift report id (from an atlas.architecture_drift event)"),
      limit: z.number().int().min(1).max(20).optional(),
    }),
    _meta: uiMeta({ invoking: "Checking architecture drift…", invoked: "Drift report ready" }),
  });

  tool("check_drift", {
    title: "Check for drift now",
    description: "Review commits pushed since the last map right now (instead of waiting for the GitHub webhook).",
    inputSchema: z.object({ repo: repoArg }),
    _meta: uiMeta({ invoking: "Reviewing new commits…", invoked: "Review started" }),
    annotations: { idempotentHint: false, openWorldHint: true },
  });

  // ---------------------------------------------------------------- app-only tools (UI data)
  const appTool = <S extends z.ZodObject>(name: keyof typeof appToolImpls, description: string, inputSchema: S) => {
    const impl = appToolImpls[name] as (args: z.infer<S>) => Promise<Record<string, unknown>>;
    server.registerTool(name, { description, inputSchema, annotations: readOnly, _meta: appOnly }, async (args: z.infer<S>) => {
      try {
        const data = await impl(args);
        return { content: [{ type: "text" as const, text: "ok" }], structuredContent: data };
      } catch (err) {
        return toErrorResult(err);
      }
    });
  };
  appTool("atlas_graph", "Full graph for the Atlas UI", z.object({ repo: z.string().optional(), sha: z.string().optional() }));
  appTool("atlas_job", "Mapping job progress for the Atlas UI", z.object({ jobId: z.string() }));
  appTool("atlas_changes", "Drift reports newer than a given one, for live updates", z.object({ repo: z.string().optional(), after: z.string().optional() }));
  appTool("atlas_repos", "Mapped repositories", z.object({}));

  // ---------------------------------------------------------------- MCP Events
  const wrap = <P, R>(fn: (p: P) => Promise<R> | R) => async (params: P) => {
    try {
      return (await fn(params)) as Record<string, unknown>;
    } catch (err) {
      if (err instanceof EventsError) throw new ProtocolError(err.code, err.message, err.data);
      throw err;
    }
  };
  const loose = z.looseObject({}).optional();
  server.server.setRequestHandler("events/list", { params: loose }, wrap(() => listEvents()));
  server.server.setRequestHandler(
    "events/subscribe",
    {
      params: z.looseObject({
        name: z.string(),
        arguments: z.record(z.string(), z.unknown()).optional(),
        delivery: z.looseObject({ mode: z.string().optional(), url: z.string().optional(), secret: z.string().optional() }).optional(),
        cursor: z.string().nullable().optional(),
        maxAgeMs: z.number().optional(),
        ttlMs: z.number().optional(),
      }),
    },
    wrap((p) => subscribe(p)),
  );
  server.server.setRequestHandler(
    "events/unsubscribe",
    {
      params: z.looseObject({
        name: z.string().optional(),
        id: z.string().optional(),
        arguments: z.record(z.string(), z.unknown()).optional(),
        delivery: z.looseObject({ url: z.string().optional() }).optional(),
      }),
    },
    wrap((p) => unsubscribe(p)),
  );

  return server;
}

// Atlas HTTP server.
//   /mcp              MCP endpoint for ChatGPT (MCP 2026-07-28 + stateless 2025 fallback)
//   /webhooks/github  GitHub push webhooks → incremental architecture review
//   /hooks/local      same, for local repos (called from a git post-commit hook)
//   /app              the Atlas UI outside ChatGPT (standalone mode)
//   /api/tools/:name  REST access to the tools (standalone UI, scripts, tests)
import { createMcpHandler } from "@modelcontextprotocol/server";
import { toNodeHandler } from "@modelcontextprotocol/node";
import express, { type NextFunction, type Request, type Response } from "express";
import { emitDrift, subscriptionCount } from "./events";
import { commentOnCommit, githubWebhook } from "./github";
import { onDrift, startReviewJob } from "./jobs";
import { appHtml, createAtlasServer } from "./mcp";
import { resolveRepo } from "./repo";
import { findRepo, getRepo } from "./store";
import { ToolError, appToolImpls, toolImpls } from "./tools";

const PORT = Number(process.env.PORT ?? 8787);
const publicUrl = () => process.env.PUBLIC_URL?.replace(/\/+$/, "");

const app = express();
app.disable("x-powered-by");
app.set("trust proxy", true);

// Permissive CORS so MCP Inspector and the standalone UI can talk to us.
app.use((req: Request, res: Response, next: NextFunction) => {
  res.setHeader("Access-Control-Allow-Origin", req.header("origin") ?? "*");
  res.setHeader("Access-Control-Allow-Methods", "GET,POST,DELETE,OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "content-type,authorization,mcp-protocol-version,mcp-session-id,last-event-id,mcp-method,mcp-name");
  res.setHeader("Access-Control-Expose-Headers", "mcp-session-id,mcp-protocol-version");
  if (req.method === "OPTIONS") {
    res.sendStatus(204);
    return;
  }
  next();
});

// GitHub signs the raw bytes, so this route must not JSON-parse first.
app.post("/webhooks/github", express.raw({ type: () => true, limit: "25mb" }), githubWebhook);

app.post("/hooks/local", express.json(), (req: Request, res: Response) => {
  const input = String(req.body?.repo ?? "");
  let key: string | undefined;
  try {
    key = findRepo(input)?.repo.key ?? resolveRepo(input).key;
  } catch {
    key = undefined;
  }
  const job = key && getRepo(key) ? startReviewJob(key, { source: "local" }) : undefined;
  res.status(job ? 202 : 404).json(job ? { jobId: job.id } : { error: "repo not mapped" });
});

// MCP
const mcp = createMcpHandler(() => createAtlasServer(), {
  legacy: "stateless",
  onerror: (err) => console.error("[mcp]", err),
});
const mcpNode = toNodeHandler(mcp);
app.all("/mcp", express.json({ limit: "4mb" }), (req: Request, res: Response) => {
  if (process.env.ATLAS_DEBUG) console.log(`[mcp] ${req.method} ${(req.body as { method?: string })?.method ?? ""}`);
  void mcpNode(req, res, req.body);
});

// REST tools
app.post("/api/tools/:name", express.json({ limit: "2mb" }), async (req: Request, res: Response) => {
  const name = String(req.params.name);
  const impl =
    (toolImpls as Record<string, (a: unknown) => Promise<unknown>>)[name] ??
    (appToolImpls as Record<string, (a: unknown) => Promise<unknown>>)[name];
  if (!impl) {
    res.status(404).json({ error: `unknown tool ${name}` });
    return;
  }
  try {
    const out = (await impl(req.body ?? {})) as Record<string, unknown>;
    // Model-facing tools return { text, structured }; app tools return data directly.
    res.json("structured" in out ? { structuredContent: out.structured, text: out.text } : { structuredContent: out });
  } catch (err) {
    res.status(err instanceof ToolError ? 400 : 500).json({ error: (err as Error).message });
  }
});

// UI
app.get("/app", async (_req: Request, res: Response) => {
  res.type("html").send(await appHtml({ standalone: true }));
});
app.get("/", (_req: Request, res: Response) => res.redirect("/app"));
app.get("/health", (_req: Request, res: Response) => {
  res.json({ ok: true, model: process.env.ATLAS_MODEL ?? "gpt-6.1-sol", openaiKey: !!process.env.OPENAI_API_KEY, subscriptions: subscriptionCount() });
});

// Drift fan-out: MCP Events subscribers + optional GitHub commit comment.
onDrift((report) => {
  void emitDrift(report, publicUrl()).then((n) => n && console.log(`[events] ${report.id} → ${n} subscriber(s)`));
  void commentOnCommit(report, publicUrl());
});

app.listen(PORT, () => {
  console.log(`Atlas on http://localhost:${PORT}  (MCP: /mcp, UI: /app)`);
  if (!process.env.OPENAI_API_KEY) console.warn("⚠ OPENAI_API_KEY is not set: mapping will fail until you add it to .env");
});

