// The map canvas: React Flow with custom component nodes and dependency edges.
// Visual state (trace / blast / drift / selection) arrives as plain maps so this
// component stays dumb and fast.
import {
  Background,
  BackgroundVariant,
  BaseEdge,
  Controls,
  type Edge,
  EdgeLabelRenderer,
  type EdgeProps,
  Handle,
  MarkerType,
  type Node,
  type NodeProps,
  Position,
  ReactFlow,
  getBezierPath,
  useReactFlow,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";
import { memo, useEffect, useMemo } from "react";
import type { AtlasEdge, AtlasGraph, AtlasNode, NodeKind } from "../../shared/graph";
import { KIND_LABEL, KindIcon } from "./icons";
import { NODE_W, layoutGraph } from "./layout";

export type NodeVisual = "base" | "dim" | "selected" | "path" | "active" | "dead" | "impacted" | "new" | "removed" | "flagged";
export type EdgeVisual = "base" | "dim" | "selected" | "visited" | "active" | "blast" | "added" | "flagged" | "removed";

export interface GraphProps {
  graph: AtlasGraph;
  ghostNodes?: AtlasNode[];
  ghostEdges?: AtlasEdge[];
  nodeVisual: Record<string, NodeVisual>;
  edgeVisual: Record<string, EdgeVisual>;
  /** Changes on every trace step so the packet animation restarts. */
  pulseKey?: string;
  badges?: Record<string, string>;
  defaultNodeVisual?: NodeVisual;
  defaultEdgeVisual?: EdgeVisual;
  onNodeClick?: (id: string) => void;
  onEdgeClick?: (id: string) => void;
  onPaneClick?: () => void;
  fitKey?: string;
}

interface AtlasNodeData extends Record<string, unknown> {
  node: AtlasNode;
  visual: NodeVisual;
  badge?: string;
}

interface AtlasEdgeData extends Record<string, unknown> {
  edge: AtlasEdge;
  visual: EdgeVisual;
  pulseKey?: string;
}

const ComponentNode = memo(function ComponentNode({ data }: NodeProps<Node<AtlasNodeData>>) {
  const { node, visual, badge } = data;
  return (
    <div className={`an an-${visual}`} data-kind={node.kind} title={node.summary}>
      <Handle id="l" type="target" position={Position.Left} className="an-handle" />
      <Handle id="r" type="source" position={Position.Right} className="an-handle" />
      <Handle id="ls" type="source" position={Position.Left} className="an-handle" />
      <Handle id="rt" type="target" position={Position.Right} className="an-handle" />
      <div className="an-icon">
        <KindIcon kind={node.kind} />
      </div>
      <div className="an-text">
        <div className="an-label">{node.label}</div>
        <div className="an-sub">{node.tech || KIND_LABEL[node.kind as NodeKind]}</div>
      </div>
      {badge && <div className={`an-badge an-badge-${visual}`}>{badge}</div>}
      {visual === "dead" && <div className="an-x" aria-label="down">✕</div>}
    </div>
  );
});

const DependencyEdge = memo(function DependencyEdge(props: EdgeProps<Edge<AtlasEdgeData>>) {
  const { id, sourceX, sourceY, targetX, targetY, sourcePosition, targetPosition, data, markerEnd } = props;
  const [path, labelX, labelY] = getBezierPath({ sourceX, sourceY, targetX, targetY, sourcePosition, targetPosition, curvature: 0.28 });
  const visual = data?.visual ?? "base";
  const edge = data?.edge;
  const showLabel = visual === "active" || visual === "selected" || visual === "added" || visual === "flagged" || visual === "removed";
  // Messages flow queue → worker even though the dependency points worker → queue.
  const reverse = edge?.kind === "consume";
  return (
    <>
      {(visual === "active" || visual === "added" || visual === "flagged" || visual === "blast") && (
        <path d={path} className={`ae-glow ae-glow-${visual}`} fill="none" />
      )}
      <BaseEdge id={id} path={path} markerEnd={markerEnd} className={`ae ae-${visual}`} interactionWidth={18} />
      {visual === "active" && (
        <circle key={data?.pulseKey} r={5.5} className="ae-packet">
          <animateMotion dur="1.05s" repeatCount="1" fill="freeze" path={path} {...(reverse ? { keyPoints: "1;0", keyTimes: "0;1", calcMode: "linear" } : {})} />
        </circle>
      )}
      {visual === "visited" && <circle r={3} className="ae-dot" cx={labelX} cy={labelY} />}
      {showLabel && edge && (
        <EdgeLabelRenderer>
          <div className={`ae-label ae-label-${visual}`} style={{ transform: `translate(-50%, -50%) translate(${labelX}px, ${labelY}px)` }}>
            <span className="ae-kind">{edge.kind}</span> {edge.label}
          </div>
        </EdgeLabelRenderer>
      )}
    </>
  );
});

const nodeTypes = { component: ComponentNode };
const edgeTypes = { dependency: DependencyEdge };

const markerColor: Record<EdgeVisual, string> = {
  base: "var(--edge)",
  dim: "var(--edge-dim)",
  selected: "var(--accent)",
  visited: "var(--accent)",
  active: "var(--accent)",
  blast: "var(--danger)",
  added: "var(--ok)",
  flagged: "var(--danger)",
  removed: "var(--faint)",
};

function FitOnChange({ fitKey }: { fitKey?: string }) {
  const rf = useReactFlow();
  useEffect(() => {
    const t = setTimeout(() => rf.fitView({ padding: 0.12, duration: 350 }), 30);
    return () => clearTimeout(t);
  }, [fitKey, rf]);
  return null;
}

export function Graph(props: GraphProps) {
  const { graph, ghostNodes = [], ghostEdges = [], nodeVisual, edgeVisual, pulseKey, badges = {} } = props;
  const defNode = props.defaultNodeVisual ?? "base";
  const defEdge = props.defaultEdgeVisual ?? "base";

  const allNodes = useMemo(() => {
    const ids = new Set(graph.nodes.map((n) => n.id));
    return [...graph.nodes, ...ghostNodes.filter((n) => !ids.has(n.id))];
  }, [graph, ghostNodes]);
  const allEdges = useMemo(() => {
    const ids = new Set(graph.edges.map((e) => e.id));
    return [...graph.edges, ...ghostEdges.filter((e) => !ids.has(e.id))];
  }, [graph, ghostEdges]);

  const positions = useMemo(() => layoutGraph(allNodes, allEdges), [allNodes, allEdges]);

  const rfNodes: Node<AtlasNodeData>[] = useMemo(
    () =>
      allNodes.map((n) => ({
        id: n.id,
        type: "component",
        position: positions.get(n.id) ?? { x: 0, y: 0 },
        data: { node: n, visual: nodeVisual[n.id] ?? defNode, badge: badges[n.id] },
        draggable: true,
        selectable: false,
      })),
    [allNodes, positions, nodeVisual, defNode, badges],
  );

  const rfEdges: Edge<AtlasEdgeData>[] = useMemo(
    () =>
      allEdges
        .filter((e) => positions.has(e.from) && positions.has(e.to))
        .map((e) => {
          const visual = edgeVisual[e.id] ?? defEdge;
          // Pick handles by where the nodes ended up, so arrows never loop around.
          const forward = (positions.get(e.to)!.x ?? 0) >= (positions.get(e.from)!.x ?? 0) + NODE_W / 2;
          return {
            id: e.id,
            source: e.from,
            target: e.to,
            sourceHandle: forward ? "r" : "ls",
            targetHandle: forward ? "l" : "rt",
            type: "dependency",
            data: { edge: e, visual, pulseKey },
            markerEnd: { type: MarkerType.ArrowClosed, width: 15, height: 15, color: markerColor[visual] },
            zIndex: visual === "active" || visual === "flagged" || visual === "added" ? 10 : visual === "dim" ? 0 : 1,
          };
        }),
    [allEdges, positions, edgeVisual, defEdge, pulseKey],
  );

  return (
    <ReactFlow
      nodes={rfNodes}
      edges={rfEdges}
      nodeTypes={nodeTypes}
      edgeTypes={edgeTypes}
      fitView
      fitViewOptions={{ padding: 0.12 }}
      minZoom={0.2}
      maxZoom={2}
      proOptions={{ hideAttribution: true }}
      onNodeClick={(_, n) => props.onNodeClick?.(n.id)}
      onEdgeClick={(_, e) => props.onEdgeClick?.(e.id)}
      onPaneClick={() => props.onPaneClick?.()}
      nodesConnectable={false}
      elementsSelectable={false}
    >
      <Background variant={BackgroundVariant.Dots} gap={18} size={1.2} color="var(--grid)" />
      <Controls showInteractive={false} position="bottom-left" />
      <FitOnChange fitKey={props.fitKey} />
    </ReactFlow>
  );
}

// Atlas UI shell: routes ChatGPT tool results to views, polls for live changes,
// runs the trace player and derives the map's visual state.
import { ReactFlowProvider } from "@xyflow/react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { AtlasEdge, AtlasGraph, AtlasNode, DriftReport } from "../../shared/graph";
import { shortSha } from "../../shared/graph";
import { type FlowView, blastRadius, flowView } from "../../server/graph/analysis";
import type { Bridge, HostState, ToolResult } from "./bridge";
import { type EdgeVisual, Graph, type NodeVisual } from "./Graph";
import { AtlasLogo } from "./icons";
import { BlastPanel, DriftPanel, FlowsPanel, Home, NodePanel, OverviewPanel, Progress, TracePanel } from "./panels";

export interface JobView {
  id: string;
  kind: "map" | "review";
  status: "running" | "done" | "error";
  repoName: string;
  startedAt: string;
  error?: string;
  reportId?: string;
  log: Array<{ agent: string; phase: string; message: string; at: string }>;
}

export interface RepoSummary {
  key: string;
  name: string;
  sha: string | null;
  components: number;
  dependencies: number;
  mapping: string | null;
}

type Mode =
  | { kind: "explore" }
  | { kind: "trace"; flow: FlowView; step: number; playing: boolean }
  | { kind: "blast"; nodeId: string }
  | { kind: "drift"; reportId: string | null };

type Tab = "overview" | "flows" | "drift";

const STEP_MS = 1500;

export function App({ bridge }: { bridge: Bridge }) {
  const [host, setHost] = useState<HostState>(bridge.host());
  const [repos, setRepos] = useState<RepoSummary[]>([]);
  const [repoKey, setRepoKey] = useState<string | null>(null);
  const [graph, setGraph] = useState<AtlasGraph | null>(null);
  const [jobId, setJobId] = useState<string | null>(null);
  const [job, setJob] = useState<JobView | null>(null);
  const [reports, setReports] = useState<DriftReport[]>([]);
  const [reviewing, setReviewing] = useState<string | null>(null);
  const [mode, setMode] = useState<Mode>({ kind: "explore" });
  const [tab, setTab] = useState<Tab>("overview");
  const [selected, setSelected] = useState<string | null>(null);
  const [toast, setToast] = useState<DriftReport | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [ready, setReady] = useState(false);
  const lastReport = useRef<string | undefined>(undefined);
  const pendingTraceRef = useRef<FlowView | null>(null);

  // ------------------------------------------------------------ data loading
  const loadGraph = useCallback(
    async (key: string) => {
      const r = await bridge.callTool<{ graph: AtlasGraph | null; mapping: string | null }>("atlas_graph", { repo: key });
      if (r.structuredContent.graph) setGraph(r.structuredContent.graph);
      if (r.structuredContent.mapping) setJobId(r.structuredContent.mapping);
      return r.structuredContent.graph;
    },
    [bridge],
  );

  const loadRepos = useCallback(async () => {
    const r = await bridge.callTool<{ repos: RepoSummary[] }>("atlas_repos", {});
    setRepos(r.structuredContent.repos ?? []);
  }, [bridge]);

  const handleResult = useCallback(
    (r: ToolResult) => {
      setReady(true);
      if (r.isError) {
        setError(r.text ?? "Something went wrong");
        return;
      }
      setError(null);
      const sc = r.structuredContent as Record<string, any>;
      if (Array.isArray(sc.repos) && sc.view !== "drift") setRepos(sc.repos);
      if (sc.repoKey) setRepoKey(sc.repoKey);
      if (sc.jobId && (sc.status === "running" || sc.view === "drift")) setJobId(sc.jobId);
      switch (sc.view) {
        case "trace":
          pendingTraceRef.current = sc.flow as FlowView;
          setSelected(null);
          setMode({ kind: "trace", flow: sc.flow, step: 0, playing: true });
          setTab("flows");
          break;
        case "blast":
          setSelected(null);
          setMode({ kind: "blast", nodeId: sc.nodeId });
          break;
        case "drift":
          setMode({ kind: "drift", reportId: sc.reportId ?? null });
          setTab("drift");
          break;
        default:
          setMode({ kind: "explore" });
      }
    },
    [],
  );

  // ------------------------------------------------------------ boot
  useEffect(() => {
    let cancelled = false;
    (async () => {
      await bridge.connect();
      if (cancelled) return;
      setHost(bridge.host());
      bridge.onHostChange(setHost);
      bridge.onToolResult(handleResult);
      if (bridge.mode === "standalone") {
        const q = new URLSearchParams(location.search);
        const r = await bridge.callTool("atlas", q.get("repo") ? { repo: q.get("repo") } : {});
        handleResult(r);
        if (q.get("drift")) {
          setMode({ kind: "drift", reportId: q.get("drift") });
          setTab("drift");
        }
      } else {
        // Opened from the sidebar with no tool result yet: show what we have.
        setTimeout(() => {
          if (!cancelled) {
            setReady(true);
            void loadRepos();
          }
        }, 1200);
      }
    })().catch((e) => setError(String(e)));
    return () => {
      cancelled = true;
    };
  }, [bridge, handleResult, loadRepos]);

  useEffect(() => {
    document.documentElement.dataset.theme = host.theme;
    document.documentElement.dataset.display = host.displayMode;
  }, [host]);

  // Repo changed → load its graph and drift history.
  useEffect(() => {
    if (!repoKey) return;
    lastReport.current = undefined;
    setReports([]);
    void loadGraph(repoKey);
    void bridge.callTool<{ reports: DriftReport[] }>("atlas_changes", { repo: repoKey }).then((r) => {
      const list = r.structuredContent.reports ?? [];
      setReports(list);
      lastReport.current = list[0]?.id;
    });
  }, [repoKey, bridge, loadGraph]);

  // Poll an active job (mapping or review).
  useEffect(() => {
    if (!jobId) return;
    let stop = false;
    const tick = async () => {
      const r = await bridge.callTool<{ job: JobView | null }>("atlas_job", { jobId });
      const j = r.structuredContent.job;
      if (stop) return;
      setJob(j);
      if (!j || j.status !== "running") {
        setJobId(null);
        if (j?.status === "done" && repoKey) {
          await loadGraph(repoKey);
          if (j.kind === "review") await pollChanges(true);
        }
      }
    };
    void tick();
    const t = setInterval(tick, 800);
    return () => {
      stop = true;
      clearInterval(t);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [jobId, bridge, repoKey, loadGraph]);

  // Live: watch for new drift reports (pushes reviewed by the webhook).
  const pollChanges = useCallback(
    async (focus = false) => {
      if (!repoKey) return;
      const r = await bridge.callTool<{ reports: DriftReport[]; reviewing: { id: string } | null }>("atlas_changes", {
        repo: repoKey,
        after: lastReport.current,
      });
      const fresh = r.structuredContent.reports ?? [];
      setReviewing(r.structuredContent.reviewing?.id ?? null);
      if (fresh.length === 0) return;
      lastReport.current = fresh[0].id;
      setReports((prev) => [...fresh, ...prev.filter((p) => !fresh.some((f) => f.id === p.id))]);
      await loadGraph(repoKey);
      const newest = fresh[0];
      if (newest.maxSeverity !== "none") setToast(newest);
      if (focus || newest.maxSeverity === "critical" || newest.maxSeverity === "warning") {
        setSelected(null);
        setMode({ kind: "drift", reportId: newest.id });
        setTab("drift");
      }
    },
    [repoKey, bridge, loadGraph],
  );

  useEffect(() => {
    if (!repoKey || !graph) return;
    const t = setInterval(() => void pollChanges(), 3000);
    return () => clearInterval(t);
  }, [repoKey, graph, pollChanges]);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 9000);
    return () => clearTimeout(t);
  }, [toast]);

  // ------------------------------------------------------------ trace player
  useEffect(() => {
    if (mode.kind !== "trace" || !mode.playing) return;
    const t = setTimeout(() => {
      setMode((m) => {
        if (m.kind !== "trace") return m;
        const last = m.flow.steps.length - 1;
        return m.step >= last ? { ...m, playing: false } : { ...m, step: m.step + 1 };
      });
    }, STEP_MS);
    return () => clearTimeout(t);
  }, [mode]);

  // ------------------------------------------------------------ model context
  const nodesById = useMemo(() => new Map((graph?.nodes ?? []).map((n) => [n.id, n])), [graph]);
  useEffect(() => {
    if (!graph) return;
    const repo = `${graph.repo.name}@${shortSha(graph.sha)}`;
    let text = "";
    if (mode.kind === "trace") {
      const s = mode.flow.steps[mode.step];
      text = s ? `In Atlas (${repo}) the user is watching the "${mode.flow.name}" flow, step ${s.index}/${mode.flow.steps.length}: ${s.from.label} → ${s.to.label} (${s.label}).` : "";
    } else if (mode.kind === "blast") {
      text = `In Atlas (${repo}) the user is simulating an outage of ${nodesById.get(mode.nodeId)?.label ?? mode.nodeId}.`;
    } else if (mode.kind === "drift") {
      const r = reports.find((x) => x.id === mode.reportId) ?? reports[0];
      text = r ? `In Atlas (${repo}) the user is viewing architecture drift for ${shortSha(r.toSha)} ("${r.commits[0]?.message ?? ""}"): ${r.summary}` : "";
    } else if (selected) {
      const n = nodesById.get(selected);
      text = n ? `In Atlas (${repo}) the user selected the component "${n.label}" (${n.kind}${n.tech ? `, ${n.tech}` : ""}): ${n.summary}` : "";
    }
    if (!text) return;
    const t = setTimeout(() => void bridge.updateContext(text), 400);
    return () => clearTimeout(t);
  }, [graph, mode, selected, reports, nodesById, bridge]);

  // ------------------------------------------------------------ derived visuals
  const activeReport = mode.kind === "drift" ? (reports.find((r) => r.id === mode.reportId) ?? reports[0]) : undefined;

  const visuals = useMemo(() => {
    const nodeVisual: Record<string, NodeVisual> = {};
    const edgeVisual: Record<string, EdgeVisual> = {};
    const badges: Record<string, string> = {};
    let ghostNodes: AtlasNode[] = [];
    let ghostEdges: AtlasEdge[] = [];
    let defaultNode: NodeVisual = "base";
    let defaultEdge: EdgeVisual = "base";
    let pulseKey: string | undefined;
    if (!graph) return { nodeVisual, edgeVisual, badges, ghostNodes, ghostEdges, defaultNode, defaultEdge, pulseKey };

    if (mode.kind === "trace") {
      defaultNode = "dim";
      defaultEdge = "dim";
      mode.flow.steps.forEach((s, i) => {
        if (i > mode.step) return;
        edgeVisual[s.edgeId] = i === mode.step ? "active" : "visited";
        nodeVisual[s.from.id] = nodeVisual[s.from.id] === "active" ? "active" : "path";
        nodeVisual[s.to.id] = "path";
      });
      const cur = mode.flow.steps[mode.step];
      if (cur) {
        nodeVisual[cur.to.id] = "active";
        badges[cur.to.id] = String(cur.index);
      }
      pulseKey = `${mode.flow.id}-${mode.step}`;
    } else if (mode.kind === "blast") {
      const b = blastRadius(graph, mode.nodeId);
      if (b) {
        defaultNode = "dim";
        defaultEdge = "dim";
        nodeVisual[b.node.id] = "dead";
        badges[b.node.id] = "DOWN";
        for (const i of b.impacted) {
          nodeVisual[i.node.id] = "impacted";
          badges[i.node.id] = i.depth === 1 ? "direct" : `${i.depth} hops`;
        }
        for (const id of b.edgeIds) edgeVisual[id] = "blast";
      }
    } else if (mode.kind === "drift" && activeReport) {
      defaultNode = "dim";
      defaultEdge = "dim";
      const flaggedEdges = new Set(activeReport.findings.filter((f) => f.severity !== "info").flatMap((f) => f.edgeIds));
      const flaggedNodes = new Set(activeReport.findings.filter((f) => f.severity !== "info").flatMap((f) => f.nodeIds));
      for (const e of activeReport.added.edges) {
        edgeVisual[e.id] = flaggedEdges.has(e.id) ? "flagged" : "added";
        nodeVisual[e.from] ??= "base";
        nodeVisual[e.to] ??= "base";
      }
      for (const n of activeReport.added.nodes) {
        nodeVisual[n.id] = "new";
        badges[n.id] = "NEW";
      }
      for (const id of flaggedNodes) {
        if (nodeVisual[id] !== "new") nodeVisual[id] = "flagged";
      }
      ghostNodes = activeReport.removed.nodes;
      ghostEdges = activeReport.removed.edges;
      for (const n of ghostNodes) {
        nodeVisual[n.id] = "removed";
        badges[n.id] = "REMOVED";
      }
      for (const e of ghostEdges) edgeVisual[e.id] = "removed";
    } else if (selected) {
      defaultNode = "dim";
      defaultEdge = "dim";
      nodeVisual[selected] = "selected";
      for (const e of graph.edges) {
        if (e.from === selected || e.to === selected) {
          edgeVisual[e.id] = "selected";
          nodeVisual[e.from === selected ? e.to : e.from] ??= "path";
        }
      }
    }
    return { nodeVisual, edgeVisual, badges, ghostNodes, ghostEdges, defaultNode, defaultEdge, pulseKey };
  }, [graph, mode, selected, activeReport]);

  // ------------------------------------------------------------ actions
  const ask = (text: string) => void bridge.sendMessage(text);
  const startTrace = (flowId: string) => {
    if (!graph) return;
    const f = graph.flows.find((x) => x.id === flowId);
    if (!f) return;
    setSelected(null);
    setMode({ kind: "trace", flow: flowView(graph, f), step: 0, playing: true });
    setTab("flows");
  };
  const exitMode = () => {
    setMode({ kind: "explore" });
  };
  const mapRepo = async (repo: string) => {
    setError(null);
    const r = await bridge.callTool("map_repo", { repo });
    handleResult(r);
  };
  const checkNow = async () => {
    if (!graph) return;
    const r = await bridge.callTool("check_drift", { repo: graph.repo.key });
    handleResult(r);
  };

  // ------------------------------------------------------------ render
  const inline = bridge.mode === "host" && host.displayMode === "inline";
  const height = inline ? Math.min(host.maxHeight ?? 620, 620) : undefined;
  const mapping = job && job.status === "running" && job.kind === "map";

  if (!ready) return <div className="boot">Opening Atlas…</div>;

  if (!repoKey || (!graph && !mapping && !jobId)) {
    return (
      <div className="shell" style={{ height }}>
        <Home repos={repos} onOpen={(k) => setRepoKey(k)} onMap={mapRepo} error={error} />
      </div>
    );
  }

  if (!graph) {
    return (
      <div className="shell" style={{ height }}>
        <Progress job={job} />
      </div>
    );
  }

  const unseenDrift = reports.filter((r) => r.maxSeverity !== "none").length;
  let panel;
  if (mode.kind === "trace") {
    panel = (
      <TracePanel
        flow={mode.flow}
        step={mode.step}
        playing={mode.playing}
        onStep={(step) => setMode({ ...mode, step, playing: false })}
        onPlay={() => setMode({ ...mode, playing: !mode.playing, step: !mode.playing && mode.step >= mode.flow.steps.length - 1 ? 0 : mode.step })}
        onClose={exitMode}
        onAsk={() => ask(`Walk me through the "${mode.flow.name}" flow in ${graph.repo.name}: what could go wrong at each step?`)}
      />
    );
  } else if (mode.kind === "blast") {
    panel = <BlastPanel graph={graph} nodeId={mode.nodeId} onClose={exitMode} onAsk={(t) => ask(t)} onTrace={startTrace} />;
  } else if (tab === "drift" || mode.kind === "drift") {
    panel = (
      <DriftPanel
        reports={reports}
        activeId={activeReport?.id ?? null}
        onSelect={(id) => {
          setSelected(null);
          setMode({ kind: "drift", reportId: id });
        }}
        onClose={() => {
          exitMode();
          setTab("overview");
        }}
        onAsk={(t) => ask(t)}
        onCheck={checkNow}
        reviewing={!!reviewing || (job?.kind === "review" && job.status === "running")}
        graph={graph}
      />
    );
  } else if (selected) {
    panel = (
      <NodePanel
        graph={graph}
        nodeId={selected}
        onClose={() => setSelected(null)}
        onSelect={setSelected}
        onBlast={(id) => {
          setSelected(null);
          setMode({ kind: "blast", nodeId: id });
        }}
        onAsk={(t) => ask(t)}
      />
    );
  } else if (tab === "flows") {
    panel = <FlowsPanel graph={graph} onTrace={startTrace} onAsk={(t) => ask(t)} />;
  } else {
    panel = <OverviewPanel graph={graph} onTrace={startTrace} onSelect={setSelected} onAsk={(t) => ask(t)} />;
  }

  const switchTab = (t: Tab) => {
    setTab(t);
    setSelected(null);
    if (t === "drift") setMode({ kind: "drift", reportId: reports[0]?.id ?? null });
    else if (mode.kind === "drift" || mode.kind === "blast" || (t === "overview" && mode.kind === "trace")) setMode({ kind: "explore" });
  };

  return (
    <div className="shell" style={{ height }}>
      <header className="bar">
        <div className="brand">
          <AtlasLogo />
          <span className="brand-name">Atlas</span>
          <span className="repo" title={graph.summary}>
            {graph.repo.name}
          </span>
          <span className="sha" title={`Mapped ${new Date(graph.generatedAt).toLocaleString()} (${graph.mode})`}>
            {shortSha(graph.sha)}
          </span>
        </div>
        <nav className="tabs">
          {(["overview", "flows", "drift"] as Tab[]).map((t) => (
            <button key={t} className={`tab ${tab === t ? "on" : ""}`} onClick={() => switchTab(t)}>
              {t === "overview" ? "Map" : t === "flows" ? "Flows" : "Drift"}
              {t === "drift" && unseenDrift > 0 && <span className="count">{unseenDrift}</span>}
            </button>
          ))}
        </nav>
        <div className="bar-right">
          <span className="verified" title="Every arrow on this map cites the file and line that proves it. Dependencies the agents proposed but Atlas couldn't find in the code were dropped.">
            ✓ {graph.stats.edgesVerified} cited · {graph.stats.edgesDropped} dropped
          </span>
          <span className={`live ${reviewing || (job?.kind === "review" && job.status === "running") ? "busy" : ""}`} title="Atlas reviews every push to this repo">
            <i /> {reviewing || (job?.kind === "review" && job.status === "running") ? "Reviewing push…" : "Live"}
          </span>
          {inline && (
            <button className="icon-btn" title="Open full screen" onClick={() => void bridge.requestDisplayMode("fullscreen")}>
              ⤢
            </button>
          )}
        </div>
      </header>
      <div className="body">
        <main className="canvas">
          <ReactFlowProvider>
            <Graph
              graph={graph}
              ghostNodes={visuals.ghostNodes}
              ghostEdges={visuals.ghostEdges}
              nodeVisual={visuals.nodeVisual}
              edgeVisual={visuals.edgeVisual}
              badges={visuals.badges}
              defaultNodeVisual={visuals.defaultNode}
              defaultEdgeVisual={visuals.defaultEdge}
              pulseKey={visuals.pulseKey}
              fitKey={`${graph.repo.key}-${graph.nodes.length}-${visuals.ghostNodes.length}-${host.displayMode}`}
              onNodeClick={(id) => {
                if (mode.kind !== "explore") setMode({ kind: "explore" });
                if (tab === "drift") setTab("overview");
                setSelected((s) => (s === id ? null : id));
              }}
              onPaneClick={() => {
                if (mode.kind === "explore") setSelected(null);
              }}
            />
          </ReactFlowProvider>
          {toast && (
            <div className={`toast sev-${toast.maxSeverity}`} role="status">
              <strong>{toast.maxSeverity === "critical" ? "Architecture drift" : "Architecture change"}</strong> in {shortSha(toast.toSha)}:{" "}
              {toast.findings[0]?.title ?? toast.summary}
              <button
                onClick={() => {
                  setMode({ kind: "drift", reportId: toast.id });
                  setTab("drift");
                  setToast(null);
                }}
              >
                View
              </button>
            </div>
          )}
          {mode.kind !== "explore" && (
            <div className="mode-pill">
              {mode.kind === "trace" ? `Tracing: ${mode.flow.name}` : mode.kind === "blast" ? `Outage: ${nodesById.get(mode.nodeId)?.label}` : "Drift view"}
              <button onClick={() => (mode.kind === "drift" ? switchTab("overview") : exitMode())} aria-label="Exit">
                ✕
              </button>
            </div>
          )}
          <Legend />
        </main>
        <aside className="side">{panel}</aside>
      </div>
      {error && <div className="err">{error}</div>}
    </div>
  );
}

function Legend() {
  return (
    <div className="legend">
      <span>
        <i className="lg lg-arrow" /> depends on
      </span>
      <span>
        <i className="lg lg-packet" /> request
      </span>
    </div>
  );
}

// Side panels and full-screen states of the Atlas UI.
import { useEffect, useMemo, useRef, useState } from "react";
import type { AtlasGraph, DriftReport, Evidence, NodeKind } from "../../shared/graph";
import { shortSha } from "../../shared/graph";
import { type FlowView, blastRadius } from "../../server/graph/analysis";
import type { JobView, RepoSummary } from "./App";
import { AtlasLogo, KIND_LABEL, KindIcon } from "./icons";

function ago(iso: string): string {
  const s = Math.max(0, (Date.now() - Date.parse(iso)) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

function Cite({ ev }: { ev?: Evidence }) {
  if (!ev) return null;
  return (
    <div className="cite">
      <div className="cite-path">
        {ev.path}:{ev.line}
      </div>
      <code className="cite-code">{ev.snippet}</code>
    </div>
  );
}

function KindChip({ kind }: { kind: NodeKind }) {
  return (
    <span className="kind-chip" data-kind={kind}>
      <KindIcon kind={kind} size={13} />
      {KIND_LABEL[kind]}
    </span>
  );
}

function PanelHead({ title, sub, onClose }: { title: React.ReactNode; sub?: React.ReactNode; onClose?: () => void }) {
  return (
    <div className="ph">
      <div>
        <div className="ph-title">{title}</div>
        {sub && <div className="ph-sub">{sub}</div>}
      </div>
      {onClose && (
        <button className="icon-btn" onClick={onClose} aria-label="Close">
          ✕
        </button>
      )}
    </div>
  );
}

function AskButton({ onClick, children }: { onClick: () => void; children: React.ReactNode }) {
  return (
    <button className="ask" onClick={onClick}>
      <span className="ask-spark">✦</span> {children}
    </button>
  );
}

// ---------------------------------------------------------------- overview

export function OverviewPanel({ graph, onTrace, onSelect, onAsk }: { graph: AtlasGraph; onTrace: (id: string) => void; onSelect: (id: string) => void; onAsk: (t: string) => void }) {
  const byKind = useMemo(() => {
    const m = new Map<NodeKind, AtlasGraph["nodes"]>();
    for (const n of graph.nodes) m.set(n.kind, [...(m.get(n.kind) ?? []), n]);
    return [...m.entries()];
  }, [graph]);
  const s = graph.stats;
  return (
    <div className="panel">
      <PanelHead title="Architecture" sub={`${graph.repo.name} · mapped ${ago(graph.generatedAt)}`} />
      <p className="summary">{graph.summary}</p>
      <div className="chips">
        {graph.stack.map((t) => (
          <span key={t} className="chip">
            {t}
          </span>
        ))}
      </div>
      <div className="stats">
        <div>
          <b>{graph.nodes.length}</b>
          <span>components</span>
        </div>
        <div>
          <b>{graph.edges.length}</b>
          <span>dependencies</span>
        </div>
        <div>
          <b>{graph.flows.length}</b>
          <span>flows</span>
        </div>
      </div>
      <div className="trust">
        <div className="trust-title">✓ Every arrow cites the code</div>
        <div className="trust-body">
          The agents proposed {s.edgesProposed} dependencies. Atlas verified <b>{s.edgesVerified}</b> against the code at {shortSha(graph.sha)} and
          dropped <b>{s.edgesDropped}</b> it couldn't find. {s.files} files read · {s.model}
          {s.durationMs ? ` · ${Math.round(s.durationMs / 1000)}s` : ""}
        </div>
      </div>
      <h4>Flows</h4>
      <div className="list">
        {graph.flows.map((f) => (
          <button key={f.id} className="row" onClick={() => onTrace(f.id)}>
            <span className="row-play">▶</span>
            <span className="row-main">
              <span className="row-title">{f.name}</span>
              <span className="row-sub">{f.trigger}</span>
            </span>
            <span className="row-meta">{f.steps.length} hops</span>
          </button>
        ))}
      </div>
      <h4>Components</h4>
      {byKind.map(([kind, nodes]) => (
        <div key={kind} className="kind-group">
          <KindChip kind={kind} />
          <div className="kind-items">
            {nodes.map((n) => (
              <button key={n.id} className="link" onClick={() => onSelect(n.id)}>
                {n.label}
              </button>
            ))}
          </div>
        </div>
      ))}
      <AskButton onClick={() => onAsk(`Give me a 60-second tour of the ${graph.repo.name} architecture as a new engineer on the team.`)}>Ask ChatGPT for a tour</AskButton>
    </div>
  );
}

export function FlowsPanel({ graph, onTrace, onAsk }: { graph: AtlasGraph; onTrace: (id: string) => void; onAsk: (t: string) => void }) {
  return (
    <div className="panel">
      <PanelHead title="Flows" sub="Requests traced hop by hop through real code" />
      <div className="list">
        {graph.flows.map((f) => (
          <button key={f.id} className="row tall" onClick={() => onTrace(f.id)}>
            <span className="row-play">▶</span>
            <span className="row-main">
              <span className="row-title">{f.name}</span>
              <span className="row-sub">{f.description}</span>
            </span>
            <span className="row-meta">{f.steps.length} hops</span>
          </button>
        ))}
      </div>
      <AskButton onClick={() => onAsk(`In ${graph.repo.name}, what happens when `)}>Ask about another flow…</AskButton>
    </div>
  );
}

// ---------------------------------------------------------------- trace

export function TracePanel(props: {
  flow: FlowView;
  step: number;
  playing: boolean;
  onStep: (i: number) => void;
  onPlay: () => void;
  onClose: () => void;
  onAsk: () => void;
}) {
  const { flow, step } = props;
  const listRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    listRef.current?.querySelector(".step.on")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
  }, [step]);
  return (
    <div className="panel">
      <PanelHead title={flow.name} sub={flow.trigger} onClose={props.onClose} />
      <p className="summary">{flow.description}</p>
      <div className="player">
        <button className="icon-btn" disabled={step === 0} onClick={() => props.onStep(Math.max(0, step - 1))} aria-label="Previous">
          ⏮
        </button>
        <button className="play" onClick={props.onPlay}>
          {props.playing ? "❚❚ Pause" : step >= flow.steps.length - 1 ? "↻ Replay" : "▶ Play"}
        </button>
        <button className="icon-btn" disabled={step >= flow.steps.length - 1} onClick={() => props.onStep(Math.min(flow.steps.length - 1, step + 1))} aria-label="Next">
          ⏭
        </button>
        <span className="player-pos">
          {step + 1} / {flow.steps.length}
        </span>
      </div>
      <div className="steps" ref={listRef}>
        {flow.steps.map((s, i) => (
          <button key={s.index} className={`step ${i === step ? "on" : i < step ? "done" : ""}`} onClick={() => props.onStep(i)}>
            <div className="step-n">{s.index}</div>
            <div className="step-body">
              <div className="step-hop">
                {s.from.label} <span className="arrow">→</span> {s.to.label}
              </div>
              <div className="step-label">
                <span className="ae-kind">{s.kind}</span> {s.label}
              </div>
              {i <= step && <div className="step-note">{s.note}</div>}
              {i === step && <Cite ev={s.evidence} />}
            </div>
          </button>
        ))}
      </div>
      <AskButton onClick={props.onAsk}>What could go wrong in this flow?</AskButton>
    </div>
  );
}

// ---------------------------------------------------------------- node

export function NodePanel({ graph, nodeId, onClose, onSelect, onBlast, onAsk }: { graph: AtlasGraph; nodeId: string; onClose: () => void; onSelect: (id: string) => void; onBlast: (id: string) => void; onAsk: (t: string) => void }) {
  const node = graph.nodes.find((n) => n.id === nodeId);
  const nodes = useMemo(() => new Map(graph.nodes.map((n) => [n.id, n])), [graph]);
  if (!node) return null;
  const out = graph.edges.filter((e) => e.from === node.id);
  const inc = graph.edges.filter((e) => e.to === node.id);
  return (
    <div className="panel">
      <PanelHead
        title={
          <span className="node-title" data-kind={node.kind}>
            <span className="an-icon sm">
              <KindIcon kind={node.kind} size={15} />
            </span>
            {node.label}
          </span>
        }
        sub={[KIND_LABEL[node.kind], node.tech].filter(Boolean).join(" · ")}
        onClose={onClose}
      />
      <p className="summary">{node.summary}</p>
      {node.details.length > 0 && (
        <ul className="details">
          {node.details.map((d) => (
            <li key={d}>{d}</li>
          ))}
        </ul>
      )}
      {node.files.length > 0 && (
        <div className="files">
          {node.files.slice(0, 8).map((f) => (
            <code key={f.path}>{f.path}</code>
          ))}
        </div>
      )}
      <div className="btn-row">
        <button className="danger-btn" onClick={() => onBlast(node.id)}>
          ⚡ What breaks if this goes down?
        </button>
      </div>
      {out.length > 0 && <h4>Depends on</h4>}
      {out.map((e) => (
        <div key={e.id} className="dep">
          <button className="dep-head link" onClick={() => onSelect(e.to)}>
            → {nodes.get(e.to)?.label} <span className="ae-kind">{e.kind}</span> <span className="dep-label">{e.label}</span>
          </button>
          <Cite ev={e.evidence[0]} />
        </div>
      ))}
      {inc.length > 0 && <h4>Used by</h4>}
      {inc.map((e) => (
        <div key={e.id} className="dep">
          <button className="dep-head link" onClick={() => onSelect(e.from)}>
            ← {nodes.get(e.from)?.label} <span className="ae-kind">{e.kind}</span> <span className="dep-label">{e.label}</span>
          </button>
          <Cite ev={e.evidence[0]} />
        </div>
      ))}
      <AskButton onClick={() => onAsk(`Explain the ${node.label} component in ${graph.repo.name}: what it does and how it fits in.`)}>Ask ChatGPT about {node.label}</AskButton>
    </div>
  );
}

// ---------------------------------------------------------------- blast

export function BlastPanel({ graph, nodeId, onClose, onAsk, onTrace }: { graph: AtlasGraph; nodeId: string; onClose: () => void; onAsk: (t: string) => void; onTrace: (id: string) => void }) {
  const b = useMemo(() => blastRadius(graph, nodeId), [graph, nodeId]);
  if (!b) return null;
  return (
    <div className="panel">
      <PanelHead title={<span className="danger-text">⚡ {b.node.label} is down</span>} sub="Simulated outage" onClose={onClose} />
      <p className="summary">{b.summary}</p>
      {b.brokenFlows.length > 0 && (
        <>
          <h4>Broken flows</h4>
          <div className="list">
            {b.brokenFlows.map((f) => (
              <button key={f.id} className="row danger" onClick={() => onTrace(f.id)}>
                <span className="row-play">✕</span>
                <span className="row-main">
                  <span className="row-title">{f.name}</span>
                  <span className="row-sub">{f.trigger}</span>
                </span>
              </button>
            ))}
          </div>
        </>
      )}
      {b.impacted.length > 0 && <h4>Impacted components</h4>}
      <div className="impacted">
        {b.impacted.map((i) => (
          <div key={i.node.id} className="imp">
            <KindChip kind={i.node.kind} />
            <span className="imp-label">{i.node.label}</span>
            <span className="imp-depth">{i.depth === 1 ? "direct" : `${i.depth} hops`}</span>
          </div>
        ))}
      </div>
      <AskButton onClick={() => onAsk(`If ${b.node.label} goes down in ${graph.repo.name}, how should we make the system degrade gracefully? Be specific to this architecture.`)}>
        How do we make this resilient?
      </AskButton>
    </div>
  );
}

// ---------------------------------------------------------------- drift

export function DriftPanel(props: {
  reports: DriftReport[];
  activeId: string | null;
  onSelect: (id: string) => void;
  onClose: () => void;
  onAsk: (t: string) => void;
  onCheck: () => void;
  reviewing: boolean;
  graph: AtlasGraph;
}) {
  const { reports } = props;
  const active = reports.find((r) => r.id === props.activeId) ?? reports[0];
  const nodes = new Map(props.graph.nodes.map((n) => [n.id, n]));
  const lbl = (id: string) => nodes.get(id)?.label ?? active?.removed.nodes.find((n) => n.id === id)?.label ?? active?.added.nodes.find((n) => n.id === id)?.label ?? id;
  return (
    <div className="panel">
      <PanelHead title="Architecture drift" sub="Every push, reviewed at the architecture level" onClose={props.onClose} />
      {props.reviewing && (
        <div className="reviewing">
          <span className="spinner" /> Reviewing a new push…
        </div>
      )}
      {!active && !props.reviewing && (
        <div className="empty">
          <p>No pushes reviewed yet. Push a commit to this repo and Atlas will review its architecture within seconds.</p>
          <button className="btn" onClick={props.onCheck}>
            Check latest commit now
          </button>
        </div>
      )}
      {active && (
        <div className={`report sev-${active.maxSeverity}`}>
          <div className="report-head">
            <span className={`sev sev-${active.maxSeverity}`}>{active.maxSeverity === "none" ? "no drift" : active.maxSeverity}</span>
            <code>
              {shortSha(active.fromSha)} → {shortSha(active.toSha)}
            </code>
            <span className="muted">{ago(active.at)}</span>
          </div>
          {active.commits[0] && (
            <div className="commit">
              “{active.commits[0].message}”{active.commits[0].author ? <span className="muted"> · {active.commits[0].author}</span> : null}
            </div>
          )}
          <p className="summary">{active.summary}</p>
          {active.findings.map((f) => (
            <div key={f.id} className={`finding sev-${f.severity}`}>
              <div className="finding-title">
                <span className={`sev sev-${f.severity}`}>{f.severity}</span> {f.title}
              </div>
              <div className="finding-detail">{f.detail}</div>
            </div>
          ))}
          {(active.added.edges.length > 0 || active.removed.edges.length > 0) && (
            <div className="delta">
              {active.added.edges.map((e) => (
                <div key={e.id} className="delta-row add">
                  <span>+</span> {lbl(e.from)} → {lbl(e.to)} <span className="ae-kind">{e.kind}</span>
                  <Cite ev={e.evidence[0]} />
                </div>
              ))}
              {active.removed.edges.map((e) => (
                <div key={e.id} className="delta-row rem">
                  <span>−</span> {lbl(e.from)} → {lbl(e.to)} <span className="ae-kind">{e.kind}</span>
                </div>
              ))}
            </div>
          )}
          {active.maxSeverity !== "none" && (
            <AskButton
              onClick={() =>
                props.onAsk(
                  `Atlas flagged architecture drift in ${props.graph.repo.name} commit ${shortSha(active.toSha)}: ${active.findings[0]?.title ?? active.summary}. Suggest the right fix that keeps the intended layering, with code.`,
                )
              }
            >
              Suggest a fix
            </AskButton>
          )}
        </div>
      )}
      {reports.length > 1 && (
        <>
          <h4>Recent pushes</h4>
          <div className="list">
            {reports.slice(0, 12).map((r) => (
              <button key={r.id} className={`row ${r.id === active?.id ? "on" : ""}`} onClick={() => props.onSelect(r.id)}>
                <span className={`dot sev-${r.maxSeverity}`} />
                <span className="row-main">
                  <span className="row-title">{r.commits[0]?.message ?? shortSha(r.toSha)}</span>
                  <span className="row-sub">
                    {shortSha(r.toSha)} · {r.maxSeverity === "none" ? "no drift" : `${r.findings.length} finding${r.findings.length === 1 ? "" : "s"}`}
                  </span>
                </span>
                <span className="row-meta">{ago(r.at)}</span>
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// ---------------------------------------------------------------- progress

const STAGES = [
  { id: "scout", label: "Scout", desc: "plans the work" },
  { id: "reader", label: "Readers", desc: "read modules in parallel" },
  { id: "cartographer", label: "Cartographer", desc: "assembles the map" },
  { id: "verifier", label: "Verifier", desc: "checks every citation" },
];

export function Progress({ job }: { job: JobView | null }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 500);
    return () => clearInterval(t);
  }, []);
  const log = job?.log ?? [];
  const stageState = (id: string) => {
    const msgs = log.filter((l) => (id === "verifier" ? l.message.startsWith("Verifier") : l.agent === id));
    if (msgs.some((m) => m.phase === "error") && !msgs.some((m) => m.phase === "done")) return "err";
    if (id === "reader") {
      const started = msgs.filter((m) => m.phase === "start").length;
      const done = msgs.filter((m) => m.phase === "done" || m.phase === "error").length;
      if (started === 0) return "todo";
      return done >= started && log.some((l) => l.agent === "cartographer") ? "done" : "run";
    }
    if (msgs.some((m) => m.phase === "done")) return "done";
    if (msgs.length) return "run";
    return "todo";
  };
  const readers = log.filter((l) => l.agent === "reader" && l.phase === "start").length;
  const readersDone = log.filter((l) => l.agent === "reader" && (l.phase === "done" || l.phase === "error")).length;
  const elapsed = job ? Math.round((now - Date.parse(job.startedAt)) / 1000) : 0;
  return (
    <div className="progress">
      <div className="progress-head">
        <AtlasLogo size={26} />
        <div>
          <div className="progress-title">Mapping {job?.repoName ?? "repository"}</div>
          <div className="muted">
            {job?.status === "error" ? "Mapping failed" : `${elapsed}s · agents are reading the code`}
          </div>
        </div>
      </div>
      <div className="pipeline">
        {STAGES.map((s, i) => {
          const st = stageState(s.id);
          return (
            <div key={s.id} className={`stage st-${st}`}>
              <div className="stage-dot">{st === "done" ? "✓" : st === "err" ? "!" : i + 1}</div>
              <div className="stage-label">{s.label}</div>
              <div className="stage-desc">{s.id === "reader" && readers ? `${readersDone}/${readers} done` : s.desc}</div>
              {i < STAGES.length - 1 && <div className="stage-line" />}
            </div>
          );
        })}
      </div>
      <div className="log">
        {log.slice(-14).map((l, i) => (
          <div key={`${l.at}-${i}`} className={`log-line ph-${l.phase}`}>
            <span className="log-agent">{l.agent === "pipeline" ? "atlas" : l.agent}</span>
            {l.message}
          </div>
        ))}
        {job?.status === "running" && <div className="log-line cursor">▍</div>}
      </div>
      {job?.error && <div className="err inline">{job.error}</div>}
    </div>
  );
}

// ---------------------------------------------------------------- home

export function Home({ repos, onOpen, onMap, error }: { repos: RepoSummary[]; onOpen: (key: string) => void; onMap: (repo: string) => void; error: string | null }) {
  const [value, setValue] = useState("");
  return (
    <div className="home">
      <div className="hero">
        <AtlasLogo size={34} />
        <h1>Atlas</h1>
        <p>Google Maps for your codebase. Paste a GitHub repo and Atlas's agents map its architecture: every dependency cited from the code.</p>
        <form
          className="map-form"
          onSubmit={(e) => {
            e.preventDefault();
            if (value.trim()) onMap(value.trim());
          }}
        >
          <input value={value} onChange={(e) => setValue(e.target.value)} placeholder="github.com/owner/repo" spellCheck={false} autoFocus />
          <button type="submit" disabled={!value.trim()}>
            Map it
          </button>
        </form>
        {error && <div className="err inline">{error}</div>}
      </div>
      {repos.length > 0 && (
        <div className="repo-list">
          <h4>Mapped repositories</h4>
          {repos.map((r) => (
            <button key={r.key} className="row" onClick={() => onOpen(r.key)}>
              <span className="row-play">
                <AtlasLogo size={14} />
              </span>
              <span className="row-main">
                <span className="row-title">{r.name}</span>
                <span className="row-sub">
                  {r.components} components · {r.dependencies} dependencies{r.sha ? ` · ${shortSha(r.sha)}` : ""}
                </span>
              </span>
              <span className="row-meta">{r.mapping ? "mapping…" : "open"}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

