  background: color-mix(in srgb, var(--kc) 13%, transparent);
}
.an-icon.sm {
  width: 24px;
  height: 24px;
  border-radius: 7px;
}
.an-text {
  min-width: 0;
}
.an-label {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 134px;
}
.an-sub {
  font-size: 11px;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 134px;
}
.an-handle {
  opacity: 0;
  width: 1px !important;
  height: 1px !important;
  min-width: 0 !important;
  border: 0 !important;
}
.an:hover {
  border-color: color-mix(in srgb, var(--kc) 45%, var(--border));
}
.an-dim {
  opacity: 0.32;
}
.an-selected,
.an-active {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft), var(--shadow-lg);
}
.an-active {
  transform: scale(1.04);
}
.an-path {
