/* ---------------------------------------------------------------- edges */
.ae {
  stroke: var(--edge) !important;
  stroke-width: 1.5 !important;
  transition: stroke 0.25s, opacity 0.25s;
}
.ae-dim {
  stroke: var(--edge-dim) !important;
}
.ae-selected,
.ae-visited {
  stroke: var(--accent) !important;
  stroke-width: 2 !important;
}
.ae-active {
  stroke: var(--accent) !important;
  stroke-width: 2.5 !important;
}
.ae-blast {
  stroke: var(--danger) !important;
  stroke-width: 2 !important;
  stroke-dasharray: 6 4;
  animation: dash 0.8s linear infinite;
}
.ae-added {
  stroke: var(--ok) !important;
  stroke-width: 2.5 !important;
}
.ae-flagged {
  stroke: var(--danger) !important;
  stroke-width: 2.8 !important;
  stroke-dasharray: 8 5;
  animation: dash 0.7s linear infinite;
}
.ae-removed {
  stroke: var(--faint) !important;
  stroke-dasharray: 3 5;
  opacity: 0.7;
}
@keyframes dash {
  to {
    stroke-dashoffset: -20;
  }
}
.ae-glow {
  stroke-width: 9;
  opacity: 0.18;
  stroke: var(--accent);
  stroke-linecap: round;
}
.ae-glow-flagged,
.ae-glow-blast {
  stroke: var(--danger);
}
.ae-glow-added {
  stroke: var(--ok);
}
.ae-packet {
  fill: var(--accent);
  stroke: var(--panel);
  stroke-width: 2.5;
  filter: drop-shadow(0 0 6px var(--accent));
}
.ae-dot {
  fill: var(--accent);
  opacity: 0.6;
}
.ae-label {
  position: absolute;
  pointer-events: none;
  font-size: 11px;
  padding: 3px 7px;
  border-radius: 7px;
  background: var(--panel);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  white-space: nowrap;
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  z-index: 20;
}
.ae-label-flagged {
  border-color: var(--danger);
  color: var(--danger);
}
.ae-label-added {
  border-color: var(--ok);
}
.ae-label-removed {
  color: var(--faint);
  text-decoration: line-through;
}
.ae-kind {
  font-family: ui-monospace, Menlo, monospace;
  font-size: 10px;
  text-transform: uppercase;
  color: var(--muted);
  background: var(--code-bg);
  padding: 1px 5px;
  border-radius: 4px;
  margin-right: 3px;
}

/* react-flow chrome */
.react-flow__controls {
  box-shadow: var(--shadow) !important;
  border-radius: 9px;
  overflow: hidden;
}
.react-flow__controls-button {
  background: var(--panel) !important;
  border-bottom: 1px solid var(--border) !important;
  fill: var(--muted) !important;
}

/* ---------------------------------------------------------------- canvas overlays */
.toast {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  max-width: min(560px, 90%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px 10px 14px;
  border-radius: 11px;
  background: var(--panel);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  z-index: 30;
  animation: drop 0.35s ease-out;
}
.toast.sev-critical {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--danger) 18%, transparent), var(--shadow-lg);
}
.toast.sev-critical strong {
  color: var(--danger);
}
.toast.sev-warning strong {
  color: var(--warn);
}
.toast button {
  margin-left: auto;
  padding: 5px 11px;
  border-radius: 7px;
  background: var(--text);
  color: var(--panel);
  font-weight: 600;
  flex-shrink: 0;
}
@keyframes drop {
  from {
    transform: translate(-50%, -12px);
    opacity: 0;
  }
}
.mode-pill {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 6px 5px 11px;
  border-radius: 999px;
  background: var(--panel);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  font-weight: 500;
  z-index: 25;
}
.mode-pill button {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 10px;
  color: var(--muted);
  background: var(--panel-2);
}
.legend {
  position: absolute;
  bottom: 12px;
  right: 12px;
  display: flex;
  gap: 12px;
  font-size: 11px;
  color: var(--muted);
  background: color-mix(in srgb, var(--panel) 85%, transparent);
  padding: 4px 9px;
  border-radius: 8px;
  border: 1px solid var(--border);
}
.lg {
  display: inline-block;
  vertical-align: middle;
  margin-right: 3px;
}
.lg-arrow {
  width: 16px;
  height: 0;
  border-top: 1.5px solid var(--edge);
}
.lg-packet {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
}

/* ---------------------------------------------------------------- panel */
.panel {
  padding: 14px 16px 22px;
}
.ph {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}
.ph-title {
  font-weight: 650;
  font-size: 15px;
  letter-spacing: -0.01em;
}
.ph-sub {
  color: var(--muted);
  font-size: 12px;
  margin-top: 2px;
}
.summary {
  line-height: 1.5;
  margin: 8px 0 10px;
}
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
.chip {
  font-size: 11.5px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--muted);
}
.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 14px 0 10px;
}
.stats div {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 9px 10px;
  display: flex;
  flex-direction: column;
}
.stats b {
  font-size: 19px;
  letter-spacing: -0.02em;
}
.stats span {
  font-size: 11px;
  color: var(--muted);
}
.trust {
  border: 1px solid color-mix(in srgb, var(--ok) 35%, var(--border));
  background: var(--ok-soft);
  border-radius: 10px;
  padding: 9px 11px;
}
.trust-title {
  font-weight: 600;
  color: var(--ok);
  margin-bottom: 3px;
}
.trust-body {
  font-size: 12px;
  line-height: 1.45;
  color: var(--text);
  opacity: 0.85;
}
.list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 9px;
  border: 1px solid var(--border);
  background: var(--panel);
  width: 100%;
}
.row:hover,
.row.on {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  background: var(--accent-soft);
}
.row.danger:hover {
  border-color: var(--danger);
  background: var(--danger-soft);
}
.row-play {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  display: grid;
  place-items: center;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 10px;
  flex-shrink: 0;
}
.row.danger .row-play {
  background: var(--danger-soft);
  color: var(--danger);
}
.row-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}
.row-title {
  font-weight: 550;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.row-sub {
  font-size: 11.5px;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.row.tall .row-sub {
  white-space: normal;
}
.row-meta {
  font-size: 11px;
  color: var(--faint);
  white-space: nowrap;
}
.kind-group {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 7px;
}
.kind-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  padding: 2px 7px 2px 5px;
  border-radius: 6px;
  white-space: nowrap;
  --kc: var(--k-service);
  color: var(--kc);
  background: color-mix(in srgb, var(--kc) 12%, transparent);
  flex-shrink: 0;
  min-width: 92px;
}
.kind-chip[data-kind="client"] { --kc: var(--k-client); }
.kind-chip[data-kind="frontend"] { --kc: var(--k-frontend); }
.kind-chip[data-kind="api"] { --kc: var(--k-api); }
.kind-chip[data-kind="worker"] { --kc: var(--k-worker); }
.kind-chip[data-kind="database"] { --kc: var(--k-database); }
.kind-chip[data-kind="cache"] { --kc: var(--k-cache); }
.kind-chip[data-kind="queue"] { --kc: var(--k-queue); }
.kind-chip[data-kind="storage"] { --kc: var(--k-storage); }
.kind-chip[data-kind="external"] { --kc: var(--k-external); }
.kind-items {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 10px;
  padding-top: 2px;
}
.link {
  color: var(--accent);
}
.link:hover {
  text-decoration: underline;
}
.ask {
  margin-top: 18px;
  width: 100%;
  padding: 9px 12px;
  border-radius: 10px;
  border: 1px dashed color-mix(in srgb, var(--accent) 45%, var(--border));
  color: var(--accent);
  font-weight: 550;
}
.ask:hover {
  background: var(--accent-soft);
}
.ask-spark {
  margin-right: 4px;
}
.btn,
.play {
  padding: 7px 12px;
  border-radius: 9px;
  background: var(--text);
  color: var(--panel);
  font-weight: 600;
}
.btn-row {
  margin: 12px 0 4px;
}
.danger-btn {
  width: 100%;
  padding: 8px 11px;
  border-radius: 9px;
  border: 1px solid color-mix(in srgb, var(--danger) 40%, var(--border));
  color: var(--danger);
  font-weight: 550;
}
.danger-btn:hover {
  background: var(--danger-soft);
}
.danger-text {
  color: var(--danger);
}

/* citations */
.cite {
  margin-top: 6px;
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  background: var(--code-bg);
}
.cite-path {
  font-family: ui-monospace, Menlo, monospace;
  font-size: 10.5px;
  color: var(--muted);
  padding: 4px 8px;
  border-bottom: 1px solid var(--border);
  background: var(--panel-2);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cite-code {
  display: block;
  padding: 6px 8px;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--text);
}

/* trace */
.player {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 10px 0 12px;
}
.player-pos {
  margin-left: auto;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.steps {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.step {
  display: flex;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid transparent;
  width: 100%;
  opacity: 0.55;
}
.step.done {
  opacity: 0.85;
}
.step.on {
  opacity: 1;
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  background: var(--accent-soft);
}
.step-n {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 700;
  background: var(--panel-2);
  border: 1px solid var(--border);
  flex-shrink: 0;
}
.step.on .step-n,
.step.done .step-n {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.step-body {
  min-width: 0;
  flex: 1;
}
.step-hop {
  font-weight: 600;
}
.arrow {
  color: var(--accent);
}
.step-label {
  font-size: 12px;
  color: var(--muted);
  margin-top: 2px;
}
.step-note {
  margin-top: 4px;
  line-height: 1.45;
}

/* node panel */
.node-title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  --kc: var(--k-service);
}
.node-title[data-kind="client"] { --kc: var(--k-client); }
.node-title[data-kind="frontend"] { --kc: var(--k-frontend); }
.node-title[data-kind="api"] { --kc: var(--k-api); }
.node-title[data-kind="worker"] { --kc: var(--k-worker); }
.node-title[data-kind="database"] { --kc: var(--k-database); }
.node-title[data-kind="cache"] { --kc: var(--k-cache); }
.node-title[data-kind="queue"] { --kc: var(--k-queue); }
.node-title[data-kind="storage"] { --kc: var(--k-storage); }
.node-title[data-kind="external"] { --kc: var(--k-external); }
.details {
  margin: 6px 0;
  padding-left: 18px;
  line-height: 1.6;
}
.files {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 8px 0;
}
.files code {
  background: var(--code-bg);
  padding: 2px 6px;
  border-radius: 5px;
  color: var(--muted);
}
.dep {
  margin-bottom: 10px;
}
.dep-head {
  font-weight: 550;
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  color: var(--text);
}
.dep-label {
  color: var(--muted);
  font-weight: 400;
}

/* blast */
.impacted {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.imp {
  display: flex;
  align-items: center;
  gap: 8px;
}
.imp-label {
  font-weight: 550;
  flex: 1;
}
.imp-depth {
  font-size: 11px;
  color: var(--danger);
}

/* drift */
.reviewing {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 9px;
  background: var(--warn-soft);
  color: var(--warn);
  margin: 8px 0;
  font-weight: 550;
}
.spinner {
  width: 13px;
  height: 13px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.empty {
  color: var(--muted);
  line-height: 1.5;
}
.report {
  margin-top: 10px;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px;
}
.report.sev-critical {
  border-color: color-mix(in srgb, var(--danger) 50%, var(--border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--danger) 10%, transparent);
}
.report-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.report-head code {
  color: var(--muted);
}
.commit {
  margin-top: 8px;
  font-weight: 550;
}
.sev {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 6px;
  background: var(--code-bg);
  color: var(--muted);
}
.sev.sev-critical {
  background: var(--danger);
  color: #fff;
}
.sev.sev-warning {
  background: var(--warn-soft);
  color: var(--warn);
}
.sev.sev-info {
  background: var(--accent-soft);
  color: var(--accent);
}
.sev.sev-none {
  background: var(--ok-soft);
  color: var(--ok);
}
.finding {
  margin-top: 8px;
  padding: 9px 10px;
  border-radius: 9px;
  background: var(--panel-2);
  border-left: 3px solid var(--faint);
}
.finding.sev-critical {
  border-left-color: var(--danger);
  background: var(--danger-soft);
}
.finding.sev-warning {
  border-left-color: var(--warn);
}
.finding.sev-info {
  border-left-color: var(--accent);
}
.finding-title {
  font-weight: 600;
  display: flex;
  gap: 6px;
  align-items: baseline;
}
.finding-detail {
  margin-top: 4px;
  line-height: 1.45;
  font-size: 12.5px;
}
.delta {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.delta-row {
  font-size: 12.5px;
}
.delta-row.add > span:first-child {
  color: var(--ok);
  font-weight: 700;
}
.delta-row.rem {
  color: var(--muted);
}
.delta-row.rem > span:first-child {
  color: var(--danger);
  font-weight: 700;
}
.dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--faint);
  flex-shrink: 0;
}
.dot.sev-critical {
  background: var(--danger);
}
.dot.sev-warning {
  background: var(--warn);
}
.dot.sev-info {
  background: var(--accent);
}
.dot.sev-none {
  background: var(--ok);
}

/* ---------------------------------------------------------------- progress */
.progress {
  padding: 26px 26px;
  max-width: 760px;
  margin: 0 auto;
  width: 100%;
  overflow-y: auto;
}
.progress-head {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
}
.progress-title {
  font-size: 17px;
  font-weight: 650;
}
.pipeline {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 18px;
}
.stage {
  position: relative;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: var(--panel);
}
.stage-dot {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 700;
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--muted);
  margin-bottom: 8px;
}
.stage-label {
  font-weight: 600;
}
.stage-desc {
  font-size: 11.5px;
  color: var(--muted);
}
.st-run {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.st-run .stage-dot {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
  animation: pulse-acc 1.4s infinite;
}
@keyframes pulse-acc {
  50% {
    box-shadow: 0 0 0 5px var(--accent-soft);
  }
}
.st-done .stage-dot {
  background: var(--ok);
  border-color: var(--ok);
  color: #fff;
}
.st-err .stage-dot {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.log {
  font-family: ui-monospace, Menlo, monospace;
  font-size: 11.5px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px 14px;
  line-height: 1.75;
  min-height: 180px;
}
.log-line {
  white-space: pre-wrap;
  animation: fadein 0.3s;
}
.log-line.ph-error {
  color: var(--danger);
}
.log-line.ph-done {
  color: var(--text);
}
.log-line.ph-start,
.log-line.ph-progress {
  color: var(--muted);
}
.log-agent {
  display: inline-block;
  min-width: 96px;
  color: var(--accent);
}
.cursor {
  animation: blink 1s steps(1) infinite;
  color: var(--accent);
}
@keyframes blink {
  50% {
    opacity: 0;
  }
}
@keyframes fadein {
  from {
    opacity: 0;
    transform: translateY(2px);
  }
}

/* ---------------------------------------------------------------- home */
.home {
  padding: 34px 26px;
  max-width: 640px;
  margin: 0 auto;
  width: 100%;
  overflow-y: auto;
}
.hero h1 {
  margin: 8px 0 4px;
  font-size: 26px;
  letter-spacing: -0.02em;
}
.hero p {
  color: var(--muted);
  line-height: 1.55;
  margin: 0 0 16px;
}
.map-form {
  display: flex;
  gap: 8px;
}
.map-form input {
  flex: 1;
  font: inherit;
  font-size: 14px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--panel);
  color: var(--text);
  outline: none;
}
.map-form input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.map-form button {
  padding: 0 16px;
  border-radius: 10px;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
}
.map-form button:disabled {
  opacity: 0.5;
}
.repo-list {
  margin-top: 26px;
}
.err {
  margin: 8px 14px;
  padding: 8px 11px;
  border-radius: 9px;
  background: var(--danger-soft);
  color: var(--danger);
}
.err.inline {
  margin: 12px 0 0;
}

