import type { NextFunction, Request, Response } from "express";
import jwt from "jsonwebtoken";
import { redis } from "../redis.js";

export interface AuthedRequest extends Request {
  customerId?: number;
}

/** Bearer JWT, and the session must still exist in Redis (logout revokes it). */
export async function requireAuth(req: AuthedRequest, res: Response, next: NextFunction) {
  const token = req.header("authorization")?.replace(/^Bearer /, "");
  if (!token) return res.status(401).json({ error: "login required" });
  try {
    const { sub, sid } = jwt.verify(token, process.env.JWT_SECRET!) as { sub: string; sid: string };
    const alive = await redis.exists(`session:${sid}`);
    if (!alive) return res.status(401).json({ error: "session expired" });
    req.customerId = Number(sub);
    next();
  } catch {
    res.status(401).json({ error: "invalid token" });
  }
}
