  const res = await fetch(`${MSG91_URL}?template_id=${process.env.MSG91_TEMPLATE_ID}&mobile=91${phone}&otp=${otp}`, {
    method: "POST",
    headers: { authkey: process.env.MSG91_AUTH_KEY! },
  });
