import type { PoolClient } from "pg";

export interface LineItem {
  productId: number;
  quantity: number;
}

/** Reserve stock inside the caller's transaction; throws if anything is out of stock. */
export async function reserveStock(tx: PoolClient, items: LineItem[]): Promise<void> {
  for (const item of items) {
    const { rowCount } = await tx.query(
      `update inventory set reserved = reserved + $2
        where product_id = $1 and stock - reserved >= $2`,
      [item.productId, item.quantity],
    );
    if (rowCount === 0) throw new Error(`Out of stock: product ${item.productId}`);
  }
}

export async function commitStock(tx: PoolClient, orderId: number): Promise<void> {
  await tx.query(
    `update inventory i set stock = stock - oi.quantity, reserved = reserved - oi.quantity
       from order_items oi
      where oi.order_id = $1 and i.product_id = oi.product_id`,
    [orderId],
  );
}
EOF
