import { db } from "../db.js";
import { razorpay } from "../lib/razorpay.js";
import { publish } from "../queue.js";
import { redis } from "../redis.js";
import { reserveStock } from "./inventory.js";

export interface Address {
  name: string;
  line1: string;
  city: string;
  pincode: string;
  phone: string;
}

/**
 * Turn the customer's cart into a pending order: reserve stock, price it,
 * open a Razorpay order the browser will pay against, and announce it.
 */
export async function createOrder(customerId: number, address: Address) {
  const cart = await redis.hgetall(`cart:${customerId}`);
  const items = Object.entries(cart).map(([productId, qty]) => ({ productId: Number(productId), quantity: Number(qty) }));
  if (items.length === 0) throw new Error("Cart is empty");

  const tx = await db.connect();
  try {
    await tx.query("begin");
    await reserveStock(tx, items);

    const { rows: prices } = await tx.query("select id, price_paise from products where id = any($1)", [items.map((i) => i.productId)]);
    const priceOf = new Map(prices.map((p) => [Number(p.id), Number(p.price_paise)]));
    const total = items.reduce((sum, i) => sum + priceOf.get(i.productId)! * i.quantity, 0);

    const { rows } = await tx.query(
      "insert into orders (customer_id, total_paise, address) values ($1, $2, $3) returning id",
      [customerId, total, address],
    );
    const orderId = Number(rows[0].id);
    for (const i of items) {
      await tx.query("insert into order_items (order_id, product_id, quantity, price_paise) values ($1, $2, $3, $4)", [
        orderId,
        i.productId,
        i.quantity,
        priceOf.get(i.productId),
      ]);
    }

    const rzpOrder = await razorpay.orders.create({ amount: total, currency: "INR", receipt: `order_${orderId}` });
    await tx.query("update orders set razorpay_order_id = $1 where id = $2", [rzpOrder.id, orderId]);
    await tx.query("commit");

    await redis.del(`cart:${customerId}`);
    await publish({ type: "order.created", orderId });
    return { orderId, razorpayOrderId: rzpOrder.id, amount: total };
  } catch (err) {
    await tx.query("rollback");
    throw err;
  } finally {
    tx.release();
  }
}

export async function getOrder(orderId: number, customerId: number) {
  const { rows } = await db.query("select id, status, total_paise, shipment_id, created_at from orders where id = $1 and customer_id = $2", [
    orderId,
    customerId,
  ]);
  return rows[0];
}
EOF
