import { db } from "../db.js";
import { publish } from "../queue.js";
import { commitStock } from "./inventory.js";

/** Idempotently mark an order paid when Razorpay confirms the payment. */
export async function markOrderPaid(razorpayOrderId: string, paymentId: string): Promise<void> {
  const tx = await db.connect();
  try {
    await tx.query("begin");
    const { rows } = await tx.query(
      `update orders set status = 'paid', razorpay_payment_id = $2
        where razorpay_order_id = $1 and status = 'pending'
      returning id`,
      [razorpayOrderId, paymentId],
    );
    if (rows[0]) await commitStock(tx, Number(rows[0].id));
    await tx.query("commit");
    if (rows[0]) await publish({ type: "order.paid", orderId: Number(rows[0].id) });
  } catch (err) {
    await tx.query("rollback");
    throw err;
  } finally {
    tx.release();
  }
}
