const SHIPROCKET = "https://apiv2.shiprocket.in/v1/external";

async function shiprocketToken(): Promise<string> {
  const res = await fetch(`${SHIPROCKET}/auth/login`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email: process.env.SHIPROCKET_EMAIL, password: process.env.SHIPROCKET_PASSWORD }),
  });
  return (await res.json()).token;
}

/** Book a courier pickup for a paid order and remember the shipment id. */
export async function createShipment(orderId: number): Promise<void> {
  const { rows } = await db.query("select id, address, total_paise from orders where id = $1 and shipment_id is null", [orderId]);
  const order = rows[0];
  if (!order) return;

  const res = await fetch(`${SHIPROCKET}/orders/create/adhoc`, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${await shiprocketToken()}` },
    body: JSON.stringify({
      order_id: String(order.id),
      billing_customer_name: order.address.name,
      billing_address: order.address.line1,
      billing_city: order.address.city,
      billing_pincode: order.address.pincode,
      billing_phone: order.address.phone,
      sub_total: order.total_paise / 100,
      payment_method: "Prepaid",
    }),
  });
  const shipment = await res.json();
  await db.query("update orders set shipment_id = $1, status = 'shipped' where id = $2", [String(shipment.shipment_id), orderId]);
}
