// Typed client for the chai-commerce API. The storefront never touches the
// database or Redis directly; everything goes through here.
const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";

export interface Product {
  id: number;
  slug: string;
  name: string;
  price_paise: number;
  image_url: string;
  available: number;
}

function token(): string | null {
  return typeof window === "undefined" ? null : localStorage.getItem("chai_token");
}

async function call<T>(path: string, init: RequestInit = {}): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, {
    ...init,
    headers: { "content-type": "application/json", ...(token() ? { authorization: `Bearer ${token()}` } : {}), ...init.headers },
    cache: "no-store",
  });
  if (!res.ok) throw new Error(`${path} → ${res.status}`);
  return res.status === 204 ? (undefined as T) : res.json();
}

export const api = {
  products: () => call<Product[]>("/api/products"),
  product: (slug: string) => call<Product & { description: string }>(`/api/products/${slug}`),
  cart: () => call<Array<{ productId: number; quantity: number }>>("/api/cart"),
  addToCart: (productId: number, quantity = 1) => call<void>("/api/cart", { method: "POST", body: JSON.stringify({ productId, quantity }) }),
  removeFromCart: (productId: number) => call<void>(`/api/cart/${productId}`, { method: "DELETE" }),
  placeOrder: (address: Record<string, string>) =>
    call<{ orderId: number; razorpayOrderId: string; amount: number }>("/api/orders", { method: "POST", body: JSON.stringify({ address }) }),
  order: (id: number) => call<{ id: number; status: string; total_paise: number; shipment_id: string | null }>(`/api/orders/${id}`),
  requestOtp: (phone: string) => call<void>("/api/auth/otp", { method: "POST", body: JSON.stringify({ phone }) }),
  verifyOtp: (phone: string, otp: string) => call<{ token: string }>("/api/auth/verify", { method: "POST", body: JSON.stringify({ phone, otp }) }),
};

export const rupees = (paise: number) => `₹${(paise / 100).toLocaleString("en-IN")}`;
