cat > lib/razorpay.ts <<'EOF'
// Razorpay Checkout runs in the browser with the PUBLIC key only. The order is
// created server-side; payment confirmation arrives via the API's webhook.
declare global {
  interface Window {
    Razorpay: new (options: Record<string, unknown>) => { open(): void };
  }
}

function loadCheckout(): Promise<void> {
  return new Promise((resolve, reject) => {
    if (window.Razorpay) return resolve();
    const script = document.createElement("script");
    script.src = "https://checkout.razorpay.com/v1/checkout.js";
    script.onload = () => resolve();
    script.onerror = reject;
    document.body.appendChild(script);
  });
}

export async function payWithRazorpay(opts: { razorpayOrderId: string; amount: number; onPaid: () => void }) {
  await loadCheckout();
  new window.Razorpay({
    key: process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID,
    order_id: opts.razorpayOrderId,
    amount: opts.amount,
    currency: "INR",
    name: "chai-commerce",
    handler: opts.onPaid,
  }).open();
}
