import { useState } from "react";
import { api } from "../../lib/api";
import { payWithRazorpay } from "../../lib/razorpay";

export default function CheckoutPage() {
  const [address, setAddress] = useState({ name: "", line1: "", city: "", pincode: "", phone: "" });
  const [busy, setBusy] = useState(false);

  async function placeOrder() {
    setBusy(true);
    try {
      const order = await api.placeOrder(address);
      await payWithRazorpay({
        razorpayOrderId: order.razorpayOrderId,
        amount: order.amount,
        onPaid: () => (window.location.href = `/orders/${order.orderId}`),
      });
    } finally {
      setBusy(false);
    }
  }

  return (
    <section>
      <h1>Checkout</h1>
      {(Object.keys(address) as Array<keyof typeof address>).map((field) => (
        <input key={field} placeholder={field} value={address[field]} onChange={(e) => setAddress({ ...address, [field]: e.target.value })} />
      ))}
      <button disabled={busy} onClick={placeOrder}>
        Pay with UPI / card
      </button>
    </section>
  );
}
