"use client";
import { use, useEffect, useState } from "react";
import { api, rupees } from "../../../lib/api";

export default function OrderPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const [order, setOrder] = useState<Awaited<ReturnType<typeof api.order>> | null>(null);

  // The webhook marks the order paid a moment after checkout; poll until it does.
  useEffect(() => {
    const load = () => api.order(Number(id)).then(setOrder);
    load();
    const t = setInterval(load, 3000);
    return () => clearInterval(t);
  }, [id]);

  if (!order) return <p>Loading…</p>;
  return (
    <section>
      <h1>Order #{order.id}</h1>
      <p>Status: {order.status}</p>
      <p>Total: {rupees(order.total_paise)}</p>
      {order.shipment_id && <p>Shipment: {order.shipment_id}</p>}
    </section>
  );
}
