@import "tailwindcss";

/* Dark mode follows the host (ChatGPT) or the toggle via data-theme on <html>. */
@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

/* ------------------------------------------------------------------ tokens */
:root {
  --bg: #fafaf9;
  --canvas: #f6f6f4;
  --surface: #ffffff;
  --surface-2: #f4f4f3;
  --surface-3: #ececea;
  --line: #e7e6e3;
  --line-strong: #d6d5d1;
  --text: #111110;
  --muted: #6f6e69;
  --faint: #a3a29d;
  --grid: #dcdbd6;
  --edge: #c4c3be;
  --edge-dim: #e6e5e1;
  --accent: #5b4cf0;
  --accent-2: #2f6bff;
  --accent-soft: #eeecff;
  --code-bg: #fbfbfa;
  --danger: #e5484d;
  --warn: #e38b10;
  --ok: #30a46c;
  --info: #3e63dd;
  --shadow-card: 0 1px 2px rgb(16 16 15 / 0.04), 0 2px 8px -2px rgb(16 16 15 / 0.06);
  --shadow-pop: 0 12px 32px -8px rgb(16 16 15 / 0.18), 0 2px 6px rgb(16 16 15 / 0.06);
  color-scheme: light;
}

:root[data-theme="dark"] {
  --bg: #0b0b0d;
  --canvas: #0e0e11;
  --surface: #141417;
  --surface-2: #1a1a1e;
  --surface-3: #222227;
  --line: #26262c;
  --line-strong: #34343b;
  --text: #ededef;
  --muted: #a0a0a8;
  --faint: #63636c;
  --grid: #222228;
  --edge: #45454e;
  --edge-dim: #232329;
  --accent: #8b7dff;
  --accent-2: #5b8cff;
  --accent-soft: #221f3d;
  --code-bg: #111114;
  --danger: #ff6369;
  --warn: #ffb224;
  --ok: #4cc38a;
  --info: #849dff;
  --shadow-card: 0 1px 2px rgb(0 0 0 / 0.5);
  --shadow-pop: 0 16px 40px -8px rgb(0 0 0 / 0.7);
  color-scheme: dark;
}

@theme inline {
  --font-sans: ui-sans-serif, -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Inter, Roboto, sans-serif;
  --font-mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
  --color-bg: var(--bg);
  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-text: var(--text);
  --color-muted: var(--muted);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-2: var(--accent-2);
  --color-accent-soft: var(--accent-soft);
  --color-code: var(--code-bg);
  --color-danger: var(--danger);
  --color-warn: var(--warn);
  --color-ok: var(--ok);
  --color-info: var(--info);
  --shadow-card: var(--shadow-card);
  --shadow-pop: var(--shadow-pop);
}

/* ------------------------------------------------------------------ base */
html,
body,
#root {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 13px;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
:root[data-display="inline"] body,
:root[data-display="inline"] #root {
  height: auto;
}
* {
  scrollbar-width: thin;
  scrollbar-color: var(--line-strong) transparent;
}
button {
  cursor: pointer;
}
button:disabled {
  cursor: default;
}

/* ------------------------------------------------------------------ react flow */
.react-flow__attribution {
  display: none;
}
.react-flow__controls {
  box-shadow: var(--shadow-card) !important;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}
.react-flow__controls-button {
  background: var(--surface) !important;
  border-bottom: 1px solid var(--line) !important;
  fill: var(--muted) !important;
  width: 28px !important;
  height: 28px !important;
}
.react-flow__controls-button:hover {
  background: var(--surface-2) !important;
}
.react-flow__handle {
  opacity: 0;
  width: 1px !important;
  height: 1px !important;
  min-width: 0 !important;
  border: 0 !important;
}

/* edges */
.cg-edge {
  fill: none;
  stroke: var(--edge);
  stroke-width: 1.25;
  transition: stroke 0.3s, stroke-width 0.3s, opacity 0.3s;
}
.cg-edge.dim {
  stroke: var(--edge-dim);
}
.cg-edge.selected,
.cg-edge.visited {
  stroke: var(--accent);
  stroke-width: 1.75;
  opacity: 0.75;
}
.cg-edge.active {
  stroke: url(#cg-gradient);
  stroke-width: 2.5;
  stroke-dasharray: 7 6;
  animation: cg-flow 0.6s linear infinite;
}
.cg-edge.blast,
.cg-edge.flagged {
  stroke: var(--danger);
  stroke-width: 2;
  stroke-dasharray: 6 5;
  animation: cg-flow 0.7s linear infinite;
}
.cg-edge.added {
  stroke: var(--ok);
  stroke-width: 2.25;
}
.cg-edge.removed {
  stroke: var(--faint);
  stroke-dasharray: 3 5;
  opacity: 0.8;
}
.cg-edge-glow {
  fill: none;
  stroke-width: 10;
  stroke-linecap: round;
  opacity: 0.16;
  stroke: var(--accent);
  filter: blur(3px);
}
.cg-edge-glow.blast,
.cg-edge-glow.flagged {
  stroke: var(--danger);
}
.cg-edge-glow.added {
  stroke: var(--ok);
}
.cg-packet {
  fill: #fff;
  stroke: var(--accent);
  stroke-width: 3;
  filter: drop-shadow(0 0 6px var(--accent));
}

@keyframes cg-flow {
  to {
    stroke-dashoffset: -26;
  }
}
@keyframes cg-ring {
  0%,
  100% {
    box-shadow: 0 0 0 4px rgb(229 72 77 / 0.18), var(--shadow-card);
  }
  50% {
    box-shadow: 0 0 0 9px rgb(229 72 77 / 0.06), var(--shadow-card);
  }
}
.cg-ring-pulse {
  animation: cg-ring 1.8s ease-in-out infinite;
}
@keyframes cg-live {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--ok) 55%, transparent);
  }
  70% {
    box-shadow: 0 0 0 6px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}
.cg-live-dot {
  animation: cg-live 2s infinite;
}
@keyframes cg-caret {
  50% {
    opacity: 0;
  }
}
.cg-caret {
  animation: cg-caret 1s steps(1) infinite;
}

// Visual identity of each component kind: label, icon and colour tokens.
import {
  Boxes,
  Braces,
  Cog,
  Database,
  Globe,
  HardDrive,
  Layers,
  type LucideIcon,
  MonitorSmartphone,
  PanelsTopLeft,
  Zap,
} from "lucide-react";
import type { NodeKind } from "../../shared/graph";

export interface KindMeta {
  label: string;
  Icon: LucideIcon;
  /** Icon tile: tinted background + coloured glyph. */
  tile: string;
  /** Small solid dot / swatch. */
  dot: string;
  /** Text colour for chips. */
  text: string;
}

export const KINDS: Record<NodeKind, KindMeta> = {
  client: { label: "Client", Icon: MonitorSmartphone, tile: "bg-slate-500/10 text-slate-600 dark:text-slate-300", dot: "bg-slate-400", text: "text-slate-600 dark:text-slate-300" },
  frontend: { label: "Frontend", Icon: PanelsTopLeft, tile: "bg-blue-500/10 text-blue-600 dark:text-blue-400", dot: "bg-blue-500", text: "text-blue-600 dark:text-blue-400" },
  api: { label: "API", Icon: Braces, tile: "bg-violet-500/10 text-violet-600 dark:text-violet-400", dot: "bg-violet-500", text: "text-violet-600 dark:text-violet-400" },
  service: { label: "Service", Icon: Boxes, tile: "bg-indigo-500/10 text-indigo-600 dark:text-indigo-400", dot: "bg-indigo-500", text: "text-indigo-600 dark:text-indigo-400" },
  worker: { label: "Worker", Icon: Cog, tile: "bg-amber-500/12 text-amber-600 dark:text-amber-400", dot: "bg-amber-500", text: "text-amber-700 dark:text-amber-400" },
  database: { label: "Database", Icon: Database, tile: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400", dot: "bg-emerald-500", text: "text-emerald-700 dark:text-emerald-400" },
  cache: { label: "Cache", Icon: Zap, tile: "bg-rose-500/10 text-rose-600 dark:text-rose-400", dot: "bg-rose-500", text: "text-rose-600 dark:text-rose-400" },
  queue: { label: "Queue", Icon: Layers, tile: "bg-fuchsia-500/10 text-fuchsia-600 dark:text-fuchsia-400", dot: "bg-fuchsia-500", text: "text-fuchsia-600 dark:text-fuchsia-400" },
  storage: { label: "Storage", Icon: HardDrive, tile: "bg-cyan-500/10 text-cyan-600 dark:text-cyan-400", dot: "bg-cyan-500", text: "text-cyan-700 dark:text-cyan-400" },
  external: { label: "Third party", Icon: Globe, tile: "bg-zinc-500/10 text-zinc-600 dark:text-zinc-300", dot: "bg-zinc-400", text: "text-zinc-600 dark:text-zinc-300" },
};

export function kindMeta(kind: NodeKind): KindMeta {
  return KINDS[kind] ?? KINDS.service;
}

// Small UI primitives shared by every view.
import { clsx } from "clsx";
import { CircleCheck, FileCode2, Info, LoaderCircle, OctagonAlert, Sparkles, TriangleAlert } from "lucide-react";
import type { ButtonHTMLAttributes, ReactNode } from "react";
import type { Evidence, NodeKind } from "../../shared/graph";
import { kindMeta } from "./kinds";

export const cn = clsx;

type Variant = "primary" | "secondary" | "ghost" | "danger";

export function Button({ variant = "secondary", size = "md", className, children, ...rest }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: Variant; size?: "sm" | "md" }) {
  return (
    <button
      {...rest}
      className={cn(
        "inline-flex items-center justify-center gap-1.5 rounded-lg font-medium transition-all duration-150 select-none active:scale-[0.98] disabled:opacity-50 disabled:active:scale-100",
        size === "sm" ? "h-7 px-2.5 text-[12px]" : "h-9 px-3.5 text-[13px]",
        variant === "primary" && "bg-gradient-to-b from-[#6a5cff] to-[#4e3fe6] text-white shadow-[0_1px_2px_rgb(0_0_0/0.15),inset_0_1px_0_rgb(255_255_255/0.18)] hover:brightness-110",
        variant === "secondary" && "border border-line bg-surface text-text shadow-card hover:bg-surface-2",
        variant === "ghost" && "text-muted hover:bg-surface-2 hover:text-text",
        variant === "danger" && "border border-danger/30 bg-danger/[0.06] text-danger hover:bg-danger/[0.1]",
        className,
      )}
    >
      {children}
    </button>
  );
}

export function IconButton({ className, children, label, ...rest }: ButtonHTMLAttributes<HTMLButtonElement> & { label: string }) {
  return (
    <button
      {...rest}
      aria-label={label}
      title={label}
      className={cn("grid size-8 place-items-center rounded-lg text-muted transition-colors hover:bg-surface-2 hover:text-text disabled:opacity-35", className)}
    >
      {children}
    </button>
  );
}

export function Eyebrow({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn("mb-2 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-faint", className)}>{children}</div>;
}

export function Card({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn("rounded-xl border border-line bg-surface shadow-card", className)}>{children}</div>;
}

export function Chip({ children, className }: { children: ReactNode; className?: string }) {
  return <span className={cn("inline-flex items-center gap-1 rounded-full border border-line bg-surface px-2 py-0.5 text-[11.5px] text-muted", className)}>{children}</span>;
}

/** Monospace tag for edge kinds (HTTP, SQL, CACHE …). */
export function KindTag({ children }: { children: ReactNode }) {
  return <span className="rounded-[5px] bg-surface-3 px-1.5 py-[1px] font-mono text-[9.5px] font-semibold uppercase tracking-wide text-muted">{children}</span>;
}

export function KindTile({ kind, size = "md" }: { kind: NodeKind; size?: "sm" | "md" | "lg" }) {
  const k = kindMeta(kind);
  const px = size === "sm" ? "size-6 rounded-md" : size === "lg" ? "size-10 rounded-xl" : "size-8 rounded-lg";
  const icon = size === "sm" ? 13 : size === "lg" ? 20 : 16;
  return (
    <span className={cn("grid shrink-0 place-items-center", px, k.tile)}>
      <k.Icon size={icon} strokeWidth={1.8} />
    </span>
  );
}

export function KindChip({ kind }: { kind: NodeKind }) {
  const k = kindMeta(kind);
  return (
    <span className={cn("inline-flex items-center gap-1.5 text-[11.5px] font-medium", k.text)}>
      <span className={cn("size-1.5 rounded-full", k.dot)} />
      {k.label}
    </span>
  );
}

export type SeverityLevel = "critical" | "warning" | "info" | "none";

const SEV: Record<SeverityLevel, { label: string; cls: string; Icon: typeof Info }> = {
  critical: { label: "Critical", cls: "bg-danger/10 text-danger ring-danger/25", Icon: OctagonAlert },
  warning: { label: "Warning", cls: "bg-warn/12 text-warn ring-warn/25", Icon: TriangleAlert },
  info: { label: "Info", cls: "bg-info/10 text-info ring-info/25", Icon: Info },
  none: { label: "No drift", cls: "bg-ok/10 text-ok ring-ok/25", Icon: CircleCheck },
};

export function SeverityBadge({ level, className }: { level: SeverityLevel; className?: string }) {
  const s = SEV[level];
  return (
    <span className={cn("inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-semibold ring-1 ring-inset", s.cls, className)}>
      <s.Icon size={12} strokeWidth={2.2} />
      {s.label}
    </span>
  );
}

export function severityColor(level: SeverityLevel): string {
  return level === "critical" ? "bg-danger" : level === "warning" ? "bg-warn" : level === "info" ? "bg-info" : "bg-ok";
}

/** A code citation: file path header + the cited line with its number. */
export function CodeCite({ ev, className }: { ev?: Evidence; className?: string }) {
  if (!ev) return null;
  return (
    <div className={cn("overflow-hidden rounded-lg border border-line bg-code", className)}>
      <div className="flex items-center gap-1.5 border-b border-line bg-surface-2/60 px-2.5 py-1.5 text-[11px] text-muted">
        <FileCode2 size={12} className="shrink-0 text-faint" />
        <span className="truncate font-mono">{ev.path}</span>
        <span className="ml-auto shrink-0 font-mono text-faint">L{ev.line}</span>
      </div>
      <pre className="m-0 flex gap-3 overflow-x-auto px-2.5 py-2 font-mono text-[11.5px] leading-relaxed">
        <span className="select-none text-faint">{ev.line}</span>
        <code className="whitespace-pre-wrap break-words text-text">{ev.snippet}</code>
      </pre>
    </div>
  );
}

export function Spinner({ size = 14, className }: { size?: number; className?: string }) {
  return <LoaderCircle size={size} className={cn("animate-spin", className)} />;
}

/** "Ask ChatGPT" call-to-action used at the bottom of panels. */
export function AskButton({ onClick, children }: { onClick: () => void; children: ReactNode }) {
  return (
    <button
      onClick={onClick}
      className="group mt-5 flex w-full items-center gap-2 rounded-xl border border-dashed border-accent/35 bg-accent-soft/40 px-3.5 py-2.5 text-left text-[12.5px] font-medium text-accent transition-colors hover:bg-accent-soft"
    >
      <Sparkles size={14} className="shrink-0" />
      <span className="flex-1">{children}</span>
      <span className="text-accent/60 transition-transform group-hover:translate-x-0.5">→</span>
    </button>
  );
}

export function ago(iso: string): string {
  const s = Math.max(0, (Date.now() - Date.parse(iso)) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

