174	function FitOnChange({ fitKey, focusIds }: { fitKey?: string; focusIds?: string[] }) {
175	  const rf = useReactFlow();
176	  const focus = useRef(focusIds);
177	  focus.current = focusIds;
178	  useEffect(() => {
179	    const t = setTimeout(() => {
180	      const ids = focus.current;
181	      rf.fitView(
182	        ids?.length
183	          ? { nodes: ids.map((id) => ({ id })), padding: 0.2, duration: 400, maxZoom: 1.3 }
184	          : { padding: 0.12, duration: 350 },
185	      );
186	    }, 40);
187	    return () => clearTimeout(t);
188	  }, [fitKey, rf]);
189	  return null;
