192	export function Graph(props: GraphProps) {
193	  const { graph, ghostNodes = [], ghostEdges = [], nodeVisual, edgeVisual, pulseKey, badges = {} } = props;
194	  const defNode = props.defaultNodeVisual ?? "base";
195	  const defEdge = props.defaultEdgeVisual ?? "base";
196	
197	  const allNodes = useMemo(() => {
198	    const ids = new Set(graph.nodes.map((n) => n.id));
199	    return [...graph.nodes, ...ghostNodes.filter((n) => !ids.has(n.id))];
200	  }, [graph, ghostNodes]);
201	  const allEdges = useMemo(() => {
202	    const ids = new Set(graph.edges.map((e) => e.id));
203	    return [...graph.edges, ...ghostEdges.filter((e) => !ids.has(e.id))];
204	  }, [graph, ghostEdges]);
205	
206	  const positions = useMemo(() => layoutGraph(allNodes, allEdges), [allNodes, allEdges]);
207	
208	  const rfNodes: Node<CartographNodeData>[] = useMemo(
209	    () =>
210	      allNodes.map((n) => ({
211	        id: n.id,
212	        type: "component",
213	        position: positions.get(n.id) ?? { x: 0, y: 0 },
214	        data: { node: n, visual: nodeVisual[n.id] ?? defNode, badge: badges[n.id] },
215	        draggable: true,
216	        selectable: false,
217	        // Above every edge layer, so edge hit-areas never swallow node clicks.
218	        zIndex: 1000,
219	      })),
220	    [allNodes, positions, nodeVisual, defNode, badges],
221	  );
222	
223	  const rfEdges: Edge<CartographEdgeData>[] = useMemo(
224	    () =>
225	      allEdges
226	        .filter((e) => positions.has(e.from) && positions.has(e.to))
227	        .map((e) => {
228	          const visual = edgeVisual[e.id] ?? defEdge;
229	          // Pick handles by where the nodes ended up, so arrows never loop around.
230	          const down = (positions.get(e.to)!.y ?? 0) >= (positions.get(e.from)!.y ?? 0) + NODE_H / 2;
231	          return {
232	            id: e.id,
233	            source: e.from,
234	            target: e.to,
235	            sourceHandle: down ? "b" : "ts",
236	            targetHandle: down ? "t" : "bt",
237	            type: "dependency",
238	            data: { edge: e, visual, pulseKey },
239	            markerEnd: { type: MarkerType.ArrowClosed, width: 14, height: 14, color: markerColor[visual] },
240	            zIndex: visual === "active" || visual === "flagged" || visual === "added" ? 10 : visual === "dim" ? 0 : 1,
241	          };
242	        }),
243	    [allEdges, positions, edgeVisual, defEdge, pulseKey],
244	  );
245	
246	  // Refit when the container changes size (inline ↔ side panel ↔ fullscreen).
247	  const wrap = useRef<HTMLDivElement>(null);
248	  const [sizeKey, setSizeKey] = useState("");
249	  useEffect(() => {
250	    const el = wrap.current;
251	    if (!el || typeof ResizeObserver === "undefined") return;
252	    const ro = new ResizeObserver(([entry]) => {
253	      const { width, height } = entry.contentRect;
254	      setSizeKey(`${Math.round(width / 60)}x${Math.round(height / 60)}`);
255	    });
256	    ro.observe(el);
257	    return () => ro.disconnect();
258	  }, []);
259	
260	  return (
261	    <div ref={wrap} style={{ width: "100%", height: "100%" }}>
262	    <ReactFlow
263	      nodes={rfNodes}
264	      edges={rfEdges}
265	      nodeTypes={nodeTypes}
266	      edgeTypes={edgeTypes}
267	      fitView
268	      fitViewOptions={{ padding: 0.12 }}
269	      minZoom={0.2}
270	      maxZoom={2}
271	      proOptions={{ hideAttribution: true }}
272	      onNodeClick={(_, n) => props.onNodeClick?.(n.id)}
273	      onEdgeClick={(_, e) => props.onEdgeClick?.(e.id)}
274	      onPaneClick={() => props.onPaneClick?.()}
275	      nodesConnectable={false}
276	      elementsSelectable={false}
277	    >
278	      <svg width="0" height="0" className="absolute">
279	        <defs>
280	          <linearGradient id="cg-gradient" x1="0" y1="0" x2="1" y2="1">
281	            <stop offset="0%" stopColor="#2f6bff" />
282	            <stop offset="100%" stopColor="#7c4dff" />
283	          </linearGradient>
284	        </defs>
285	      </svg>
286	      <Background variant={BackgroundVariant.Dots} gap={20} size={1.4} color="var(--grid)" />
287	      <Controls showInteractive={false} position="bottom-left" />
288	      <FitOnChange fitKey={`${props.fitKey}|${sizeKey}`} focusIds={props.focusIds} />
289	    </ReactFlow>
290	    </div>
291	  );
292	}
