269	export function NodePanel({ graph, nodeId, onClose, onSelect, onBlast, onAsk }: { graph: CartographGraph; nodeId: string; onClose: () => void; onSelect: (id: string) => void; onBlast: (id: string) => void; onAsk: (t: string) => void }) {
270	  const node = graph.nodes.find((n) => n.id === nodeId);
271	  const nodes = useMemo(() => new Map(graph.nodes.map((n) => [n.id, n])), [graph]);
272	  if (!node) return null;
273	  const out = graph.edges.filter((e) => e.from === node.id);
274	  const inc = graph.edges.filter((e) => e.to === node.id);
275	  const Dep = ({ e, dir }: { e: (typeof graph.edges)[number]; dir: "out" | "in" }) => {
276	    const other = nodes.get(dir === "out" ? e.to : e.from);
277	    return (
278	      <div className="mb-3">
279	        <button onClick={() => other && onSelect(other.id)} className="group mb-1.5 flex w-full items-center gap-2 text-left">
280	          {other && <KindTile kind={other.kind} size="sm" />}
281	          <span className="truncate text-[13px] font-medium text-text group-hover:text-accent">{other?.label ?? "?"}</span>
282	          <KindTag>{e.kind}</KindTag>
283	          <span className="truncate text-[11.5px] text-muted">{e.label}</span>
284	        </button>
285	        <CodeCite ev={e.evidence[0]} />
286	      </div>
287	    );
288	  };
289	  return (
290	    <Panel>
291	      <PanelHead icon={<KindTile kind={node.kind} size="lg" />} title={node.label} sub={[kindMeta(node.kind).label, node.tech].filter(Boolean).join(" · ")} onClose={onClose} />
292	      <Prose>{node.summary}</Prose>
293	      {node.details.length > 0 &&
294	        (node.details.every((d) => d.length <= 42) ? (
295	          // Short facts (endpoints, tables, queue names) read best as code chips…
296	          <div className="mb-3 flex flex-wrap gap-1.5">
297	            {node.details.map((d) => (
298	              <Chip key={d} className="font-mono text-[11px]">
299	                {d}
300	              </Chip>
301	            ))}
302	          </div>
303	        ) : (
304	          // …while sentences read best as a list.
305	          <ul className="mb-4 flex list-none flex-col gap-1.5 p-0">
306	            {node.details.map((d) => (
307	              <li key={d} className="flex gap-2 text-[12.5px] leading-relaxed text-text/80">
308	                <span className="mt-[7px] size-1.5 shrink-0 rounded-full bg-accent/50" />
309	                {d}
310	              </li>
311	            ))}
312	          </ul>
313	        ))}
314	      {node.files.length > 0 && (
315	        <div className="mb-4 flex flex-wrap gap-1.5">
316	          {node.files.slice(0, 8).map((f) => (
317	            <span key={f.path} className="rounded-md bg-surface-2 px-1.5 py-[2px] font-mono text-[11px] text-muted">
318	              {f.path}
319	            </span>
320	          ))}
321	        </div>
322	      )}
323	      <Button variant="danger" className="w-full" onClick={() => onBlast(node.id)}>
324	        <Zap size={14} /> What breaks if this goes down?
325	      </Button>
326	      {out.length > 0 && <Eyebrow className="mt-6">Depends on · {out.length}</Eyebrow>}
327	      {out.map((e) => (
328	        <Dep key={e.id} e={e} dir="out" />
329	      ))}
330	      {inc.length > 0 && <Eyebrow className="mt-5">Used by · {inc.length}</Eyebrow>}
331	      {inc.map((e) => (
332	        <Dep key={e.id} e={e} dir="in" />
333	      ))}
334	      <AskButton onClick={() => onAsk(`Explain the ${node.label} component in ${graph.repo.name}: what it does and how it fits in.`)}>Ask ChatGPT about {node.label}</AskButton>
335	    </Panel>
336	  );
337	}
