543	
544	const STAGES = [
545	  { id: "scout", label: "Scout", desc: "Plans the work", Icon: Compass },
546	  { id: "reader", label: "Readers", desc: "Read the code", Icon: BookOpen },
547	  { id: "cartographer", label: "Cartographer", desc: "Draws the map", Icon: MapIcon },
548	  { id: "verifier", label: "Verifier", desc: "Checks every citation", Icon: ShieldCheck },
549	] as const;
550	
551	export function Progress({ job }: { job: JobView | null }) {
552	  const [now, setNow] = useState(Date.now());
553	  useEffect(() => {
554	    const t = setInterval(() => setNow(Date.now()), 500);
555	    return () => clearInterval(t);
556	  }, []);
557	  const log = job?.log ?? [];
558	  const state = (id: string): "todo" | "run" | "done" | "err" => {
559	    const msgs = log.filter((l) => (id === "verifier" ? l.message.startsWith("Verifier") : l.agent === id));
560	    if (msgs.some((m) => m.phase === "error") && !msgs.some((m) => m.phase === "done")) return "err";
561	    if (id === "reader") {
562	      const started = msgs.filter((m) => m.phase === "start").length;
563	      const done = msgs.filter((m) => m.phase === "done" || m.phase === "error").length;
564	      if (!started) return "todo";
565	      return done >= started && log.some((l) => l.agent === "cartographer") ? "done" : "run";
566	    }
567	    if (msgs.some((m) => m.phase === "done")) return "done";
568	    return msgs.length ? "run" : "todo";
569	  };
570	  const readers = log.filter((l) => l.agent === "reader" && l.phase === "start").length;
571	  const readersDone = log.filter((l) => l.agent === "reader" && (l.phase === "done" || l.phase === "error")).length;
572	  const elapsed = job ? Math.max(0, Math.round((now - Date.parse(job.startedAt)) / 1000)) : 0;
573	  const mm = `${Math.floor(elapsed / 60)}:${String(elapsed % 60).padStart(2, "0")}`;
574	  return (
575	    <div className="mx-auto w-full max-w-[760px] overflow-y-auto px-6 py-8">
576	      <motion.div {...fadeIn} className="mb-6 flex items-center gap-3.5">
577	        <CartographLogo size={40} />
578	        <div className="min-w-0 flex-1">
579	          <div className="text-[18px] font-semibold tracking-[-0.02em] text-text">Mapping {job?.repoName ?? "repository"}</div>
580	          <div className="text-[12.5px] text-muted">{job?.status === "error" ? "Mapping failed" : "A team of agents is reading the code"}</div>
581	        </div>
582	        <div className="rounded-lg border border-line bg-surface px-2.5 py-1 font-mono text-[13px] text-text tabular-nums shadow-card">{mm}</div>
583	      </motion.div>
584	
585	      <div className="grid grid-cols-2 gap-2.5 sm:grid-cols-4">
586	        {STAGES.map((s, i) => {
587	          const st = state(s.id);
588	          return (
589	            <motion.div key={s.id} {...fadeIn} transition={{ ...fadeIn.transition, delay: i * 0.05 }}>
590	              <Card className={cn("relative h-full px-3.5 py-3 transition-all", st === "run" && "border-accent/50 ring-4 ring-accent/10", st === "err" && "border-danger/40")}>
591	                <div className="flex items-center justify-between">
592	                  <span className={cn("grid size-8 place-items-center rounded-lg", st === "done" ? "bg-ok/12 text-ok" : st === "run" ? "bg-accent-soft text-accent" : "bg-surface-2 text-faint")}>
593	                    <s.Icon size={16} />
594	                  </span>
595	                  {st === "done" ? <CircleCheck size={16} className="text-ok" /> : st === "run" ? <Spinner className="text-accent" /> : null}
596	                </div>
597	                <div className="mt-2.5 text-[13px] font-semibold text-text">{s.label}</div>
598	                <div className="text-[11.5px] text-muted">{s.id === "reader" && readers ? `${readersDone} of ${readers} done` : s.desc}</div>
599	                {s.id === "reader" && readers > 0 && (
600	                  <div className="mt-2 flex gap-1">
601	                    {Array.from({ length: readers }, (_, r) => (
602	                      <span key={r} className={cn("h-1 flex-1 rounded-full transition-colors", r < readersDone ? "bg-ok" : "bg-accent/25")} />
603	                    ))}
604	                  </div>
605	                )}
606	              </Card>
607	            </motion.div>
608	          );
609	        })}
610	      </div>
611	
612	      <div className="mt-4 overflow-hidden rounded-xl border border-line bg-[#0f0f12] shadow-card">
613	        <div className="flex items-center gap-1.5 border-b border-white/5 px-3.5 py-2">
614	          <span className="size-2.5 rounded-full bg-[#ff5f57]" />
615	          <span className="size-2.5 rounded-full bg-[#febc2e]" />
616	          <span className="size-2.5 rounded-full bg-[#28c840]" />
617	          <span className="ml-2 font-mono text-[11px] text-white/40">agents · live</span>
618	        </div>
619	        <div className="min-h-[200px] px-3.5 py-3 font-mono text-[11.5px] leading-[1.75]">
620	          {log.slice(-14).map((l, i) => (
621	            <motion.div key={`${l.at}-${i}`} initial={{ opacity: 0, x: -4 }} animate={{ opacity: 1, x: 0 }} className={cn("flex gap-3", l.phase === "error" ? "text-[#ff8a8a]" : l.phase === "done" ? "text-white/90" : "text-white/55")}>
622	              <span className="w-[86px] shrink-0 text-[#a99bff]">{l.agent === "pipeline" ? "cartograph" : l.agent}</span>
623	              <span className="min-w-0 break-words">{l.message}</span>
624	            </motion.div>
625	          ))}
626	          {job?.status === "running" && <span className="cg-caret text-[#a99bff]">▍</span>}
627	        </div>
628	      </div>
629	      {job?.error && <div className="mt-3 rounded-lg bg-danger/10 px-3 py-2 text-[12.5px] text-danger">{job.error}</div>}
630	    </div>
631	  );
632	}
