"""FastAPI server for UPI dispute resolution."""

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
from agents import DisputeOrchestrator
from mock_data import get_mock_data
import json

app = FastAPI(title="DisputePro - UPI Dispute Resolution")

# Enable CORS for frontend
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Initialize orchestrator with mock data
mock_data = get_mock_data()
orchestrator = DisputeOrchestrator(mock_data)


class DisputeSubmission(BaseModel):
    """User submits a UPI dispute complaint."""
    utr: str  # Unique Transaction Reference
    customer_id: str
    complaint: str
    today: str = "2026-10-10"  # Demo date


class DisputeResponse(BaseModel):
    """Response with agent analysis."""
    id: str
    status: str
    summary: dict
    traces: dict
    entire_checkpoint: dict
    cfo_ai_model: dict


@app.get("/health")
def health():
    """Health check."""
    return {"status": "ok", "service": "DisputePro"}


@app.post("/api/resolve")
def resolve_dispute(submission: DisputeSubmission):
    """
    Submit a UPI dispute and get agent analysis.

    Example:
    {
        "utr": "412398765011",
        "customer_id": "rahul",
        "complaint": "My UPI payment was debited but not credited.",
        "today": "2026-10-10"
    }
    """
    try:
        # Run agents
        result = orchestrator.resolve(
            utr=submission.utr,
            customer_id=submission.customer_id,
            today=submission.today,
        )

        return {
            "id": result.id,
            "status": result.status,
            "summary": {
                "transaction": {
                    "utr": result.transaction.utr,
                    "amount": f"₹{result.transaction.amount_paise / 100:.2f}",
                    "status": result.transaction.status,
                    "customer": result.transaction.customer_id,
                },
                "risk": {
                    "score": result.risk_assessment.score_percent,
                    "band": result.risk_assessment.band,
                    "recommendation": result.risk_assessment.recommendation,
                },
                "policy": {
                    "route": result.policy_decision.path,
                    "compensation": f"₹{result.policy_decision.compensation_paise / 100:.2f}",
                    "days_late": result.policy_decision.days_breached,
                },
                "action": {
                    "type": result.proposed_action.action_type if result.proposed_action else "none",
                    "reasoning": result.proposed_action.reasoning if result.proposed_action else "No action needed",
                } if result.proposed_action else None,
            },
            "traces": {
                "investigator": result.investigator_trace,
                "policy": result.policy_trace,
                "resolver": result.resolver_trace,
            },
            "entire_checkpoint": result.entire_checkpoint,
            "cfo_ai_model": result.cfo_ai_model,
            "created_at": result.created_at,
        }

    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Internal error: {str(e)}")


@app.get("/api/transactions")
def list_transactions():
    """List available demo transactions."""
    return {
        "transactions": [
            {
                "utr": t["utr"],
                "customer_id": t["customer_id"],
                "amount": f"₹{t['amount_paise'] / 100:.2f}",
                "status": t["status"],
                "notes": t["notes"],
            }
            for t in mock_data["transactions"]
        ]
    }


@app.get("/api/customers")
def list_customers():
    """List demo customers."""
    return {
        "customers": [
            {
                "id": p["customer_id"],
                "velocity": p["velocity"],
                "is_mule": p["is_mule"],
            }
            for p in mock_data["risk_profiles"]
        ]
    }


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)

