"""Data models for UPI dispute resolution."""

from dataclasses import dataclass, asdict
from datetime import datetime
from typing import Optional, Literal
import json

# RBI deadline paths
ROUTE_TYPE = Literal["A", "B", "C", "D", "HUMAN_REVIEW"]
ACTION_TYPE = Literal["reversal", "fraud_hold", "escalation"]
RISK_BAND = Literal["GREEN", "YELLOW", "RED"]

@dataclass
class Transaction:
    """A UPI transaction."""
    utr: str  # Unique Transaction Reference
    customer_id: str
    amount_paise: int
    status: Literal["FAILED", "PENDING", "SUCCESS"]
    reversal_status: Literal["NONE", "PENDING", "COMPLETED"]
    created_at: str  # ISO timestamp

    def to_dict(self):
        return asdict(self)


@dataclass
class DisputeSubmission:
    """A customer's dispute complaint."""
    id: str
    customer_id: str
    utr: str
    complaint: str
    amount_paise: int
    created_at: str
    today: str  # Demo date for calculating deadlines


@dataclass
class RiskSignals:
    """Fraud risk indicators."""
    velocity: Literal["NORMAL", "HIGH", "EXTREME"]
    geo: str  # Country
    device: Literal["KNOWN", "NEW"]
    vpa_age_days: int
    is_mule: bool = False

    def to_dict(self):
        return asdict(self)


@dataclass
class PolicyDecision:
    """RBI policy decision."""
    path: ROUTE_TYPE  # A, B, C, D, or HUMAN_REVIEW
    compensation_paise: int  # How much to credit
    deadline: Optional[str]  # ISO date when deadline is
    days_breached: int  # Days late (negative if on time)
    policy_version: str  # RBI_2023_UPI_DISPUTES_v2.1
    policy_text: str  # Human-readable explanation

    def to_dict(self):
        return asdict(self)


@dataclass
class RiskAssessment:
    """Fraud risk score."""
    score_percent: int  # 0-100
    band: RISK_BAND
    factors: list[str]  # Why this score?
    recommendation: Literal["APPROVE", "HOLD", "INVESTIGATE"]

    def to_dict(self):
        return asdict(self)


@dataclass
class ProposedAction:
    """Agent's proposed action."""
    id: str
    action_type: ACTION_TYPE
    utr: str
    customer_id: str
    principal_paise: int
    compensation_paise: Optional[int]
    beneficiary_vpa: str
    reasoning: str
    created_at: str

    def to_dict(self):
        return asdict(self)


@dataclass
class DisputeResult:
    """Complete dispute resolution result."""
    id: str
    status: Literal["COMPLETED", "AWAITING_APPROVAL", "HUMAN_REVIEW", "FAILED"]
    transaction: Transaction
    risk_signals: RiskSignals
    policy_decision: PolicyDecision
    risk_assessment: RiskAssessment
    proposed_action: Optional[ProposedAction]

    # Evidence for judges
    investigator_trace: dict  # neatLogs trace
    policy_trace: dict
    resolver_trace: dict
    entire_checkpoint: dict  # Entire.io checkpoint
    cfo_ai_model: dict  # Business economics

    created_at: str

    def to_dict(self):
        return {
            "id": self.id,
            "status": self.status,
            "transaction": self.transaction.to_dict(),
            "risk_signals": self.risk_signals.to_dict(),
            "policy_decision": self.policy_decision.to_dict(),
            "risk_assessment": self.risk_assessment.to_dict(),
            "proposed_action": self.proposed_action.to_dict() if self.proposed_action else None,
            "investigator_trace": self.investigator_trace,
            "policy_trace": self.policy_trace,
            "resolver_trace": self.resolver_trace,
            "entire_checkpoint": self.entire_checkpoint,
            "cfo_ai_model": self.cfo_ai_model,
            "created_at": self.created_at,
        }
"""FastAPI server for UPI dispute resolution."""

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
from agents import DisputeOrchestrator
from mock_data import get_mock_data
import json

app = FastAPI(title="DisputePro - UPI Dispute Resolution")

# Enable CORS for frontend
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Initialize orchestrator with mock data
mock_data = get_mock_data()
orchestrator = DisputeOrchestrator(mock_data)


class DisputeSubmission(BaseModel):
    """User submits a UPI dispute complaint."""
    utr: str  # Unique Transaction Reference
    customer_id: str
    complaint: str
    today: str = "2026-10-10"  # Demo date


class DisputeResponse(BaseModel):
    """Response with agent analysis."""
    id: str
    status: str
    summary: dict
    traces: dict
    entire_checkpoint: dict
    cfo_ai_model: dict


@app.get("/health")
def health():
    """Health check."""
    return {"status": "ok", "service": "DisputePro"}


@app.post("/api/resolve")
def resolve_dispute(submission: DisputeSubmission):
    """
    Submit a UPI dispute and get agent analysis.

    Example:
    {
        "utr": "412398765011",
        "customer_id": "rahul",
        "complaint": "My UPI payment was debited but not credited.",
        "today": "2026-10-10"
    }
    """
    try:
        # Run agents
        result = orchestrator.resolve(
            utr=submission.utr,
            customer_id=submission.customer_id,
            today=submission.today,
        )

        return {
            "id": result.id,
            "status": result.status,
            "summary": {
                "transaction": {
                    "utr": result.transaction.utr,
                    "amount": f"₹{result.transaction.amount_paise / 100:.2f}",
                    "status": result.transaction.status,
                    "customer": result.transaction.customer_id,
                },
                "risk": {
                    "score": result.risk_assessment.score_percent,
                    "band": result.risk_assessment.band,
                    "recommendation": result.risk_assessment.recommendation,
                },
                "policy": {
                    "route": result.policy_decision.path,
                    "compensation": f"₹{result.policy_decision.compensation_paise / 100:.2f}",
                    "days_late": result.policy_decision.days_breached,
                },
                "action": {
                    "type": result.proposed_action.action_type if result.proposed_action else "none",
                    "reasoning": result.proposed_action.reasoning if result.proposed_action else "No action needed",
                } if result.proposed_action else None,
            },
            "traces": {
                "investigator": result.investigator_trace,
                "policy": result.policy_trace,
                "resolver": result.resolver_trace,
            },
            "entire_checkpoint": result.entire_checkpoint,
            "cfo_ai_model": result.cfo_ai_model,
            "created_at": result.created_at,
        }

    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Internal error: {str(e)}")


@app.get("/api/transactions")
def list_transactions():
