from fastapi.responses import StreamingResponse
from pydantic import BaseModel

from agents import Run, decide, orchestrate, rupees
from scenarios import build_scenarios

app = FastAPI(title="DisputePro")
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])

PACES = {"slow": 1.0, "normal": 0.55, "fast": 0.2, "instant": 0.0}
RUNS: dict[str, Run] = {}


class RunRequest(BaseModel):
    scenario_id: str
    complaint: str | None = None
    pace: str = "normal"


class Decision(BaseModel):
    approve: bool
    reviewer: str = "Ops reviewer"


def _sse(run: Run, task_factory):
    async def body():
        task = asyncio.create_task(task_factory())
        while True:
            getter = asyncio.create_task(run.queue.get())
            done, _ = await asyncio.wait({getter, task}, return_when=asyncio.FIRST_COMPLETED)
            if getter in done:
                yield f"data: {json.dumps(getter.result(), default=str)}\n\n"
                continue
            getter.cancel()
            while not run.queue.empty():
                yield f"data: {json.dumps(run.queue.get_nowait(), default=str)}\n\n"
            if task.exception():
                yield f"data: {json.dumps({'type': 'run_failed', 'error': str(task.exception())})}\n\n"
            break

    return StreamingResponse(body(), media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


@app.get("/health")
def health():
    return {"status": "ok"}


@app.get("/api/scenarios")
def scenarios():
    return [
        {"id": s["id"], "label": s["label"], "customer": s["customer"]["name"], "complaint": s["complaint"],
         "utr": s["txn"]["utr"], "amount": rupees(s["txn"]["amount_paise"])}
        for s in build_scenarios().values()
    ]


@app.post("/api/runs")
async def start_run(req: RunRequest):
    cases = build_scenarios()
    if req.scenario_id not in cases:
        raise HTTPException(404, f"Unknown scenario {req.scenario_id}")
    scenario = cases[req.scenario_id]
    run = Run(scenario, (req.complaint or scenario["complaint"]).strip(), PACES.get(req.pace, PACES["normal"]))
    RUNS[run.id] = run
    return _sse(run, lambda: orchestrate(run))


@app.post("/api/runs/{run_id}/decision")
async def run_decision(run_id: str, body: Decision):
    run = RUNS.get(run_id)
    if not run:
        raise HTTPException(404, "Run not found")
    if run.status != "AWAITING_APPROVAL":
        raise HTTPException(409, f"Run is {run.status}, not awaiting approval")
    run.status = "DECIDING"
    return _sse(run, lambda: decide(run, body.approve, body.reviewer))


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=8000)

export const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000'

export type NodeId = 'complaint' | 'orchestrator' | 'investigator' | 'policy' | 'resolver' | 'human' | 'outcome'
export type NodeStatus = 'idle' | 'running' | 'done' | 'skipped' | 'waiting'
export type EdgeState = 'idle' | 'active' | 'taken' | 'skipped'
export type StepStatus = 'running' | 'ok' | 'warn' | 'bad' | 'info'

export interface Scenario {
  id: string
  label: string
  customer: string
  complaint: string
  utr: string
  amount: string
}

export interface NodeState {
  status: NodeStatus
  activity?: string
  durationMs?: number
}

export interface Step {
  id: string
  node: NodeId
  kind: string
  title: string
  detail?: string | null
  status: StepStatus
  result?: string
  data?: Record<string, unknown> | null
  t: number
}

export interface Action {
  kind: 'credit' | 'request' | 'info'
  label: string
  amount_paise: number
  state: 'proposed' | 'done' | 'scheduled' | 'cancelled'
  ref?: string
}

export interface Outcome {
  status: 'RESOLVED' | 'ACTIONED' | 'CLOSED' | 'MONITORING' | 'AWAITING_APPROVAL' | 'ESCALATED'
  headline: string
  summary: string
  category: string
  actions: Action[]
  payout_paise: number
  risk_band: 'LOW' | 'MEDIUM' | 'HIGH' | null
  risk_score?: number
  customer_message: string
  citation: string | null
  route: NodeId[]
}

export interface RunState {
  phase: 'idle' | 'running' | 'awaiting' | 'done' | 'error'
  runId?: string
  customer?: string
  utr?: string
  amount?: string
  nodes: Record<NodeId, NodeState>
  edges: Record<string, EdgeState>
  steps: Step[]
  outcome?: Outcome
  error?: string
  elapsedMs: number
}

export const EDGE_IDS = [
  'complaint>orchestrator',
  'orchestrator>investigator',
  'orchestrator>policy',
  'orchestrator>resolver',
  'resolver>human',
  'investigator>outcome',
  'policy>outcome',
  'resolver>outcome',
  'human>outcome',
] as const

const NODE_IDS: NodeId[] = ['complaint', 'orchestrator', 'investigator', 'policy', 'resolver', 'human', 'outcome']

export function initialRunState(): RunState {
  return {
    phase: 'idle',
    nodes: Object.fromEntries(NODE_IDS.map((n) => [n, { status: 'idle' }])) as Record<NodeId, NodeState>,
    edges: Object.fromEntries(EDGE_IDS.map((e) => [e, 'idle'])),
    steps: [],
    elapsedMs: 0,
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type RunEvent = { type: string; t: number; [k: string]: any }

export function reduceRun(state: RunState, ev: RunEvent): RunState {
  const elapsedMs = Math.max(state.elapsedMs, ev.t ?? 0)
  switch (ev.type) {
    case 'reset':
      return initialRunState()
    case 'run_started':
      return { ...initialRunState(), phase: 'running', runId: ev.run_id, customer: ev.customer, utr: ev.utr, amount: ev.amount }
    case 'node':
      return {
        ...state,
        elapsedMs,
        nodes: {
          ...state.nodes,
          [ev.node]: {
            ...state.nodes[ev.node as NodeId],
            status: ev.status,
            activity: ev.activity ?? state.nodes[ev.node as NodeId].activity,
            durationMs: ev.duration_ms ?? state.nodes[ev.node as NodeId].durationMs,
          },
        },
      }
    case 'edge':
      return { ...state, elapsedMs, edges: { ...state.edges, [ev.edge]: ev.state } }
    case 'step': {
      const step: Step = { id: ev.id, node: ev.node, kind: ev.kind, title: ev.title, detail: ev.detail, status: ev.status, data: ev.data, t: ev.t }
      const node = state.nodes[step.node]
      const activity = step.kind === 'tool' ? `Calling ${step.title}` : step.title
      return { ...state, elapsedMs, steps: [...state.steps, step], nodes: { ...state.nodes, [step.node]: { ...node, activity } } }
    }
    case 'step_update':
      return {
        ...state,
        elapsedMs,
        steps: state.steps.map((s) => (s.id === ev.id ? { ...s, status: ev.status, result: ev.result, data: ev.data } : s)),
      }
    case 'run_finished': {
      const awaiting = ev.outcome.status === 'AWAITING_APPROVAL'
      const edges = { ...state.edges }
      const nodes = { ...state.nodes }
      if (!awaiting) {
        for (const k of Object.keys(edges)) if (edges[k] === 'idle') edges[k] = 'skipped'
        for (const k of NODE_IDS) if (nodes[k].status === 'idle') nodes[k] = { ...nodes[k], status: 'skipped' }
      }
      return { ...state, elapsedMs, edges, nodes, outcome: ev.outcome, phase: awaiting ? 'awaiting' : 'done' }
    }
    case 'run_failed':
      return { ...state, phase: 'error', error: ev.error }
    default:
      return state
  }
}

export async function streamEvents(path: string, body: unknown, onEvent: (ev: RunEvent) => void, signal?: AbortSignal) {
  const res = await fetch(`${API_URL}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    signal,
  })
  if (!res.ok || !res.body) {
    const detail = await res.text().catch(() => '')
    throw new Error(`Request failed (${res.status}) ${detail}`)
  }
  const reader = res.body.getReader()
  const decoder = new TextDecoder()
  let buf = ''
  for (;;) {
    const { done, value } = await reader.read()
    if (done) break
    buf += decoder.decode(value, { stream: true })
    let idx
    while ((idx = buf.indexOf('\n\n')) >= 0) {
      const chunk = buf.slice(0, idx)
      buf = buf.slice(idx + 2)
      const line = chunk.split('\n').find((l) => l.startsWith('data: '))
      if (line) onEvent(JSON.parse(line.slice(6)))
    }
  }
}

export function formatPaise(p: number) {
  const r = p / 100
  return '₹' + r.toLocaleString('en-IN', { maximumFractionDigits: p % 100 ? 2 : 0 })
}

