'use client'

import type { EdgeState, NodeId, NodeState, RunState } from '@/lib/run'
import { Icon, NODE_META } from './meta'

const W = 220
const H = 76
const POS: Record<NodeId, { x: number; y: number }> = {
  complaint: { x: 440, y: 12 },
  orchestrator: { x: 440, y: 128 },
  investigator: { x: 80, y: 272 },
  policy: { x: 440, y: 272 },
  resolver: { x: 800, y: 272 },
  human: { x: 800, y: 452 },
  outcome: { x: 440, y: 452 },
}

const EDGE_PATHS: Record<string, string> = {
  'complaint>orchestrator': 'M550 88 L550 128',
  'orchestrator>investigator': 'M550 204 C550 240 190 236 190 272',
  'orchestrator>policy': 'M550 204 L550 272',
  'orchestrator>resolver': 'M550 204 C550 240 910 236 910 272',
  'investigator>outcome': 'M190 348 C190 440 300 490 440 490',
  'policy>outcome': 'M550 348 L550 452',
  'resolver>outcome': 'M860 348 C860 410 640 400 640 452',
  'resolver>human': 'M960 348 L960 452',
  'human>outcome': 'M800 490 L660 490',
}

function endpoints(d: string) {
  const nums = d.match(/-?\d+(\.\d+)?/g)!.map(Number)
  return { a: [nums[0], nums[1]], b: [nums[nums.length - 2], nums[nums.length - 1]] }
}

function Edge({ id, state }: { id: string; state: EdgeState }) {
  const d = EDGE_PATHS[id]
  const { a, b } = endpoints(d)
  const pathId = `edge-${id.replace('>', '-')}`
  const portColor = state === 'taken' ? '#10b981' : state === 'active' ? '#8b5cf6' : '#cbd5e1'
  return (
    <g>
      <path id={pathId} d={d} fill="none" stroke="#e2e8f0" strokeWidth={2} />
      {state === 'skipped' && <path d={d} fill="none" stroke="#94a3b8" strokeWidth={2} strokeDasharray="2 6" strokeLinecap="round" />}
      {state === 'active' && (
        <>
          <path d={d} fill="none" stroke="#a78bfa" strokeWidth={2.5} strokeDasharray="7 7" className="edge-flow" />
          {[0, 0.45, 0.9].map((begin) => (
            <circle key={begin} r={4.5} fill="#7c3aed" className="drop-shadow">
              <animateMotion dur="1.35s" begin={`${begin}s`} repeatCount="indefinite" rotate="auto">
                <mpath href={`#${pathId}`} />
              </animateMotion>
            </circle>
          ))}
        </>
      )}
      {state === 'taken' && <path d={d} fill="none" stroke="#10b981" strokeWidth={2.5} pathLength={1} className="edge-draw" />}
      <circle cx={a[0]} cy={a[1]} r={3.5} fill="white" stroke={portColor} strokeWidth={2} />
      <circle cx={b[0]} cy={b[1]} r={3.5} fill="white" stroke={portColor} strokeWidth={2} />
    </g>
  )
}

const STATUS_CHIP: Record<NodeState['status'], { text: string; cls: string }> = {
  idle: { text: 'Not reached', cls: 'bg-slate-100 text-slate-500' },
  running: { text: 'Working', cls: 'bg-violet-100 text-violet-700' },
  done: { text: 'Done', cls: 'bg-emerald-100 text-emerald-700' },
  skipped: { text: 'Skipped', cls: 'bg-slate-100 text-slate-400' },
  waiting: { text: 'Waiting', cls: 'bg-amber-100 text-amber-700' },
}

function Node({ id, state, selected, onSelect, stepCount }: {
  id: NodeId
  state: NodeState
  selected: boolean
  onSelect: (id: NodeId) => void
  stepCount: number
}) {
  const meta = NODE_META[id]
  const { x, y } = POS[id]
  const chip = STATUS_CHIP[state.status]
  const ring =
    state.status === 'running'
      ? 'border-violet-400 node-glow'
      : state.status === 'waiting'
        ? 'border-amber-400 node-wait'
        : state.status === 'done'
          ? 'border-emerald-300'
          : state.status === 'skipped'
            ? 'border-dashed border-slate-300 opacity-55'
            : 'border-slate-200'
  const showActivity = state.status !== 'idle' && state.activity
  return (
    <foreignObject x={x - 8} y={y - 8} width={W + 16} height={H + 16}>
      <button
        onClick={() => onSelect(id)}
        className={`m-2 flex h-[76px] w-[220px] flex-col justify-center gap-1 rounded-2xl border-2 bg-white px-3 text-left shadow-sm transition hover:shadow-md ${ring} ${
          selected ? 'outline outline-2 outline-offset-2 outline-indigo-400' : ''
        }`}
      >
        <div className="flex items-center gap-2">
          <span className={`grid h-7 w-7 shrink-0 place-items-center rounded-lg ${meta.chip}`}>
            {state.status === 'running' ? (
              <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-current border-t-transparent" />
            ) : state.status === 'done' ? (
              <Icon name="check" className="h-4 w-4" />
            ) : (
              <Icon name={id} className="h-4 w-4" />
            )}
          </span>
          <span className="min-w-0 flex-1 truncate text-[13px] font-semibold text-slate-900">{meta.label}</span>
          <span className={`rounded-full px-1.5 py-0.5 text-[10px] font-semibold ${chip.cls}`}>{chip.text}</span>
        </div>
        <div className={`truncate text-[11px] ${showActivity ? 'text-slate-600' : 'text-slate-400'}`} title={state.activity}>
          {showActivity ? state.activity : meta.role}
        </div>
        <div className="flex gap-2 text-[10px] text-slate-400">
          {stepCount > 0 && <span>{stepCount} steps</span>}
          {state.durationMs != null && <span>{(state.durationMs / 1000).toFixed(1)}s</span>}
        </div>
      </button>
    </foreignObject>
  )
}

export default function RunGraph({ run, selected, onSelect }: {
  run: RunState
  selected: NodeId | null
  onSelect: (id: NodeId) => void
}) {
  const counts = run.steps.reduce<Record<string, number>>((acc, s) => ((acc[s.node] = (acc[s.node] ?? 0) + 1), acc), {})
  return (
    <div>
      <div className="overflow-x-auto">
        <svg viewBox="0 0 1100 540" className="mx-auto block w-full min-w-[720px]" role="img" aria-label="Agent run graph">
          <defs>
            <pattern id="dots" width="22" height="22" patternUnits="userSpaceOnUse">
              <circle cx="1" cy="1" r="1" fill="#e2e8f0" />
            </pattern>
          </defs>
          <rect width="1100" height="540" fill="url(#dots)" />
          {Object.keys(EDGE_PATHS).map((id) => (
            <Edge key={id} id={id} state={run.edges[id]} />
          ))}
          {(Object.keys(POS) as NodeId[]).map((id) => (
            <Node key={id} id={id} state={run.nodes[id]} selected={selected === id} onSelect={onSelect} stepCount={counts[id] ?? 0} />
          ))}
        </svg>
      </div>
      <div className="flex flex-wrap items-center gap-5 border-t border-slate-100 px-5 py-3 text-xs text-slate-500">
        <Legend swatch={<span className="h-0.5 w-6 rounded bg-emerald-500" />} label="Taken" />
        <Legend swatch={<span className="h-0.5 w-6 rounded bg-violet-400" />} label="Active" />
        <Legend swatch={<span className="w-6 border-t-2 border-dotted border-slate-400" />} label="Not taken" />
        <Legend swatch={<span className="h-0.5 w-6 rounded bg-slate-200" />} label="Not reached" />
        <span className="ml-auto">Click a node to filter its log</span>
      </div>
    </div>
  )
}

function Legend({ swatch, label }: { swatch: JSX.Element; label: string }) {
  return (
    <span className="flex items-center gap-2">
      {swatch}
      {label}
    </span>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import type { NodeId, RunState, Step } from '@/lib/run'
import { Icon, NODE_META } from './meta'

function Typewriter({ text, live }: { text: string; live: boolean }) {
  const [n, setN] = useState(live ? 0 : text.length)
  useEffect(() => {
    if (!live) return
    const per = Math.max(6, Math.min(18, 900 / text.length))
    const id = setInterval(() => setN((v) => (v >= text.length ? (clearInterval(id), v) : v + 2)), per)
    return () => clearInterval(id)
  }, [text, live])
  return (
    <>
      {text.slice(0, n)}
      {n < text.length && <span className="ml-0.5 inline-block h-3 w-1.5 animate-pulse bg-slate-400 align-middle" />}
    </>
  )
}

const TONE: Record<Step['status'], string> = {
  running: 'text-violet-700',
  ok: 'text-emerald-700',
  warn: 'text-amber-700',
  bad: 'text-rose-700',
  info: 'text-slate-700',
}

const BORDER: Record<Step['status'], string> = {
  running: 'border-violet-300',
  ok: 'border-emerald-400',
  warn: 'border-amber-400',
  bad: 'border-rose-400',
  info: 'border-slate-300',
}

function StepRow({ step, live }: { step: Step; live: boolean }) {
  const [open, setOpen] = useState(false)
  const time = <span className="shrink-0 font-mono text-[10px] text-slate-400">+{(step.t / 1000).toFixed(1)}s</span>

  if (step.kind === 'tool') {
    return (
      <div className="step-in rounded-lg border border-slate-200 bg-slate-50/70 px-3 py-2">
        <div className="flex items-center gap-2">
          <span className="grid h-5 w-5 place-items-center rounded bg-slate-900 text-white">
            <Icon name="tool" className="h-3 w-3" />
          </span>
          <code className="min-w-0 flex-1 truncate text-[12px] text-slate-800">{step.detail}</code>
          {step.status === 'running' ? (
            <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-violet-500 border-t-transparent" />
          ) : (
            <span className={`text-[10px] font-semibold uppercase ${TONE[step.status]}`}>{step.status === 'bad' ? 'flag' : step.status}</span>
          )}
          {time}
        </div>
        {step.status === 'running' ? (
          <div className="mt-1 pl-7 text-[12px] text-slate-400">executing…</div>
        ) : (
          <div className="mt-1 flex items-start gap-2 pl-7">
            <span className={`flex-1 text-[12px] ${TONE[step.status]}`}>→ {step.result}</span>
            {step.data && (
              <button onClick={() => setOpen((v) => !v)} className="text-[11px] font-medium text-indigo-600 hover:underline">
                {open ? 'hide' : 'raw'}
              </button>
            )}
          </div>
        )}
        {open && step.data && (
          <pre className="mt-2 max-h-48 overflow-auto rounded bg-slate-900 p-2 text-[11px] leading-relaxed text-slate-100">
            {JSON.stringify(step.data, null, 2)}
          </pre>
        )}
      </div>
    )
  }

  if (step.kind === 'check') {
    return (
      <div className="step-in flex items-center gap-2 px-1 py-0.5 text-[12px]">
        <span className={step.status === 'bad' ? 'text-rose-600' : 'text-emerald-600'}>
          <Icon name={step.status === 'bad' ? 'x' : step.status === 'warn' ? 'decision' : 'check'} className="h-3.5 w-3.5" />
        </span>
        <span className="flex-1 text-slate-700">{step.title}</span>
        <span className={`font-mono text-[11px] ${TONE[step.status]}`}>{step.detail}</span>
        {time}
      </div>
    )
  }

  if (step.kind === 'draft') {
    return (
      <div className="step-in rounded-lg border border-indigo-200 bg-indigo-50/60 px-3 py-2">
        <div className="mb-1 flex items-center gap-2 text-[12px] font-semibold text-indigo-800">
          <Icon name="draft" className="h-3.5 w-3.5" /> {step.title}
          <span className="ml-auto">{time}</span>
        </div>
        <p className="whitespace-pre-line text-[12px] leading-relaxed text-indigo-950">
          <Typewriter text={step.detail ?? ''} live={live} />
        </p>
      </div>
    )
  }

  const emphasised = step.kind === 'decision' || step.kind === 'finding'
  return (
    <div className={`step-in flex gap-2 ${emphasised ? `rounded-r-lg border-l-[3px] bg-white py-1.5 pl-2.5 pr-2 shadow-sm ${BORDER[step.status]}` : 'px-1 py-0.5'}`}>
      <span className={`mt-0.5 ${emphasised ? TONE[step.status] : 'text-slate-400'}`}>
        <Icon name={step.kind} className="h-3.5 w-3.5" />
      </span>
      <div className="min-w-0 flex-1">
        <div className={`text-[12.5px] ${emphasised ? `font-semibold ${TONE[step.status]}` : step.kind === 'think' ? 'italic text-slate-500' : 'font-medium text-slate-800'}`}>
          {step.title}
        </div>
        {step.detail && (
          <div className="text-[12px] leading-relaxed text-slate-600">
            <Typewriter text={step.detail} live={live} />
          </div>
        )}
      </div>
      {time}
    </div>
  )
}

export default function ActivityFeed({ run, filter, onClearFilter }: {
  run: RunState
  filter: NodeId | null
  onClearFilter: () => void
}) {
  const scroller = useRef<HTMLDivElement>(null)
  const follow = useRef(true)
  const seen = useRef(new Set<string>())
  const steps = filter ? run.steps.filter((s) => s.node === filter) : run.steps

  useEffect(() => {
    const el = scroller.current
    if (el && follow.current) el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' })
  }, [steps.length, run.steps[run.steps.length - 1]?.status])

  useEffect(() => {
    if (run.phase === 'idle') seen.current.clear()
  }, [run.phase])

  const groups: { node: NodeId; steps: Step[] }[] = []
  for (const s of steps) {
    const last = groups[groups.length - 1]
    if (last && last.node === s.node) last.steps.push(s)
    else groups.push({ node: s.node, steps: [s] })
  }

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center gap-2 border-b border-slate-100 px-4 py-3">
        <h3 className="text-sm font-semibold text-slate-900">Live agent log</h3>
        {run.phase === 'running' && (
          <span className="flex items-center gap-1.5 rounded-full bg-violet-50 px-2 py-0.5 text-[11px] font-medium text-violet-700">
            <span className="h-1.5 w-1.5 animate-ping rounded-full bg-violet-500" /> streaming
          </span>
        )}
        {filter && (
          <button onClick={onClearFilter} className={`rounded-full px-2 py-0.5 text-[11px] font-medium ${NODE_META[filter].chip}`}>
            {NODE_META[filter].label} ✕
          </button>
        )}
        <span className="ml-auto font-mono text-[11px] text-slate-400">{steps.length} lines</span>
      </div>
      <div
        ref={scroller}
        onScroll={(e) => {
          const el = e.currentTarget
          follow.current = el.scrollHeight - el.scrollTop - el.clientHeight < 80
        }}
        className="flex-1 space-y-3 overflow-y-auto px-4 py-3"
      >
        {steps.length === 0 && (
          <div className="grid h-full place-items-center text-center text-sm text-slate-400">
            {run.phase === 'idle' ? 'Pick a case and run the agents — every tool call and decision streams here.' : 'No steps for this node.'}
          </div>
        )}
        {groups.map((g, i) => (
          <div key={`${g.node}-${i}`} className="space-y-1.5">
            <div className="flex items-center gap-2 pt-1">
              <span className={`h-2 w-2 rounded-full ${NODE_META[g.node].dot}`} />
              <span className={`text-[11px] font-semibold uppercase tracking-wide ${NODE_META[g.node].text}`}>{NODE_META[g.node].label}</span>
              <span className="h-px flex-1 bg-slate-100" />
            </div>
            {g.steps.map((s) => {
              const live = !seen.current.has(s.id)
              seen.current.add(s.id)
              return <StepRow key={s.id} step={s} live={live} />
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

