'use client'

import { formatPaise, type Outcome, type RunState } from '@/lib/run'
import { Icon, NODE_META } from './meta'

const STATUS_STYLE: Record<Outcome['status'], string> = {
  RESOLVED: 'bg-emerald-100 text-emerald-800',
  ACTIONED: 'bg-sky-100 text-sky-800',
  CLOSED: 'bg-slate-100 text-slate-700',
  MONITORING: 'bg-amber-100 text-amber-800',
  AWAITING_APPROVAL: 'bg-amber-100 text-amber-800',
  ESCALATED: 'bg-rose-100 text-rose-800',
}

const ACTION_STATE: Record<string, string> = {
  done: 'bg-emerald-100 text-emerald-700',
  proposed: 'bg-amber-100 text-amber-700',
  scheduled: 'bg-sky-100 text-sky-700',
  cancelled: 'bg-slate-100 text-slate-500 line-through',
}

const BAND: Record<string, string> = { LOW: 'text-emerald-600', MEDIUM: 'text-amber-600', HIGH: 'text-rose-600' }

function Row({ k, v, mono }: { k: string; v: React.ReactNode; mono?: boolean }) {
  return (
    <div className="flex items-start justify-between gap-3 py-1.5">
      <dt className="text-[11px] font-medium uppercase tracking-wide text-slate-400">{k}</dt>
      <dd className={`text-right text-[13px] text-slate-800 ${mono ? 'font-mono text-[12px]' : ''}`}>{v}</dd>
    </div>
  )
}

export default function OutcomePanel({ run, deciding, onDecide }: {
  run: RunState
  deciding: boolean
  onDecide: (approve: boolean) => void
}) {
  const o = run.outcome
  const route = (['investigator', 'policy', 'resolver', 'human'] as const).filter((n) =>
    ['running', 'done', 'waiting'].includes(run.nodes[n].status),
  )

  if (run.phase === 'idle') {
    return (
      <div className="flex h-full flex-col justify-center gap-3 p-6 text-sm text-slate-500">
        <h3 className="text-sm font-semibold text-slate-900">How the squad works</h3>
        <p>The <b className="text-violet-700">Master Orchestrator</b> reads the complaint, but never trusts it. It sends the case to the <b className="text-sky-700">Investigator</b> for evidence first, then routes on what the records show.</p>
        <p><b className="text-amber-700">Policy</b> applies RBI rules and computes what the bank owes. <b className="text-teal-700">Resolver</b> scores fraud risk, prepares actions and executes them if they're within limits; otherwise it asks a <b className="text-rose-700">human</b>.</p>
        <p>Each case takes a different route. Agents that aren't needed are skipped.</p>
      </div>
    )
  }

  return (
    <div className="flex h-full flex-col overflow-y-auto">
      <div className="border-b border-slate-100 px-5 py-3">
        <h3 className="text-sm font-semibold text-slate-900">{o ? 'Outcome' : 'Run summary'}</h3>
      </div>

      {o ? (
        <div className="step-in space-y-4 p-5">
          <div>
            <span className={`inline-block rounded-full px-2.5 py-0.5 text-[11px] font-bold tracking-wide ${STATUS_STYLE[o.status]}`}>
              {o.status.replace('_', ' ')}
            </span>
            <h4 className="mt-2 text-lg font-bold leading-snug text-slate-900">{o.headline}</h4>
            <p className="mt-1 text-[13px] leading-relaxed text-slate-600">{o.summary}</p>
          </div>

          {o.status === 'AWAITING_APPROVAL' && (
            <div className="rounded-xl border-2 border-amber-300 bg-amber-50 p-3">
              <p className="text-[12px] font-medium text-amber-900">Nothing has been executed. Review the prepared actions below.</p>
              <div className="mt-2 flex gap-2">
                <button
                  disabled={deciding}
                  onClick={() => onDecide(true)}
                  className="flex-1 rounded-lg bg-emerald-600 px-3 py-2 text-sm font-semibold text-white hover:bg-emerald-700 disabled:opacity-50"
                >
                  Approve & execute
                </button>
                <button
                  disabled={deciding}
                  onClick={() => onDecide(false)}
                  className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50"
                >
                  Reject
                </button>
              </div>
            </div>
          )}

          <dl className="divide-y divide-slate-100 rounded-xl border border-slate-200 px-3">
            <Row k="Category" v={o.category} />
            {o.risk_band && (
              <Row k="Fraud risk" v={<span className={`font-semibold ${BAND[o.risk_band]}`}>{o.risk_band} · {o.risk_score}/100</span>} />
            )}
            <Row k="Paid to customer" v={<span className="font-semibold">{formatPaise(o.payout_paise)}</span>} />
            <Row
              k="Route"
              v={
                <span className="flex flex-wrap justify-end gap-1">
                  {route.map((n) => (
                    <span key={n} className={`rounded px-1.5 py-0.5 text-[11px] font-medium ${NODE_META[n].chip}`}>{NODE_META[n].label}</span>
                  ))}
                </span>
              }
            />
          </dl>

          <div>
            <h5 className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Actions</h5>
            <ul className="space-y-1.5">
              {o.actions.map((a) => (
                <li key={a.label} className="rounded-lg border border-slate-200 px-3 py-2">
                  <div className="flex items-start gap-2">
                    <span className="flex-1 text-[13px] text-slate-800">{a.label}</span>
                    {a.kind === 'credit' && <span className="text-[13px] font-semibold text-emerald-700">{formatPaise(a.amount_paise)}</span>}
                    <span className={`rounded px-1.5 py-0.5 text-[10px] font-bold uppercase ${ACTION_STATE[a.state]}`}>{a.state}</span>
                  </div>
                  {a.ref && <div className="mt-0.5 font-mono text-[11px] text-slate-400">ref {a.ref}</div>}
                </li>
              ))}
            </ul>
          </div>

          <div>
            <h5 className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Reply to customer</h5>
            <p className="whitespace-pre-line rounded-xl bg-indigo-50 p-3 text-[12.5px] leading-relaxed text-indigo-950">{o.customer_message}</p>
          </div>

          {o.citation && (
            <p className="flex gap-1.5 text-[11px] leading-relaxed text-slate-500">
              <Icon name="rule" className="mt-0.5 h-3.5 w-3.5 shrink-0" /> {o.citation}
            </p>
          )}
        </div>
      ) : (
        <dl className="divide-y divide-slate-100 px-5 py-2">
          <Row k="Run ID" v={run.runId} mono />
          <Row k="Status" v={<span className="font-semibold text-violet-700">{run.phase === 'error' ? 'Failed' : 'Running'}</span>} />
          <Row k="Customer" v={run.customer} />
          <Row k="UTR" v={run.utr} mono />
          <Row k="Amount" v={run.amount} />
          <Row k="Tool calls" v={run.steps.filter((s) => s.kind === 'tool').length} />
          <Row
            k="Route so far"
            v={
              <span className="flex flex-wrap justify-end gap-1">
                {route.length === 0 ? '—' : route.map((n) => (
                  <span key={n} className={`rounded px-1.5 py-0.5 text-[11px] font-medium ${NODE_META[n].chip}`}>{NODE_META[n].label}</span>
                ))}
              </span>
            }
          />
          {run.error && <Row k="Error" v={<span className="text-rose-600">{run.error}</span>} />}
        </dl>
      )}
    </div>
  )
}

'use client'

import { useEffect, useReducer, useRef, useState } from 'react'
import ActivityFeed from '@/components/ActivityFeed'
import { Icon } from '@/components/meta'
import OutcomePanel from '@/components/OutcomePanel'
import RunGraph from '@/components/RunGraph'
import { API_URL, initialRunState, reduceRun, streamEvents, type NodeId, type Scenario } from '@/lib/run'

const PACES = [
  { id: 'slow', label: 'Slow-mo' },
  { id: 'normal', label: 'Normal' },
  { id: 'fast', label: 'Fast' },
] as const

export default function Home() {
  const [scenarios, setScenarios] = useState<Scenario[]>([])
  const [loadError, setLoadError] = useState<string | null>(null)
  const [selectedId, setSelectedId] = useState<string>('rahul')
  const [complaint, setComplaint] = useState('')
  const [pace, setPace] = useState<(typeof PACES)[number]['id']>('normal')
  const [run, dispatch] = useReducer(reduceRun, undefined, initialRunState)
  const [filter, setFilter] = useState<NodeId | null>(null)
  const [deciding, setDeciding] = useState(false)
  const [now, setNow] = useState(0)
  const startedAt = useRef(0)
  const abort = useRef<AbortController | null>(null)

  useEffect(() => {
    fetch(`${API_URL}/api/scenarios`)
      .then((r) => r.json())
      .then((list: Scenario[]) => {
        setScenarios(list)
        setComplaint(list.find((s) => s.id === 'rahul')?.complaint ?? '')
      })
      .catch(() => setLoadError(`Can't reach the agent API at ${API_URL}. Is the backend running?`))
  }, [])

  useEffect(() => {
    if (run.phase !== 'running') return
    const id = setInterval(() => setNow(performance.now()), 100)
    return () => clearInterval(id)
  }, [run.phase])

  const scenario = scenarios.find((s) => s.id === selectedId)
  const running = run.phase === 'running'

  function pick(s: Scenario) {
    if (running) return
    setSelectedId(s.id)
    setComplaint(s.complaint)
    setFilter(null)
    dispatch({ type: 'reset', t: 0 })
  }

  async function consume(path: string, body: unknown) {
    abort.current?.abort()
    const ctrl = new AbortController()
    abort.current = ctrl
    try {
      await streamEvents(path, body, dispatch, ctrl.signal)
    } catch (e) {
      if (!ctrl.signal.aborted) dispatch({ type: 'run_failed', t: 0, error: (e as Error).message })
    }
  }

  async function start() {
    setFilter(null)
    startedAt.current = performance.now()
    setNow(startedAt.current)
    dispatch({ type: 'reset', t: 0 })
    await consume('/api/runs', { scenario_id: selectedId, complaint, pace })
  }

  async function decide(approve: boolean) {
    if (!run.runId) return
    setDeciding(true)
    dispatch({ type: 'resume', t: 0 })
    await consume(`/api/runs/${run.runId}/decision`, { approve })
    setDeciding(false)
  }

  const elapsed = running ? Math.max(run.elapsedMs, now - startedAt.current) : run.elapsedMs
  const statusLabel =
    run.phase === 'idle' ? 'Ready' : running ? 'Running' : run.phase === 'error' ? 'Failed' : run.outcome?.status.replace('_', ' ')
  const approvals =
    run.nodes.human.status === 'waiting' ? 'Waiting on reviewer'
      : run.nodes.human.status === 'done' ? 'Reviewed'
      : run.nodes.human.status === 'skipped' ? 'Not needed' : '—'

  return (
    <div className="flex min-h-screen flex-col lg:flex-row">
      {/* Sidebar */}
      <aside className="flex w-full shrink-0 flex-col border-b border-slate-200 bg-white lg:sticky lg:top-0 lg:h-screen lg:w-[340px] lg:border-b-0 lg:border-r">
        <div className="flex items-center gap-2.5 border-b border-slate-100 px-5 py-4">
          <span className="grid h-8 w-8 place-items-center rounded-lg bg-gradient-to-br from-violet-600 to-indigo-600 text-white">
            <Icon name="orchestrator" className="h-4 w-4" />
          </span>
          <div>
            <div className="text-[15px] font-bold leading-tight text-slate-900">DisputePro</div>
            <div className="text-[11px] text-slate-500">UPI dispute resolution squad</div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-4">
          <h2 className="mb-2 px-1 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Cases</h2>
          {loadError && <p className="rounded-lg bg-rose-50 p-3 text-xs text-rose-700">{loadError}</p>}
          <div className="space-y-1.5">
            {scenarios.map((s) => (
              <button
                key={s.id}
                onClick={() => pick(s)}
                disabled={running}
                className={`w-full rounded-xl border px-3 py-2.5 text-left transition disabled:cursor-not-allowed ${
                  s.id === selectedId ? 'border-indigo-300 bg-indigo-50/70 shadow-sm' : 'border-transparent hover:bg-slate-50'
                }`}
              >
                <div className="flex items-center justify-between gap-2">
                  <span className="text-[13px] font-semibold text-slate-900">{s.customer}</span>
                  <span className="text-[12px] font-medium text-slate-500">{s.amount}</span>
                </div>
                <div className="text-[12px] text-slate-500">{s.label}</div>
              </button>
            ))}
          </div>

          <h2 className="mb-2 mt-5 px-1 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Complaint</h2>
          <textarea
            value={complaint}
            onChange={(e) => setComplaint(e.target.value)}
            disabled={running}
            rows={5}
            className="w-full resize-none rounded-xl border border-slate-200 bg-slate-50 p-3 text-[13px] leading-relaxed text-slate-800 focus:border-indigo-300 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-100"
          />
          {scenario && <p className="mt-1 px-1 font-mono text-[11px] text-slate-400">UTR {scenario.utr}</p>}
          <p className="mt-1 px-1 text-[11px] text-slate-400">Edit the text. The orchestrator classifies the claim, then checks it against the records.</p>
        </div>

        <div className="space-y-3 border-t border-slate-100 p-4">
          <div className="flex rounded-lg bg-slate-100 p-0.5 text-[12px] font-medium">
            {PACES.map((p) => (
              <button
                key={p.id}
                onClick={() => setPace(p.id)}
                disabled={running}
                className={`flex-1 rounded-md py-1.5 ${pace === p.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}
              >
                {p.label}
              </button>
            ))}
          </div>
          <button
            onClick={start}
            disabled={running || deciding || !scenario || !complaint.trim()}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 py-3 text-sm font-semibold text-white shadow-md shadow-indigo-200 transition hover:brightness-110 disabled:opacity-50"
          >
            {running ? (
              <>
                <span className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" /> Agents working…
              </>
            ) : (
              <>
                <Icon name="play" className="h-4 w-4" /> {run.phase === 'idle' ? 'Run agents' : 'Run again'}
              </>
            )}
          </button>
        </div>
      </aside>

      {/* Main */}
      <main className="min-w-0 flex-1 space-y-4 p-4 lg:p-6">
        <header className="rounded-2xl border border-slate-200 bg-white">
          <div className="flex flex-wrap items-start gap-3 px-5 pt-4">
            <span className={`mt-0.5 grid h-9 w-9 place-items-center rounded-full ${
              running ? 'bg-violet-100 text-violet-700' : run.phase === 'idle' ? 'bg-slate-100 text-slate-500' : 'bg-emerald-100 text-emerald-700'
            }`}>
              {running ? <span className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" /> : <Icon name={run.phase === 'idle' ? 'play' : 'check'} />}
            </span>
            <div className="min-w-0 flex-1">
              <h1 className="text-xl font-bold text-slate-900">
                {scenario ? `${scenario.customer} · ${scenario.label}` : 'UPI Dispute Resolution Squad'}
              </h1>
              <p className="text-[13px] text-slate-500">
                Master Orchestrator → Investigator · Policy · Resolver
                {run.runId && <span className="ml-2 font-mono text-[12px] text-slate-400">#{run.runId.slice(4)}</span>}
              </p>
            </div>
            {running && (
              <span className="flex items-center gap-1.5 rounded-full bg-violet-50 px-2.5 py-1 text-[12px] font-medium text-violet-700">
                <span className="relative flex h-2 w-2">
                  <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-violet-400" />
                  <span className="relative inline-flex h-2 w-2 rounded-full bg-violet-600" />
                </span>
                Live
              </span>
            )}
          </div>
          <div className="mt-4 grid grid-cols-2 border-t border-slate-100 sm:grid-cols-5">
            {[
              ['Started by', 'Customer complaint'],
              ['Status', statusLabel],
              ['Duration', run.phase === 'idle' ? '—' : `${(elapsed / 1000).toFixed(1)}s`],
              ['Steps', run.steps.length || '—'],
              ['Approvals', approvals],
            ].map(([k, v]) => (
              <div key={k as string} className="border-r border-slate-100 px-5 py-3 last:border-r-0">
                <div className="text-[11px] text-slate-400">{k}</div>
                <div className={`text-[14px] font-semibold ${k === 'Status' && run.phase === 'done' ? 'text-emerald-600' : 'text-slate-900'}`}>{v}</div>
              </div>
            ))}
          </div>
        </header>

        <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white">
          <div className="flex items-center gap-3 border-b border-slate-100 px-5 py-3">
            <h2 className="text-sm font-semibold text-slate-900">Run graph</h2>
            <span className="text-[12px] text-slate-400">7 nodes · routes on evidence, not on the claim</span>
          </div>
          <RunGraph run={run} selected={filter} onSelect={(id) => setFilter((f) => (f === id ? null : id))} />
        </section>

        <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="h-[560px] overflow-hidden rounded-2xl border border-slate-200 bg-white">
            <ActivityFeed run={run} filter={filter} onClearFilter={() => setFilter(null)} />
          </section>
          <section className="h-[560px] overflow-hidden rounded-2xl border border-slate-200 bg-white">
            <OutcomePanel run={run} deciding={deciding} onDecide={decide} />
          </section>
        </div>
      </main>
    </div>
  )
}

import type { Metadata } from 'next'
import './globals.css'

export const metadata: Metadata = {
  title: 'DisputePro — UPI Dispute Resolution Squad',
  description: 'Watch a master orchestrator and three agents resolve UPI disputes step by step.',
}

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body className="bg-slate-50 text-slate-900 antialiased">{children}</body>
    </html>
  )
}

@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

/* Active edge: dashes flow toward the target */
.edge-flow {
  animation: edge-flow 0.6s linear infinite;
}
@keyframes edge-flow {
  to {
    stroke-dashoffset: -14;
  }
}

/* Taken edge: line draws itself in */
.edge-draw {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: edge-draw 0.7s ease-out forwards;
}
@keyframes edge-draw {
  to {
    stroke-dashoffset: 0;
  }
}

.node-glow {
  animation: node-glow 1.6s ease-in-out infinite;
}
