function ends(d: string) {
  const n = d.match(/-?\d+(\.\d+)?/g)!.map(Number)
  return [n[0], n[1], n[n.length - 2], n[n.length - 1]]
}

function Packets({ pathId, color, dur = 1.2 }: { pathId: string; color: string; dur?: number }) {
  return (
    <>
      {[0, dur / 3, (2 * dur) / 3].map((begin) => (
        <circle key={begin} r={4} fill={color}>
          <animateMotion dur={`${dur}s`} begin={`${begin}s`} repeatCount="indefinite">
            <mpath href={`#${pathId}`} />
          </animateMotion>
        </circle>
      ))}
    </>
  )
}

function FlowEdge({ id, state }: { id: string; state: EdgeState }) {
  const d = FLOW_PATHS[id]
  const [x1, y1, x2, y2] = ends(d)
  const pid = `flow-${id.replace('>', '-')}`
  const port = state === 'taken' ? '#10b981' : state === 'active' ? '#8b5cf6' : '#cbd5e1'
  return (
    <g>
      <path id={pid} d={d} fill="none" stroke="#e2e8f0" strokeWidth={2} />
      {state === 'skipped' && <path d={d} fill="none" stroke="#94a3b8" strokeWidth={2} strokeDasharray="2 6" strokeLinecap="round" />}
      {state === 'active' && (
        <>
          <path d={d} fill="none" stroke="#a78bfa" strokeWidth={2.5} strokeDasharray="7 7" className="edge-flow" />
          <Packets pathId={pid} color="#7c3aed" />
        </>
      )}
      {state === 'taken' && <path d={d} fill="none" stroke="#10b981" strokeWidth={2.5} pathLength={1} className="edge-draw" />}
      <circle cx={x1} cy={y1} r={3.5} fill="white" stroke={port} strokeWidth={2} />
      <circle cx={x2} cy={y2} r={3.5} fill="white" stroke={port} strokeWidth={2} />
    </g>
  )
}

function PartyEdge({ agent, party, calls, inflight }: { agent: NodeId; party: PartyId; calls: number; inflight: number }) {
  const a = NODE_BOX[agent]
  const p = PARTY_BOX[party]
  const ay = a.y + a.h / 2
  const py = p.y + p.h / 2
  const x1 = a.x + a.w
  const x2 = p.x
  const d = `M${x1} ${ay} C${x1 + 90} ${ay} ${x2 - 90} ${py} ${x2} ${py}`
  const pid = `call-${agent}-${party}`
  const stroke = NODE_META[agent].stroke
  return (
    <g>
      <path id={pid} d={d} fill="none" stroke={stroke} strokeOpacity={inflight ? 0.9 : 0.35} strokeWidth={inflight ? 2.5 : 1.6}
        strokeDasharray={inflight ? '6 6' : undefined} className={inflight ? 'edge-flow' : 'edge-draw'} pathLength={inflight ? undefined : 1} />
      {inflight > 0 && <Packets pathId={pid} color={stroke} dur={0.9} />}
      <g transform={`translate(${x2 - 16} ${py - 9})`}>
        <rect width={20} height={18} rx={9} fill="white" stroke={stroke} strokeOpacity={0.6} />
        <text x={10} y={12.5} textAnchor="middle" fontSize={10} fontWeight={700} fill={stroke}>{calls}</text>
      </g>
    </g>
  )
}

const STATUS_CHIP: Record<NodeState['status'], { text: string; cls: string }> = {
  idle: { text: 'Not reached', cls: 'bg-slate-100 text-slate-500' },
  running: { text: 'Working', cls: 'bg-violet-100 text-violet-700' },
  done: { text: 'Done', cls: 'bg-emerald-100 text-emerald-700' },
  skipped: { text: 'Skipped', cls: 'bg-slate-100 text-slate-400' },
  waiting: { text: 'Waiting', cls: 'bg-amber-100 text-amber-700' },
}

function AgentCard({ id, state, selected, onSelect, steps, tokens, brain }: {
  id: NodeId
  state: NodeState
