export default function FlowGraph({ run, selected, onSelect }: {
  run: RunState
  selected: string | null
  onSelect: (key: string) => void
}) {
  const counts = run.steps.reduce<Record<string, number>>((acc, s) => ((acc[s.node] = (acc[s.node] ?? 0) + 1), acc), {})
  const links = partyLinks(run.steps)
  const partyTotals = PARTY_IDS.reduce<Record<string, { calls: number; inflight: number }>>((acc, p) => {
    const ls = links.filter((l) => l.party === p)
    acc[p] = { calls: ls.reduce((n, l) => n + l.calls, 0), inflight: ls.reduce((n, l) => n + l.inflight, 0) }
    return acc
  }, {})
  return (
    <div className="overflow-x-auto">
      <svg viewBox={`0 0 ${VIEW_W} ${VIEW_H}`} className="block w-full min-w-[760px]" role="img" aria-label="Live agent workflow">
        <defs>
          <pattern id="dots" width="22" height="22" patternUnits="userSpaceOnUse">
            <circle cx="1" cy="1" r="1" fill="#e2e8f0" />
          </pattern>
        </defs>
        <rect width={VIEW_W} height={VIEW_H} fill="url(#dots)" />
        <text x={110} y={VIEW_H - 2} textAnchor="middle" className="fill-slate-300 text-[10px] font-semibold uppercase tracking-widest">Control</text>
        <text x={408} y={VIEW_H - 2} textAnchor="middle" className="fill-slate-300 text-[10px] font-semibold uppercase tracking-widest">AI agents</text>
        <text x={825} y={VIEW_H - 2} textAnchor="middle" className="fill-slate-300 text-[10px] font-semibold uppercase tracking-widest">Counterparties (live APIs)</text>
        {links.map((l) => <PartyEdge key={`${l.agent}-${l.party}`} {...l} />)}
        {Object.keys(FLOW_PATHS).map((id) => <FlowEdge key={id} id={id} state={run.edges[id] ?? 'idle'} />)}
        {(Object.keys(NODE_BOX) as NodeId[]).map((id) => (
          <AgentCard key={id} id={id} state={run.nodes[id]} selected={selected === id} onSelect={() => onSelect(id)}
            steps={counts[id] ?? 0} tokens={run.usage[id] ? run.usage[id].input_tokens + run.usage[id].output_tokens : undefined}
            brain={run.brainLabel} />
        ))}
        {PARTY_IDS.map((p) => (
          <PartyCard key={p} id={p} {...partyTotals[p]} selected={selected === p} onSelect={() => onSelect(p)} />
        ))}
      </svg>
    </div>
  )
}

