import { useEffect, useRef, useState } from 'react'
import type { NodeId, PartyId, RunState, Step } from '@/lib/run'
import { Icon, NODE_META, PARTY_META } from '../meta'

function Typewriter({ text, since }: { text: string; since: number }) {
  const msPerChar = Math.max(3, Math.min(14, 900 / text.length))
  const reveal = () => Math.min(text.length, Math.floor((Date.now() - since) / msPerChar))
  const [n, setN] = useState(reveal)
  useEffect(() => {
    if (n >= text.length) return
    const id = setInterval(() => {
      const next = reveal()
      setN(next)
      if (next >= text.length) clearInterval(id)
    }, 30)
    return () => clearInterval(id)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, since])
  return (
    <>
      {text.slice(0, n)}
      {n < text.length && <span className="ml-0.5 inline-block h-3 w-1.5 animate-pulse bg-slate-400 align-middle" />}
    </>
  )
}

const TONE: Record<Step['status'], string> = {
  running: 'text-violet-700', ok: 'text-emerald-700', warn: 'text-amber-700', bad: 'text-rose-700', info: 'text-slate-700',
}
const BORDER: Record<Step['status'], string> = {
  running: 'border-violet-300', ok: 'border-emerald-400', warn: 'border-amber-400', bad: 'border-rose-400', info: 'border-slate-300',
}

function CallRow({ step }: { step: Step }) {
  const [open, setOpen] = useState(false)
  const p = step.party ? PARTY_META[step.party] : null
  const code = step.http?.status
  return (
    <div className="step-in rounded-lg border border-slate-200 bg-white px-3 py-2 shadow-sm">
      <div className="flex items-center gap-2">
        <span className="grid h-5 w-5 shrink-0 place-items-center rounded bg-slate-900 text-white">
          <Icon name={step.party ?? 'tool'} className="h-3 w-3" />
        </span>
        <span className="shrink-0 text-[11px] font-semibold text-slate-500">{p?.short}</span>
        <code className="min-w-0 flex-1 truncate text-[11.5px] text-slate-800">
          <span className={step.http?.method === 'POST' ? 'font-bold text-orange-600' : 'font-bold text-sky-700'}>{step.http?.method}</span>{' '}
          {step.http?.path}
        </code>
        {step.status === 'running' ? (
          <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-violet-500 border-t-transparent" />
        ) : (
          <span className={`font-mono text-[10.5px] font-semibold ${code && code < 400 ? 'text-emerald-700' : 'text-rose-700'}`}>
            {code} · {step.http?.latency_ms}ms
          </span>
        )}
      </div>
      <div className="mt-1 flex items-start gap-2 pl-7">
        <span className="text-[11px] text-slate-400">{step.title}</span>
      </div>
      {step.status !== 'running' && (
        <div className="flex items-start gap-2 pl-7">
          <span className={`flex-1 text-[12px] ${TONE[step.status]}`}>→ {step.result}</span>
          <button onClick={() => setOpen((v) => !v)} className="text-[11px] font-medium text-indigo-600 hover:underline">
            {open ? 'hide' : 'payload'}
          </button>
        </div>
      )}
      {open && (
        <div className="mt-2 grid gap-2 md:grid-cols-2">
          {step.http?.body ? (
            <pre className="max-h-56 overflow-auto rounded bg-slate-900 p-2 text-[10.5px] leading-relaxed text-amber-100">
              {'// request\n' + JSON.stringify(step.http.body, null, 2)}
            </pre>
          ) : null}
          <pre className={`max-h-56 overflow-auto rounded bg-slate-900 p-2 text-[10.5px] leading-relaxed text-slate-100 ${step.http?.body ? '' : 'md:col-span-2'}`}>
            {'// response\n' + JSON.stringify(step.data, null, 2)}
          </pre>
        </div>
