  )
}

function StepRow({ step, brain }: { step: Step; brain?: string }) {
  const time = <span className="shrink-0 font-mono text-[10px] text-slate-400">+{(step.t / 1000).toFixed(1)}s</span>
  if (step.kind === 'call') return <CallRow step={step} />
  if (step.kind === 'check' && (step.detail?.length ?? 0) <= 8) {
    return (
      <div className="step-in flex items-center gap-2 px-1 py-0.5 text-[12px]">
        <span className={step.status === 'bad' ? 'text-rose-600' : 'text-emerald-600'}>
          <Icon name={step.status === 'bad' ? 'x' : 'check'} className="h-3.5 w-3.5" />
        </span>
        <span className="flex-1 text-slate-700">{step.title}</span>
        <span className={`font-mono text-[11px] ${TONE[step.status]}`}>{step.detail}</span>
        {time}
      </div>
    )
  }
  if (step.kind === 'draft') {
    return (
      <div className="step-in rounded-lg border border-indigo-200 bg-indigo-50/60 px-3 py-2">
        <div className="mb-1 flex items-center gap-2 text-[12px] font-semibold text-indigo-800">
          <Icon name="draft" className="h-3.5 w-3.5" /> {step.title}
          <span className="ml-auto">{time}</span>
        </div>
        <p className="whitespace-pre-line text-[12px] leading-relaxed text-indigo-950">
          <Typewriter text={step.detail ?? ''} since={step.arrivedAt} />
        </p>
      </div>
    )
  }
  if (step.kind === 'think') {
    const llm = brain && brain !== 'rules'
    return (
      <div className="step-in flex gap-2 rounded-lg bg-violet-50/60 px-2.5 py-1.5">
        <span className="mt-0.5 text-violet-500"><Icon name="think" className="h-3.5 w-3.5" /></span>
        <div className="min-w-0 flex-1">
          <div className="text-[10.5px] font-semibold uppercase tracking-wide text-violet-600">{llm ? 'Model reasoning' : step.title}</div>
          <div className="whitespace-pre-line text-[12px] italic leading-relaxed text-slate-700">
            <Typewriter text={step.detail ?? step.title} since={step.arrivedAt} />
          </div>
        </div>
        {time}
      </div>
    )
  }
  const emph = ['decision', 'finding', 'guard'].includes(step.kind)
  return (
    <div className={`step-in flex gap-2 ${emph ? `rounded-r-lg border-l-[3px] bg-white py-1.5 pl-2.5 pr-2 shadow-sm ${BORDER[step.status]}` : 'px-1 py-0.5'}`}>
      <span className={`mt-0.5 ${emph ? TONE[step.status] : 'text-slate-400'}`}><Icon name={step.kind} className="h-3.5 w-3.5" /></span>
      <div className="min-w-0 flex-1">
        <div className={`text-[12.5px] ${emph ? `font-semibold ${TONE[step.status]}` : 'font-medium text-slate-800'}`}>{step.title}</div>
        {step.detail && (
          <div className="whitespace-pre-line text-[12px] leading-relaxed text-slate-600">
            <Typewriter text={step.detail} since={step.arrivedAt} />
          </div>
        )}
      </div>
      {time}
    </div>
  )
}

export default function AgentLog({ run, filter, onClearFilter }: { run: RunState; filter: string | null; onClearFilter: () => void }) {
  const scroller = useRef<HTMLDivElement>(null)
  const content = useRef<HTMLDivElement>(null)
  const follow = useRef(true)
  const steps = !filter ? run.steps : run.steps.filter((s) => s.node === filter || s.party === filter)

  useEffect(() => {
    if (run.phase === 'idle') follow.current = true
  }, [run.phase])

  useEffect(() => {
    const el = scroller.current
    const inner = content.current
    if (!el || !inner) return
    const ro = new ResizeObserver(() => {
      if (follow.current) el.scrollTop = el.scrollHeight
    })
    ro.observe(inner)
    return () => ro.disconnect()
  }, [])

  const groups: { node: NodeId; steps: Step[] }[] = []
  for (const s of steps) {
    const last = groups[groups.length - 1]
    if (last && last.node === s.node) last.steps.push(s)
    else groups.push({ node: s.node, steps: [s] })
  }
  const filterLabel = filter ? (NODE_META[filter as NodeId]?.label ?? PARTY_META[filter as PartyId]?.label) : null

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center gap-2 border-b border-slate-100 px-4 py-2.5">
        <h3 className="text-sm font-semibold text-slate-900">Agent activity</h3>
        {run.phase === 'running' && (
          <span className="flex items-center gap-1.5 rounded-full bg-violet-50 px-2 py-0.5 text-[11px] font-medium text-violet-700">
            <span className="h-1.5 w-1.5 animate-ping rounded-full bg-violet-500" /> streaming
          </span>
        )}
        {filterLabel && (
          <button onClick={onClearFilter} className="rounded-full bg-indigo-50 px-2 py-0.5 text-[11px] font-medium text-indigo-700">
            {filterLabel} ✕
          </button>
        )}
        <span className="ml-auto font-mono text-[11px] text-slate-400">
          {steps.filter((s) => s.kind === 'call').length} API calls · {steps.length} steps
        </span>
      </div>
      <div ref={scroller} onScroll={(e) => {
        const el = e.currentTarget
        follow.current = el.scrollHeight - el.scrollTop - el.clientHeight < 40
      }} className="flex-1 overflow-y-auto bg-slate-50/50 px-4 py-3">
        <div ref={content} className="space-y-3">
          {steps.length === 0 && (
            <div className="grid place-items-center py-16 text-center text-sm text-slate-400">
              {run.phase === 'idle' ? 'Run the agents — every reasoning step, rule and API call to each party streams here.' : 'Nothing for this filter yet.'}
            </div>
          )}
          {groups.map((g, i) => (
            <div key={`${g.node}-${i}`} className="space-y-1.5">
              <div className="flex items-center gap-2 pt-1">
                <span className={`h-2 w-2 rounded-full ${NODE_META[g.node].dot}`} />
                <span className={`text-[11px] font-semibold uppercase tracking-wide ${NODE_META[g.node].text}`}>{NODE_META[g.node].label}</span>
                <span className="h-px flex-1 bg-slate-200" />
              </div>
              {g.steps.map((s) => <StepRow key={s.id} step={s} brain={run.brain} />)}
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

'use client'

import { PARTY_IDS, rs, type PartyId, type RunState, type Snapshot } from '@/lib/run'
import { Icon, NODE_META, PARTY_META } from '../meta'

function Fact({ k, before, now, mono }: { k: string; before?: string | number | null; now: React.ReactNode; mono?: boolean }) {
  const changed = before != null && String(before) !== String(now)
  return (
    <div className="flex items-baseline justify-between gap-3 py-0.5">
      <span className="text-[11px] text-slate-500">{k}</span>
      <span className={`text-right text-[12px] ${mono ? 'font-mono text-[11px]' : ''} ${changed ? 'font-semibold text-emerald-700' : 'text-slate-800'}`}>
        {changed && <span className="mr-1 font-normal text-slate-400 line-through">{before}</span>}
        {now}
      </span>
    </div>
  )
}

function Chip({ children, tone = 'slate' }: { children: React.ReactNode; tone?: 'slate' | 'green' | 'amber' | 'rose' }) {
  const cls = { slate: 'bg-slate-100 text-slate-700', green: 'bg-emerald-100 text-emerald-800', amber: 'bg-amber-100 text-amber-800', rose: 'bg-rose-100 text-rose-800' }[tone]
  return <span className={`step-in inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 font-mono text-[10.5px] font-semibold ${cls}`}>{children}</span>
}

function PartyState({ id, b, s }: { id: PartyId; b?: Snapshot | null; s?: Snapshot | null }) {
  if (!s) return null
  if (id === 'cbs') {
    const old = new Set(b?.cbs.postings.map((p) => p.id))
    const fresh = s.cbs.postings.filter((p) => !old.has(p.id))
    const blocked = s.cbs.blocked_vpas.filter((v) => !b?.cbs.blocked_vpas.includes(v))
    return (
      <div>
        <Fact k={`${s.cbs.name} balance`} before={b ? rs(b.cbs.balance_paise) : null} now={rs(s.cbs.balance_paise)} />
        {fresh.length > 0 && <div className="mt-1 flex flex-wrap gap-1">{fresh.map((p) => <Chip key={p.id} tone="green">+{rs(p.amount_paise)} {p.type.replace('_', ' ').toLowerCase()} · {p.id}</Chip>)}</div>}
        {blocked.map((v) => <div key={v} className="mt-1"><Chip tone="rose">blocked {v}</Chip></div>)}
      </div>
    )
  }
  if (id === 'npci') {
    const old = new Set(b?.npci.complaints.map((c) => c.id))
    const fresh = s.npci.complaints.filter((c) => !old.has(c.id))
    return (
      <div>
        <Fact k="Credit leg" now={s.npci.credit_leg} />
        <Fact k="Reversal leg" before={b?.npci.reversal_leg} now={s.npci.reversal_leg} />
        {fresh.length > 0 && <div className="mt-1 flex flex-wrap gap-1">{fresh.map((c) => <Chip key={c.id} tone={c.status === 'REJECTED' ? 'rose' : 'green'}>UDIR {c.type.replace('_', ' ').toLowerCase()} · {c.status}</Chip>)}</div>}
      </div>
    )
  }
  if (id === 'bene') {
    return (
      <div>
        <Fact k={s.bene.bank ?? 'Bank'} now={s.bene.holder_name ?? '—'} />
        <Fact k="Credit" now={s.bene.credit?.status === 'CREDITED' ? `credited · ${s.bene.credit.credit_ref}` : 'not credited'} mono />
        {(s.bene.lien_paise ?? 0) > 0 || (b?.bene.lien_paise ?? 0) > 0 ? (
          <Fact k="Lien (frozen)" before={b ? rs(b.bene.lien_paise ?? 0) : null} now={rs(s.bene.lien_paise ?? 0)} />
        ) : null}
      </div>
    )
  }
  if (id === 'acquirer') {
    const old = new Set(b?.acquirer.refunds.map((r) => r.id))
    const fresh = s.acquirer.refunds.filter((r) => !old.has(r.id))
    return fresh.length ? (
      <div className="flex flex-wrap gap-1">{fresh.map((r) => <Chip key={r.id} tone="green">refund {rs(r.amount_paise)} · {r.id}</Chip>)}</div>
    ) : null
  }
  const ours = s.ncrp.our_reports.filter((r) => !b?.ncrp.our_reports.some((o) => o.ack_no === r.ack_no))
  return (
    <div>
      <Fact k="Reports on payee" before={b?.ncrp.reports_on_payee} now={s.ncrp.reports_on_payee} />
      {ours.map((r) => <div key={r.ack_no} className="mt-1"><Chip tone="green">filed {r.ack_no}</Chip></div>)}
    </div>
  )
}

export default function PartiesPanel({ run, live, selected, onSelect }: {
  run: RunState
  live: Snapshot | null
  selected: string | null
  onSelect: (key: string) => void
}) {
  return (
    <div className="space-y-2.5">
      <div className="flex items-baseline justify-between px-1">
        <h3 className="text-sm font-semibold text-slate-900">Parties</h3>
        <span className="text-[11px] text-slate-400">live state · every call over HTTP</span>
      </div>
      {PARTY_IDS.map((p) => {
        const calls = run.steps.filter((s) => s.kind === 'call' && s.party === p)
        const inflight = calls.some((c) => c.status === 'running')
        const m = PARTY_META[p]
        return (
          <div key={p} onClick={() => onSelect(p)}
            className={`cursor-pointer rounded-xl border bg-white p-3 transition hover:shadow-sm ${
              inflight ? 'border-violet-300 node-glow' : selected === p ? 'border-indigo-300' : 'border-slate-200'
            } ${calls.length === 0 && run.phase !== 'idle' ? 'opacity-60' : ''}`}>
            <div className="flex items-center gap-2.5">
              <span className={`grid h-7 w-7 place-items-center rounded-lg ${calls.length ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-500'}`}>
                <Icon name={p} className="h-3.5 w-3.5" />
              </span>
              <div className="min-w-0 flex-1">
                <div className="truncate text-[13px] font-semibold text-slate-900">{m.label}</div>
                <div className="truncate text-[11px] text-slate-500">{m.role}</div>
              </div>
              {inflight ? (
                <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-violet-500 border-t-transparent" />
              ) : (
                <span className="text-[11px] font-semibold text-slate-500">{calls.length ? `${calls.length} calls` : run.phase === 'idle' ? '' : 'not needed'}</span>
              )}
            </div>
            {(live || run.before) && (
              <div className="mt-2 border-t border-slate-100 pt-2">
                <PartyState id={p} b={run.before} s={live ?? run.before} />
              </div>
            )}
            {calls.length > 0 && (
              <ul className="mt-2 space-y-1 border-t border-slate-100 pt-2">
                {calls.slice(-3).map((c) => (
                  <li key={c.id} className="step-in flex items-center gap-1.5 text-[11px]">
                    <span className={`h-1.5 w-1.5 shrink-0 rounded-full ${NODE_META[c.node].dot}`} title={NODE_META[c.node].label} />
                    <span className={`font-mono font-bold ${c.http?.method === 'POST' ? 'text-orange-600' : 'text-sky-700'}`}>{c.http?.method}</span>
                    <span className="min-w-0 flex-1 truncate text-slate-600">{c.status === 'running' ? c.title : c.result}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        )
      })}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { rs, type Outcome } from '@/lib/run'
import { Icon } from '../meta'

const STATUS: Record<Outcome['status'], { label: string; cls: string }> = {
  RESOLVED: { label: 'Resolved', cls: 'bg-emerald-100 text-emerald-800' },
  ACTIONED: { label: 'Actioned', cls: 'bg-sky-100 text-sky-800' },
  CLOSED: { label: 'Closed', cls: 'bg-slate-100 text-slate-700' },
  MONITORING: { label: 'Monitoring', cls: 'bg-amber-100 text-amber-800' },
  AWAITING_APPROVAL: { label: 'Awaiting approval', cls: 'bg-amber-100 text-amber-800' },
  ESCALATED: { label: 'Escalated', cls: 'bg-rose-100 text-rose-800' },
}
const STATE: Record<string, string> = {
  done: 'bg-emerald-100 text-emerald-700', proposed: 'bg-amber-100 text-amber-700',
  scheduled: 'bg-sky-100 text-sky-700', cancelled: 'bg-slate-100 text-slate-500 line-through',
}
const BAND: Record<string, string> = { LOW: 'text-emerald-600', MEDIUM: 'text-amber-600', HIGH: 'text-rose-600' }

const label = (t: string) => t.replace(/_/g, ' ').toLowerCase().replace(/^./, (c) => c.toUpperCase())

export default function OutcomeCard({ o, deciding, onDecide }: { o: Outcome; deciding: boolean; onDecide: (approve: boolean) => void }) {
  const [showEvidence, setShowEvidence] = useState(false)
  const tokens = Object.values(o.usage ?? {}).reduce((n, u) => n + u.input_tokens + u.output_tokens, 0)
  return (
    <div className="step-in space-y-3 rounded-2xl border-2 border-indigo-200 bg-white p-4 shadow-md">
      <div>
        <span className={`rounded-full px-2.5 py-0.5 text-[11px] font-bold uppercase tracking-wide ${STATUS[o.status].cls}`}>{STATUS[o.status].label}</span>
        <h3 className="mt-2 text-lg font-bold leading-snug text-slate-900">{o.headline}</h3>
        <p className="mt-1 text-[12.5px] leading-relaxed text-slate-600">{o.summary}</p>
      </div>

      {o.status === 'AWAITING_APPROVAL' && (
        <div className="rounded-xl border-2 border-amber-300 bg-amber-50 p-3">
          <p className="text-[12px] font-medium text-amber-900">Held: {o.human_reason}. Nothing has executed yet.</p>
          <div className="mt-2 flex gap-2">
            <button disabled={deciding} onClick={() => onDecide(true)}
              className="flex-1 rounded-lg bg-emerald-600 px-3 py-2 text-sm font-semibold text-white hover:bg-emerald-700 disabled:opacity-50">
              Approve & execute
            </button>
            <button disabled={deciding} onClick={() => onDecide(false)}
              className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50">
              Reject
            </button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-3 gap-2 text-center">
        <div className="rounded-lg bg-slate-50 p-2">
          <div className="text-[10px] uppercase tracking-wide text-slate-400">Paid to customer</div>
          <div className="text-[15px] font-bold text-slate-900">{rs(o.payout_paise)}</div>
        </div>
        <div className="rounded-lg bg-slate-50 p-2">
          <div className="text-[10px] uppercase tracking-wide text-slate-400">Fraud risk</div>
          <div className={`text-[15px] font-bold ${o.risk ? BAND[o.risk.band] : 'text-slate-400'}`}>{o.risk ? `${o.risk.band} ${o.risk.score}` : '—'}</div>
        </div>
        <div className="rounded-lg bg-slate-50 p-2">
          <div className="text-[10px] uppercase tracking-wide text-slate-400">Case type</div>
          <div className="truncate text-[12px] font-semibold text-slate-900" title={o.case_type}>{label(o.case_type)}</div>
        </div>
      </div>

      <div>
        <h4 className="mb-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Actions</h4>
        <ul className="space-y-1.5">
          {o.actions.map((a, i) => (
            <li key={i} className="rounded-lg border border-slate-200 px-2.5 py-1.5">
              <div className="flex items-center gap-2">
                <span className="flex-1 text-[12.5px] font-medium text-slate-800">{label(a.type)}</span>
                {a.amount_paise > 0 && <span className="text-[12px] font-semibold text-slate-700">{rs(a.amount_paise)}</span>}
                <span className={`rounded px-1.5 py-0.5 text-[9.5px] font-bold uppercase ${STATE[a.state]}`}>{a.state}</span>
              </div>
              <div className="text-[11px] text-slate-500">{a.note}{a.ref && <span className="ml-1 font-mono text-slate-400">· {a.ref}</span>}</div>
            </li>
          ))}
          {o.rejected.map((a, i) => (
            <li key={`r${i}`} className="rounded-lg border border-rose-200 bg-rose-50/50 px-2.5 py-1.5 text-[12px] text-rose-800">
              <Icon name="guard" className="mr-1 inline h-3 w-3" /> Blocked by guardrail: {label(a.type)} — {a.note}
            </li>
          ))}
        </ul>
      </div>

      {o.customer_message && (
        <div>
          <h4 className="mb-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Reply to customer</h4>
          <p className="rounded-xl bg-indigo-50 p-3 text-[12.5px] leading-relaxed text-indigo-950">{o.customer_message}</p>
        </div>
      )}

      <button onClick={() => setShowEvidence((v) => !v)} className="text-[12px] font-medium text-indigo-600 hover:underline">
        {showEvidence ? 'Hide' : 'Show'} evidence trail ({o.findings.evidence.length})
      </button>
      {showEvidence && (
        <ul className="space-y-1">
          {o.findings.evidence.map((e, i) => (
            <li key={i} className="text-[12px] text-slate-700"><b className="text-slate-900">{e.source}:</b> {e.fact}</li>
          ))}
          {o.ruling && <li className="text-[12px] text-slate-700"><b className="text-slate-900">Liability:</b> {o.ruling.liability}</li>}
        </ul>
      )}

      {o.citation && (
        <p className="flex gap-1.5 border-t border-slate-100 pt-2 text-[11px] leading-relaxed text-slate-500">
          <Icon name="rule" className="mt-0.5 h-3.5 w-3.5 shrink-0" /> {o.citation}
        </p>
      )}
      {tokens > 0 && <p className="text-[11px] text-slate-400">LLM usage: {tokens.toLocaleString()} tokens</p>}
    </div>
  )
}

'use client'

import Link from 'next/link'
import { useCallback, useEffect, useReducer, useRef, useState } from 'react'
import AgentLog from '@/components/console/AgentLog'
import FlowGraph from '@/components/console/FlowGraph'
import OutcomeCard from '@/components/console/OutcomeCard'
import PartiesPanel from '@/components/console/PartiesPanel'
import { Icon } from '@/components/meta'
import { API_URL, initialRunState, reduceRun, rs, streamEvents, type Case, type Meta, type Snapshot } from '@/lib/run'

const PACES = [
  { id: 'slow', label: 'Slow' },
  { id: 'normal', label: 'Normal' },
  { id: 'fast', label: 'Fast' },
] as const

type Txn = { utr: string; amount_paise: number; counterparty_name: string; counterparty_vpa: string; initiated_at: string; kind: string }
type Customer = { id: string; name: string }

export default function Console() {
  const [meta, setMeta] = useState<Meta | null>(null)
  const [cases, setCases] = useState<Case[]>([])
  const [apiError, setApiError] = useState<string | null>(null)
  const [selected, setSelected] = useState<string>('p2p-not-credited')
  const [complaint, setComplaint] = useState('')
  const [editing, setEditing] = useState(false)
  const [pace, setPace] = useState<(typeof PACES)[number]['id']>('normal')
  const [run, dispatch] = useReducer(reduceRun, undefined, initialRunState)
  const [filter, setFilter] = useState<string | null>(null)
  const [deciding, setDeciding] = useState(false)
  const [live, setLive] = useState<Snapshot | null>(null)
  const [customers, setCustomers] = useState<Customer[]>([])
  const [custom, setCustom] = useState<{ customer_id: string; utr: string; txns: Txn[] }>({ customer_id: '', utr: '', txns: [] })
  const [now, setNow] = useState(0)
  const startedAt = useRef(0)
  const abort = useRef<AbortController | null>(null)

  const isCustom = selected === 'custom'
  const kase = cases.find((c) => c.id === selected)
  const target = isCustom ? (custom.customer_id && custom.utr ? { customer_id: custom.customer_id, utr: custom.utr } : null) : kase
  const running = run.phase === 'running'

  const loadSnapshot = useCallback(async (customer_id: string, utr: string) => {
    const r = await fetch(`${API_URL}/sandbox/snapshot?customer_id=${customer_id}&utr=${utr}`)
    if (r.ok) setLive(await r.json())
  }, [])

  useEffect(() => {
    Promise.all([fetch(`${API_URL}/api/meta`).then((r) => r.json()), fetch(`${API_URL}/api/cases`).then((r) => r.json()),
      fetch(`${API_URL}/api/customers`).then((r) => r.json())])
      .then(([m, c, cu]) => {
        setMeta(m)
        setCases(c)
        setCustomers(cu)
        setComplaint(c[0]?.complaint ?? '')
      })
      .catch(() => setApiError(`Can't reach the DisputePro API at ${API_URL}.`))
  }, [])

  useEffect(() => {
    if (target && run.phase === 'idle') loadSnapshot(target.customer_id, target.utr)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selected, custom.utr, cases.length])

  const finishedPosts = run.steps.filter((s) => s.kind === 'call' && s.http?.method === 'POST' && s.status !== 'running').length
  useEffect(() => {
    if (finishedPosts && target) loadSnapshot(target.customer_id, target.utr)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [finishedPosts])

  useEffect(() => {
    if (run.outcome?.after) setLive(run.outcome.after)
  }, [run.outcome])

  useEffect(() => {
    if (!running) return
    const id = setInterval(() => setNow(performance.now()), 100)
    return () => clearInterval(id)
  }, [running])

  function pick(id: string) {
    if (running) return
    setSelected(id)
    setEditing(false)
    setFilter(null)
    dispatch({ type: 'reset', t: 0 })
    const c = cases.find((x) => x.id === id)
    setComplaint(c?.complaint ?? '')
    setLive(null)
  }

  async function pickCustomer(customer_id: string) {
    setCustom({ customer_id, utr: '', txns: [] })
    setLive(null)
    if (!customer_id) return
    const txns: Txn[] = await fetch(`${API_URL}/api/customers/${customer_id}/transactions`).then((r) => r.json())
    setCustom({ customer_id, utr: '', txns })
  }

  async function consume(path: string, body: unknown) {
    abort.current?.abort()
    const ctrl = new AbortController()
    abort.current = ctrl
    try {
      await streamEvents(path, body, dispatch, ctrl.signal)
    } catch (e) {
      if (!ctrl.signal.aborted) dispatch({ type: 'run_failed', t: 0, error: (e as Error).message })
    }
  }

  async function start() {
    setFilter(null)
    startedAt.current = performance.now()
    dispatch({ type: 'reset', t: 0 })
    const body = isCustom ? { customer_id: custom.customer_id, utr: custom.utr, complaint, pace } : { case_id: selected, complaint, pace }
    await consume('/api/runs', body)
  }

  async function decide(approve: boolean) {
    if (!run.runId) return
    setDeciding(true)
    dispatch({ type: 'resume', t: 0 })
    await consume(`/api/runs/${run.runId}/decision`, { approve })
    setDeciding(false)
  }

  async function resetSandbox() {
    await fetch(`${API_URL}/sandbox/reset`, { method: 'POST' })
    dispatch({ type: 'reset', t: 0 })
    setCustom((c) => ({ ...c, utr: '' }))
    if (target && !isCustom) loadSnapshot(target.customer_id, target.utr)
  }

  const elapsed = running ? Math.max(run.elapsedMs, now - startedAt.current) : run.elapsedMs
  const llm = meta && meta.brain !== 'rules'
  const customTxn = custom.txns.find((t) => t.utr === custom.utr)

  return (
    <div className="flex h-screen flex-col bg-slate-50">
      {/* Top bar */}
      <header className="flex shrink-0 flex-wrap items-center gap-3 border-b border-slate-200 bg-white px-4 py-2.5">
        <Link href="/" className="flex items-center gap-2">
          <span className="grid h-8 w-8 place-items-center rounded-lg bg-gradient-to-br from-violet-600 to-indigo-600 text-white">
            <Icon name="orchestrator" className="h-4 w-4" />
          </span>
          <span className="text-[15px] font-bold text-slate-900">DisputePro</span>
        </Link>
        <span className="hidden text-[13px] text-slate-400 sm:inline">/ UPI dispute desk · Sahyadri Bank (sandbox)</span>
        {meta && (
          <span title={meta.brain_label}
            className={`ml-2 flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold ${llm ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-800'}`}>
            <span className={`h-1.5 w-1.5 rounded-full ${llm ? 'bg-emerald-500' : 'bg-amber-500'}`} />
            Agent brain: {llm ? meta.brain_label : 'Rules engine · LLM not configured'}
          </span>
        )}
        <div className="ml-auto flex items-center gap-2">
          <div className="flex rounded-lg bg-slate-100 p-0.5 text-[12px] font-medium">
            {PACES.map((p) => (
              <button key={p.id} onClick={() => setPace(p.id)} disabled={running}
                className={`rounded-md px-2.5 py-1 ${pace === p.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}>{p.label}</button>
            ))}
          </div>
          <button onClick={resetSandbox} disabled={running} title="Restore all sandbox balances and records"
            className="flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-2.5 py-1.5 text-[12px] font-medium text-slate-600 hover:bg-slate-50 disabled:opacity-50">
            <Icon name="reset" className="h-3.5 w-3.5" /> Reset sandbox
          </button>
          <button onClick={start} disabled={running || deciding || !target || !complaint.trim()}
            className="flex items-center gap-2 rounded-lg bg-gradient-to-r from-violet-600 to-indigo-600 px-4 py-1.5 text-[13px] font-semibold text-white shadow-md shadow-indigo-200 hover:brightness-110 disabled:opacity-50">
            {running ? <><span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-white border-t-transparent" /> Agents working · {(elapsed / 1000).toFixed(1)}s</>
              : <><Icon name="play" className="h-3.5 w-3.5" /> {run.phase === 'idle' ? 'Run agents' : 'Run again'}</>}
          </button>
        </div>
      </header>

      {/* Case queue */}
      <nav className="flex shrink-0 gap-1.5 overflow-x-auto border-b border-slate-200 bg-white px-4 py-2">
        <span className="self-center pr-1 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Complaint queue</span>
        {cases.map((c) => (
          <button key={c.id} onClick={() => pick(c.id)} disabled={running}
            className={`shrink-0 rounded-lg border px-3 py-1.5 text-left transition disabled:cursor-not-allowed ${
              selected === c.id ? 'border-indigo-300 bg-indigo-50 shadow-sm' : 'border-slate-200 hover:bg-slate-50'}`}>
            <div className="text-[12px] font-semibold text-slate-900">{c.title}</div>
            <div className="text-[10.5px] text-slate-500">{c.customer_name} · {rs(c.amount_paise)} · {c.rule}</div>
          </button>
        ))}
        <button onClick={() => pick('custom')} disabled={running}
          className={`shrink-0 rounded-lg border border-dashed px-3 py-1.5 text-left ${isCustom ? 'border-indigo-400 bg-indigo-50' : 'border-slate-300 hover:bg-slate-50'}`}>
          <div className="text-[12px] font-semibold text-slate-900">+ New complaint</div>
          <div className="text-[10.5px] text-slate-500">any customer, any transaction</div>
        </button>
      </nav>
      {apiError && <div className="bg-rose-50 px-4 py-2 text-[12px] text-rose-700">{apiError}</div>}

      <div className="grid min-h-0 flex-1 grid-cols-1 lg:grid-cols-[minmax(0,1fr)_400px]">
        <main className="min-h-0 space-y-3 overflow-y-auto p-3 lg:p-4">
          {/* Case brief */}
          <section className="rounded-2xl border border-slate-200 bg-white px-4 py-3">
            {isCustom ? (
              <div className="grid gap-2 md:grid-cols-[180px_minmax(0,1fr)]">
                <select value={custom.customer_id} onChange={(e) => pickCustomer(e.target.value)} disabled={running}
                  className="rounded-lg border border-slate-200 bg-slate-50 px-2 py-1.5 text-[13px]">
                  <option value="">Choose customer…</option>
                  {customers.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
                <select value={custom.utr} onChange={(e) => setCustom((c) => ({ ...c, utr: e.target.value }))} disabled={running || !custom.txns.length}
                  className="min-w-0 rounded-lg border border-slate-200 bg-slate-50 px-2 py-1.5 text-[13px]">
                  <option value="">Choose the transaction being disputed…</option>
                  {custom.txns.map((t) => (
                    <option key={t.utr} value={t.utr}>{t.initiated_at.slice(0, 10)} · {rs(t.amount_paise)} → {t.counterparty_name} ({t.kind}) · {t.utr}</option>
                  ))}
                </select>
                <textarea value={complaint} onChange={(e) => setComplaint(e.target.value)} disabled={running} rows={2}
                  placeholder="What does the customer say happened?"
                  className="resize-none rounded-lg border border-slate-200 bg-slate-50 p-2 text-[13px] md:col-span-2" />
                {customTxn && <p className="text-[11px] text-slate-400 md:col-span-2">Agents get only the UTR and the complaint. They work out the case type themselves.</p>}
              </div>
            ) : kase && (
              <div className="flex flex-wrap items-start gap-3">
                <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-slate-100 text-[13px] font-bold text-slate-600">
                  {kase.customer_name.split(' ').map((w) => w[0]).join('')}
                </span>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="text-[14px] font-semibold text-slate-900">{kase.customer_name}</span>
                    <span className="rounded bg-slate-100 px-1.5 py-0.5 text-[10.5px] font-medium text-slate-600">{kase.category}</span>
                    <span className="font-mono text-[11px] text-slate-400">UTR {kase.utr}</span>
                  </div>
                  {editing ? (
                    <textarea value={complaint} onChange={(e) => setComplaint(e.target.value)} rows={2} autoFocus onBlur={() => setEditing(false)}
                      className="mt-1 w-full resize-none rounded-lg border border-indigo-200 bg-indigo-50/40 p-2 text-[13px]" />
                  ) : (
                    <button onClick={() => !running && setEditing(true)} className="mt-0.5 text-left text-[13px] italic leading-relaxed text-slate-600 hover:text-slate-900">
                      “{complaint}” <span className="not-italic text-[11px] text-indigo-500">edit</span>
                    </button>
                  )}
                </div>
                <div className="text-right">
                  <div className="text-[18px] font-bold text-slate-900">{rs(kase.amount_paise)}</div>
                  <div className="text-[11px] text-slate-500">{kase.rule}</div>
                </div>
              </div>
            )}
          </section>

