export const PARTY_STYLE: Record<PartyId, { name: string; chip: string; dot: string }> = {
  cbs: { name: 'Core banking', chip: 'bg-indigo-50 text-indigo-700 ring-indigo-200', dot: 'bg-indigo-500' },
