  )
}

function DeadlineBar({ start, deadline }: { start: string; deadline: string }) {
  const s = new Date(start).getTime()
  const d = new Date(deadline).getTime()
  const pct = Math.min(100, Math.max(2, ((Date.now() - s) / (d - s)) * 100))
  return (
    <div className="mt-3">
      <div className="relative h-2 rounded-full bg-slate-100">
        <div className="absolute inset-y-0 left-0 rounded-full bg-gradient-to-r from-emerald-400 to-emerald-500" style={{ width: `${pct}%` }} />
        <div className="absolute -top-1 h-4 w-1 rounded bg-emerald-700" style={{ left: `${pct}%` }} />
      </div>
      <div className="mt-1 flex justify-between font-mono text-[10px] text-slate-400">
        <span>payment {start.slice(5, 16).replace('T', ' ')}</span>
        <span>resolved</span>
        <span>deadline {deadline.slice(5, 10)} 23:59</span>
      </div>
    </div>
  )
}

export default function ResultPanel({ kase, run, live, deciding, onDecide }: {
  kase?: Case
  run: RunState
  live: Snapshot | null
  deciding: boolean
  onDecide: (approve: boolean) => void
}) {
  if (!kase) return <aside className="border-l border-slate-200" />
  const o = run.outcome
  const calls = run.steps.filter((s) => s.kind === 'call')
  const parties = new Set(calls.map((c) => c.party)).size
  const stake = STAKE[kase.id]
  const diffs = changes(run.before, live)

  return (
    <aside className="no-scrollbar min-h-0 space-y-3 overflow-y-auto border-l border-slate-200 bg-white p-4">
      {!o && (
        <>
          {kase.deadline_at ? (
            <section className="rounded-2xl bg-ink p-4 text-white">
              <div className="flex items-center justify-between text-[11px] font-medium uppercase tracking-widest text-slate-400">
                <span>Penalty clock</span>
                <span className="rounded bg-white/10 px-1.5 py-0.5 font-mono normal-case tracking-normal text-slate-300">{kase.rule}</span>
              </div>
              <div className="mt-3 font-mono text-[40px] font-semibold leading-none tracking-tight text-amber-300">
                <Countdown deadline={kase.deadline_at} />
              </div>
              <p className="mt-1.5 text-[12px] text-slate-400">until the deadline · {kase.deadline_at.slice(0, 10)} 23:59 IST</p>
              <div className="mt-4 grid grid-cols-2 gap-2 border-t border-white/10 pt-3 text-[12px]">
                <div><div className="text-slate-400">Penalty so far</div><div className="font-serif text-[26px] leading-tight text-emerald-300">₹0</div></div>
                <div><div className="text-slate-400">After deadline</div><div className="font-serif text-[26px] leading-tight text-rose-300">₹100<span className="font-sans text-[12px] text-slate-400">/day</span></div></div>
              </div>
            </section>
          ) : stake && (
            <section className="rounded-2xl bg-ink p-4 text-white">
              <div className="text-[11px] font-medium uppercase tracking-widest text-slate-400">{stake.title}</div>
              <p className="mt-2 font-serif text-[22px] leading-snug">{stake.text}</p>
            </section>
          )}

          <section className="rounded-2xl border border-slate-200 p-4">
            <h4 className="text-[11px] font-semibold uppercase tracking-widest text-slate-400">{run.phase === 'running' ? 'Agents at work' : 'Without DisputePro'}</h4>
            {run.phase === 'running' ? (
              <div className="mt-3 grid grid-cols-3 gap-2 text-center">
                <Stat v={(run.elapsedMs / 1000).toFixed(1) + 's'} k="elapsed" />
                <Stat v={String(calls.length)} k="API calls" />
                <Stat v={String(parties)} k="parties" />
              </div>
            ) : (
              <ul className="mt-2 space-y-1.5 text-[12.5px] leading-snug text-slate-600">
                {kase.trigger === 'sweep' ? (
                  <>
                    <li>• Surfaces only in the next day’s manual reconciliation</li>
                    <li>• An analyst then checks core banking, NPCI and the other bank by hand</li>
                    <li>• Late fixes pay ₹100/day; late returns lose the chargeback</li>
                  </>
                ) : (
                  <>
                    <li>• Ticket waits in the dispute queue</li>
                    <li>• Analyst logs into 3–4 systems and emails the other bank</li>
                    <li>• Customer chases, escalates, or goes to the Ombudsman</li>
                  </>
                )}
              </ul>
            )}
          </section>
        </>
      )}

      {o && (
        <section className="step-in space-y-4">
          <div className="rounded-2xl border border-emerald-200 bg-gradient-to-b from-emerald-50/80 to-white p-4">
            <Hero o={o} kase={kase} />
          </div>

          {o.status === 'AWAITING_APPROVAL' && (
            <div className="glow-amber rounded-2xl border-2 border-amber-300 bg-amber-50 p-3">
              <p className="text-[12.5px] font-medium text-amber-900">{o.human_reason}. Nothing has moved yet.</p>
              <div className="mt-2.5 flex gap-2">
                <button disabled={deciding} onClick={() => onDecide(true)}
                  className="flex-1 rounded-xl bg-emerald-600 px-3 py-2.5 text-[13px] font-semibold text-white hover:bg-emerald-700 disabled:opacity-50">
                  Approve & execute
                </button>
                <button disabled={deciding} onClick={() => onDecide(false)}
                  className="rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-[13px] font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50">
                  Reject
                </button>
              </div>
            </div>
          )}

          <div className="grid grid-cols-4 gap-1.5 text-center">
            <Stat v={`${o.ops.seconds}s`} k="end to end" />
            <Stat v={String(o.ops.api_calls)} k="API calls" />
            <Stat v={String(o.ops.parties.length)} k="parties" />
            <Stat v={String(o.ops.human_touches)} k="analyst touches" />
          </div>

          <div>
            <h4 className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-slate-400">What the agents did</h4>
            <ul className="space-y-1">
              {o.actions.map((a, i) => (
                <li key={i} className="flex items-center gap-2 rounded-lg border border-slate-200 px-2.5 py-1.5">
                  <span className={`grid h-5 w-5 shrink-0 place-items-center rounded-full ${a.state === 'done' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                    <Icon name={a.state === 'done' ? 'check' : 'guard'} className="h-3 w-3" />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block text-[12.5px] font-medium text-slate-800">{ACTION[a.type] ?? a.type}</span>
                    {a.ref && <span className="block truncate font-mono text-[10px] text-slate-400">{a.ref}</span>}
                  </span>
                  {a.amount_paise > 0 && <span className="font-mono text-[11.5px] font-semibold text-slate-700">{rs(a.amount_paise)}</span>}
                </li>
              ))}
            </ul>
          </div>

          {diffs.length > 0 && (
            <div>
              <h4 className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-slate-400">Changed in live systems</h4>
              <ul className="space-y-1">
                {diffs.map((d) => (
                  <li key={d} className="step-in flex gap-2 text-[12px] text-slate-700">
                    <span className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-500" />{d}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {o.customer_message && (
            <div>
              <h4 className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-slate-400">
                {o.customer_message.startsWith('Ops note') ? 'Ops note' : 'Sent to customer'}
              </h4>
              <p className="rounded-xl bg-slate-50 p-3 text-[12.5px] leading-relaxed text-slate-700">{o.customer_message.replace(/^Ops note: /, '')}</p>
            </div>
          )}
          {o.citation && <p className="text-[10.5px] leading-relaxed text-slate-400">{o.citation}</p>}
        </section>
      )}
    </aside>
  )
}

function Stat({ v, k }: { v: string; k: string }) {
  return (
    <div className="rounded-xl bg-slate-50 px-1 py-2">
      <div className="font-mono text-[16px] font-semibold text-slate-900">{v}</div>
      <div className="text-[10px] leading-tight text-slate-500">{k}</div>
    </div>
  )
}

'use client'

import Link from 'next/link'
import { useCallback, useEffect, useReducer, useRef, useState } from 'react'
import AgentColumn from '@/components/desk/AgentColumn'
import CaseRail from '@/components/desk/CaseRail'
import { OrchestratorBar, PartyBus } from '@/components/desk/Orchestrator'
import ResultPanel from '@/components/desk/ResultPanel'
import { PARTY_STYLE } from '@/components/desk/StepItem'
import { Icon } from '@/components/meta'
import { API_URL, initialRunState, reduceRun, rs, streamEvents, type Case, type Meta, type PartyId, type Snapshot } from '@/lib/run'

const PACES = [
  { id: 'slow', label: 'Slow' },
  { id: 'normal', label: 'Normal' },
  { id: 'fast', label: 'Fast' },
] as const

export default function Desk() {
  const [meta, setMeta] = useState<Meta | null>(null)
  const [cases, setCases] = useState<Case[]>([])
  const [apiError, setApiError] = useState<string | null>(null)
  const [selected, setSelected] = useState('deemed-outward')
  const [pace, setPace] = useState<(typeof PACES)[number]['id']>('normal')
  const [run, dispatch] = useReducer(reduceRun, undefined, initialRunState)
  const [deciding, setDeciding] = useState(false)
  const [live, setLive] = useState<Snapshot | null>(null)
  const [resolved, setResolved] = useState<Record<string, string>>({})
  const abort = useRef<AbortController | null>(null)

  const kase = cases.find((c) => c.id === selected)
  const running = run.phase === 'running'
  const llm = !!meta && meta.brain !== 'rules'

  const loadSnapshot = useCallback(async (c: Case) => {
    const r = await fetch(`${API_URL}/sandbox/snapshot?customer_id=${c.customer_id}&utr=${c.utr}`)
    if (r.ok) setLive(await r.json())
  }, [])

  const loadCases = useCallback(() => fetch(`${API_URL}/api/cases`).then((r) => r.json()).then(setCases), [])

  useEffect(() => {
    Promise.all([fetch(`${API_URL}/api/meta`).then((r) => r.json()), loadCases()])
      .then(([m]) => setMeta(m))
      .catch(() => setApiError(`Can't reach the DisputePro API at ${API_URL}.`))
  }, [loadCases])

  useEffect(() => {
    if (kase && run.phase === 'idle') loadSnapshot(kase)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selected, cases.length])

  const posts = run.steps.filter((s) => s.kind === 'call' && s.http?.method === 'POST' && s.status !== 'running').length
  useEffect(() => {
    if (posts && kase) loadSnapshot(kase)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [posts])

  useEffect(() => {
    const o = run.outcome
    if (!o) return
    if (o.after) setLive(o.after)
    if (o.status !== 'AWAITING_APPROVAL') {
      const label = o.deadline ? `₹0 penalty · ${o.headline.replace(/^(Refunded|Returned) with /, '').replace(' to spare', ' spare')}` : o.headline
      setResolved((r) => ({ ...r, [selected]: label }))
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run.outcome])

  function pick(id: string) {
    if (running) return
    setSelected(id)
    setLive(null)
    dispatch({ type: 'reset', t: 0 })
  }

  async function consume(path: string, body: unknown) {
    abort.current?.abort()
    const ctrl = new AbortController()
    abort.current = ctrl
    try {
      await streamEvents(path, body, dispatch, ctrl.signal)
    } catch (e) {
      if (!ctrl.signal.aborted) dispatch({ type: 'run_failed', t: 0, error: (e as Error).message })
    }
  }

  async function start() {
    dispatch({ type: 'reset', t: 0 })
    await consume('/api/runs', { case_id: selected, pace })
  }

  async function decide(approve: boolean) {
    if (!run.runId) return
    setDeciding(true)
    dispatch({ type: 'resume', t: 0 })
    await consume(`/api/runs/${run.runId}/decision`, { approve })
    setDeciding(false)
  }

  async function resetSandbox() {
    await fetch(`${API_URL}/sandbox/reset`, { method: 'POST' })
    dispatch({ type: 'reset', t: 0 })
    setResolved({})
    await loadCases()
    if (kase) loadSnapshot(kase)
  }

  const stepsOf = (n: string) => run.steps.filter((s) => s.node === n)
  const tok = (n: string) => (run.usage[n] ? run.usage[n].input_tokens + run.usage[n].output_tokens : undefined)
  const partyLabels = Object.fromEntries(
    (Object.keys(PARTY_STYLE) as PartyId[]).map((p) => [p, p === 'bene' ? (live?.bene.bank ?? 'Other bank') : PARTY_STYLE[p].name]),
  ) as Record<PartyId, string>

  return (
    <div className="flex h-screen flex-col bg-white">
      <header className="flex h-14 shrink-0 items-center gap-3 border-b border-slate-200 px-4">
        <Link href="/" className="flex items-center gap-2">
          <span className="grid h-8 w-8 place-items-center rounded-lg bg-gradient-to-br from-violet-600 to-indigo-700 text-white">
            <Icon name="orchestrator" className="h-4 w-4" />
          </span>
          <span className="text-[15px] font-semibold tracking-tight">DisputePro</span>
        </Link>
        <span className="text-[13px] text-slate-300">/</span>
        <span className="text-[13px] font-medium text-slate-600">UPI exceptions desk</span>
        <span className="hidden text-[12px] text-slate-400 md:inline">Sahyadri Bank · sandbox</span>
        {meta && (
          <span title={meta.brain_label} className={`ml-1 hidden items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-medium lg:flex ${
            llm ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-800'}`}>
            <span className={`h-1.5 w-1.5 rounded-full ${llm ? 'bg-emerald-500' : 'bg-amber-500'}`} />
            {llm ? meta.brain_label : 'Agent brain: rules engine (LLM keys not set)'}
          </span>
        )}
        <div className="ml-auto flex items-center gap-2">
          <div className="flex rounded-lg bg-slate-100 p-0.5 text-[12px] font-medium">
            {PACES.map((p) => (
              <button key={p.id} onClick={() => setPace(p.id)} disabled={running}
                className={`rounded-md px-2.5 py-1 ${pace === p.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}>{p.label}</button>
            ))}
          </div>
          <button onClick={resetSandbox} disabled={running} title="Restore every sandbox balance and record"
            className="grid h-8 w-8 place-items-center rounded-lg border border-slate-200 text-slate-500 hover:bg-slate-50 disabled:opacity-40">
            <Icon name="reset" className="h-3.5 w-3.5" />
          </button>
          <button onClick={start} disabled={running || deciding || !kase}
            className="flex h-9 items-center gap-2 rounded-lg bg-ink px-4 text-[13px] font-semibold text-white shadow hover:bg-slate-800 disabled:opacity-60">
            {running ? <><span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-white border-t-transparent" /> Resolving · {(run.elapsedMs / 1000).toFixed(1)}s</>
              : <><Icon name="play" className="h-3.5 w-3.5" /> {run.phase === 'idle' ? 'Resolve with agents' : 'Run again'}</>}
          </button>
        </div>
      </header>
      {apiError && <div className="bg-rose-50 px-4 py-2 text-[12px] text-rose-700">{apiError}</div>}

      <div className="grid min-h-0 flex-1 grid-cols-1 lg:grid-cols-[264px_minmax(0,1fr)] xl:grid-cols-[264px_minmax(0,1fr)_340px]">
        <CaseRail cases={cases} selected={selected} onPick={pick} disabled={running} resolved={resolved} />

        <main className="flex min-h-0 flex-col gap-3 p-4">
          {kase && (
            <section className="flex items-start gap-4">
              <div className="min-w-0 flex-1">
                <h1 className="font-serif text-[28px] leading-tight tracking-tight text-slate-900">{kase.title}</h1>
                <p className="mt-0.5 line-clamp-2 text-[13px] text-slate-500">
                  {kase.trigger === 'sweep'
                    ? <>Flagged by the reconciliation sweep of <b className="font-medium text-slate-700">{kase.settlement_date}</b>. No customer has complained yet.</>
                    : <><b className="font-medium text-slate-700">{kase.customer_name}:</b> <i>“{kase.complaint}”</i></>}
                </p>
              </div>
              <dl className="hidden shrink-0 grid-cols-3 gap-4 text-right md:grid">
                <div><dt className="text-[10px] uppercase tracking-widest text-slate-400">Amount</dt><dd className="font-mono text-[15px] font-semibold">{rs(kase.amount_paise)}</dd></div>
                <div><dt className="text-[10px] uppercase tracking-widest text-slate-400">Our role</dt><dd className="text-[13px] font-medium text-slate-700">{kase.role}</dd></div>
                <div><dt className="text-[10px] uppercase tracking-widest text-slate-400">UTR</dt><dd className="font-mono text-[12px] text-slate-600">{kase.utr}</dd></div>
              </dl>
            </section>
          )}

          <OrchestratorBar state={run.nodes.orchestrator} steps={stepsOf('orchestrator')} tokens={tok('orchestrator')} />

          <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 md:grid-cols-3">
            {(['investigator', 'policy', 'resolver'] as const).map((n) => (
              <AgentColumn key={n} id={n} state={run.nodes[n]} edge={run.edges[`orchestrator>${n}`] ?? 'idle'}
                steps={stepsOf(n)} tokens={tok(n)} llm={llm} waitingHuman={n === 'resolver' && run.phase === 'awaiting'} />
            ))}
          </div>

          <PartyBus steps={run.steps} labels={partyLabels} />
          {run.phase === 'error' && <div className="rounded-xl bg-rose-50 p-3 text-[12px] text-rose-700">Run failed: {run.error}</div>}
        </main>

        <ResultPanel kase={kase} run={run} live={live} deciding={deciding} onDecide={decide} />
      </div>
    </div>
  )
}

